["pln_nmh_90_01"] = "ASANSÖR GELDİ. HADİ MİLLET! ASKERÎ BİRLİKLER OTOPARKTA TOPLANIYOR!",
["pln_nmh_90_02"] = "BU DELİLİK, HASTANENİN ETRAFINI SARMIŞLAR. ÖZEL ASKERÎ BİRLİK GİBİ... PARALI ASKERLER. GİTMENİZ GEREK... HEMEN.",
