["pln_nmh_99_01"] = "MİLLET!... MİLLET! HÂLÂ ORADA MISINIZ?! ÇI... -KIN!",
["pln_nmh_brf_01"] = "MÜŞTERİMİZ, MERCY HOSTPİTAL'IN TECRİT KOĞUŞUNDA TUTULAN BİR HASTADAN KAN ÖRNEĞİ İSTİYOR. İÇERİ GİRİN, GÜVENLİK KAMERALARINI DEVRE DIŞI BIRAKIN, SİVİLLERİ KONTROL ALTINA ALIN VE HASTAYI TESPİT EDEBİLMEM İÇİN HASTA VERİ TABANINA ERİŞMEMİ SAĞLAYIN. BURADA GÜVENLİK ZAYIF, SORUNSUZ VE TEMİZ BİR İŞ OLMALI. BİTİRDİĞİNİZDE SİZİ ÇATIDAN ÇIKARACAĞIM. BİR ARACI ÜZERİNDEN GELEN BU İŞ BİRAZ ŞAİBELİ. İŞİN İÇİNDE ASKERÎ SANAYİYLE BAĞLANTILI KARANLIK BİR ŞİRKET VAR GİBİ AMA RİSKE DEĞER. ÖDEME, GELECEKTE İHTİYACIMIZ OLACAK BİR ŞEY. ÜSTÜNE DE GÜZEL BİR NAKİT İKRAMİYE VAR.",
["pln_nmh_cnc_01"] = "SİZE BİR HASTANE İŞİ VAR. AMELİYATHANE KIYAFETLERİNİZİ GİYİN!",
["pln_nmh_cnc_02"] = "MERCY HOSTPİTAL'DA BİR İŞ VAR. ALIŞILMIŞ İŞLERİMİZDEN DEĞİL. İLGİNÇ OLABİLİR. ",
["pln_nmh_cnc_03"] = "BADEMCİKLERİ KONTROL ETTİRME VAKTİ MİLLET. MERCY HOSPİTAL'A GİDİYORUZ.",
["pln_nmh_end_fail_01"] = "BERBAT BİR İŞTİ.",
["pln_nmh_end_win_01"] = "EVET. PEK DE PLANA GÖRE GİTMEDİ, DEĞİL Mİ? AMA İŞİ YİNE DE BİTİRDİK. MALI HEMEN ELDEN ÇIKARACAĞIM. PARAMIZI ALIR ALMAZ BU İŞİ GETİREN APTALLA BAĞLARI KOPARIYORUM. NE OLDUĞUNU, O PARALI ASKERLERİN KİM OLDUĞUNU ÖĞRENMELİYİZ. İÇİMDEN BİR SES BU İŞİN MEZARINDAN KALKIP PEŞİMİZE DÜŞECEĞİNİ SÖYLÜYOR.",
["pln_pal_01_01"] = "KALIPLAR İÇİN GELDİK. SON AYLARDA SERVET BASIP ÇILGINCA HARCADILAR. SUDA KAN VAR, BİZ DE KÖPEK BALIKLARIYIZ!",
