["pln_pal_21_03"] = "TAMAM, POLİS SANTRALİ HAREKETLENDİ. SANIRIM BİRİ SİZİ GÖRDÜ. HAZIR OLUN!",
["pln_pal_22_01"] = "TAMAM, FARK EDİLMEDEN EPEY İLERLEDİNİZ AMA ARTIK BİTTİ. POLİSLERİN KAYIP OLDUĞU BİLDİRİLDİ, BİR SWAT EKİBİ GÖNDERİYORLAR. PARTİ YENİ BAŞLADI.",
["pln_pal_22_02"] = "O DEVRİYELERİN YOKLUĞU FARK EDİLMİŞ GİBİ. KALABALIK BİR MÜDAHALE EKİBİ GELİYOR. HAZIR OLUN!",
