["pln_pal_24_03"] = "PENSACOLA PD GELİYOR. GÜNEYDEKİ BÜTÜN KIÇ TEKMELEYİCİLERİ DE TOPLAMIŞLAR GİBİ.",
["pln_pal_25_01"] = "SIĞINAĞA GİRİN!",
