["pln_pal_27_03"] = "BUNUN İÇİN LEVYE HARİKA OLURDU.",
["pln_pal_28_01"] = "ÇABUK, O ODAYA GİRİN. KASA'YI GÖRÜYOR MUSUNUZ?",
