["pln_pal_28_03"] = "TAMAM, GANİMET O KAPININ ARKASINDA.",
["pln_pal_28_04"] = "BU KAPIDAN PARA BASKI KALIPLARINA ULAŞABİLİRİZ. ",
["pln_pal_29_01"] = "GÖRÜNÜŞE GÖRE BU BİR FRANZ JAEGER KASASI. O KİLİT MATKAPLA AÇILAMIYOR, KASANIN TAMAMI DA ÇOK SAĞLAM TAKVİYELİ. ESKİDEN BUNLARDAN BİRİNE RASTLAMIŞTIM. KASAYI SUYLA DOLDURUP İÇİNDE BİRAZ C4 PATLATTIK. SU BASINCI, İÇİNDEKİLERE ZARAR VERMEDEN KAPIYI YERİNDEN ATTI.",
["pln_pal_29_02"] = "HEY, BU BİR FRANZ-JAEGER KASASI. BUNU BEKLEMİYORDUM. BU KADAR ZAMANDA AÇMANIN TEK YOLU VAR. SU BASINCI!",
