["pln_pal_brf_01"] = "GÜNEŞ EYALETİ'NE HOŞ GELDİNİZ! KADINLARIN PARA AVCISI, ERKEKLERİN DOLANDIRICI OLDUĞU YERE. KARŞINIZDA BAY MITCHELL: DIŞARIDAN BAKINCA SAYGIN BİR KULÜBÜN GOLF HOCASI. PERDENİN ARKASINDAYSA PROFESYONEL BİR KARA PARA AKLAYICI VE KALPAZAN; USTA BİR SUÇLU. MITCHELL VE SUÇ ORTAĞI WİLSON, MİLYONLARCA PARA BASARKEN GÖZDEN UZAK KALMAYI BAŞARDI. ŞİMDİYE KADAR.",
["pln_pal_cbf_01"] = "ÇANTALARI HAZIRLAYIN, EKİP. BU İŞ MASON-DİXİE'NİN GÜNEYİNDE. PENSACOLA'DAKİ MITCHELL VE WİLSON'IN PEŞİNDEYİZ. İKİ KALPAZAN. BODRUMUNDAN PARA BASMA İŞİ YÜRÜTÜYOR. GİZLİ BİR OPERASYON, ADAMIN İŞİ DE SAĞLAM. O YÜZDEN CİDDİ PARA KALDIRIYOR. BİZ DE PAYIMIZI ALALIM!",
