["pln_pp_bb1_k_01"] = "MÜDÜRÜN OFİSİNE ÇATIDAN ERİŞİLEBİLİR. ANAHTAR KARTLARI İÇİN İYİ YER. BİLGİSAYAR ÖNEMLİ OLABİLİR.",
