["pln_pp_bb1_n_01"] = "TAMAMEN AÇIK ALAN. GÖRÜŞ HATTI ÇOK. KULLANIN AMA DİKKATLİ OLUN. KESKİN NİŞANCILAR BURAYI İYİ GÖRÜYOR.",
["pln_pp_bb1_n_02"] = "BURASI ANA LOBİ. ETKİLEYİCİ. YÜKSEKLİKTEN YARARLANIN AMA DİKKAT EDİN, NEREDE OLURSANIZ OLUN BİR YERE KARŞI AÇIKTA KALACAKSINIZ.",
