["pln_pp_bb1_o_03"] = "PEKÂLÂ, MİNİBÜS SİZİ BURADA BIRAKACAK.",
["pln_pp_hm2_01_01"] = "BODRUMDAKİ SANDIKLAR BANA FİKİR VERDİ. ONLARI KULLANIP COMMİSSAR'IN MEKÂNINA GİZLİCE GİREBİLİRİZ. BUNU BEKLEMEYECEK.",
["pln_pp_hm2_02_01"] = "İÇERİDEKİ ADAMIMIZ EN ÜST KATTA KÜÇÜK BİR KASA DAİRESİ TESPİT ETTİ. HER ŞEY BOKA SARARSA COMMİSSAR ONU PANİK ODASI OLARAK KULLANABİLİR.",
["pln_pp_hm2_03_01"] = "EN ÜST KATTA BİR DAĞ KOKAİN OLDUĞUNU ÖĞRENDİK. SİZİ O ZULADAN UZAK TUTMAK İÇİN HER ŞEYİ YAPARLAR. COMMİSSAR YOK ETMEDEN ULAŞIN. NE DERLER BİLİRSİNİZ: ‘ERKEN KALKAN BİRİNCİ KALİTE MALI KAPAR.’",
["pln_pp_hm2_04_01"] = "COMMİSSAR ACIMASIZ BİR PİÇ OLARAK BİLİNİR. ADAM KAÇIRMA, İŞKENCE VE İNFAZ ONUN ALIŞILDIK YÖNTEMLERİDİR. ETRAFTA BİRKAÇ REHİNE GÖRMENİZ OLASI.",
["pln_pt1_01_01"] = "TAMAM. ADAMI DUYDUNUZ. MAL KEÇİLERİN İÇİNDE, KEÇİLER DE ŞEHİR MERKEZİNİN HER YERİNE DAĞILMIŞ. TOPLAYIN.",
["pln_pt1_01_02"] = "VLAD'IN DEDİĞİ GİBİ... KOKAİN KEÇİLERİN İÇİNDE, KEÇİLER DE... ŞEY, ŞEHİR MERKEZİNİN HER YANINA DAĞILMIŞ. İZLERİNİ SÜRÜN.",
["pln_pt1_01_03"] = "VLAD, SENİ DELİ... TAMAM MİLLET. DURUM BU. BAZEN NÜKLEER BOMBALAR OLUR, BAZEN KEÇİLER. ARAMAYA BAŞLAYIN.",
