["pln_pt1_03_02"] = "BÜTÜN KEÇİLER GÜVENE ALINDI. ŞİMDİ ARABANIZA BİNİP GAZLAYIN ORADAN.",
["pln_pt1_03_03"] = "HEPSİ TAMAM. ARABAYA BİNİP SIVIŞIN!",
["pln_pt1_04_01"] = "EKİP, SIVIŞMA VAKTİ. ARABAYA BİNİN!",
["pln_pt1_04_02"] = "EKİP, KEÇİLERİ ALDINIZ. ŞİMDİ GAZA BASIN!",
["pln_pt1_04_03"] = "BURADAKİ İŞ BİTTİ MİLLET. GİTME VAKTİ! ARABAYA BİNİN!",
["pln_pt1_05_01"] = "KEÇİLERİ TAŞIMAK İÇİN ARABAYI KULLANIRSANIZ DAHA ÇABUK BİTİRİRSİNİZ.",
["pln_pt1_05_02"] = "KEÇİLERİ ARABAYA TAŞIYIN. DÖŞEMEYE SIÇMASINLAR YETER.",
["pln_pt1_05_03"] = "O KEÇİLERİ ÇABUK TOPLAMALISINIZ. ARABAYI KULLANIN!",
