["pln_pt1_06_02"] = "O APARTMANDAKİ KEÇİYİ UNUTMAYIN. ",
["pln_pt1_06_03"] = "ŞURADAKİ APARTMANDA HÂLÂ BİR KEÇİ VAR.",
