["pln_pt1_07_02"] = "BÜTÜN BU DAİRELERDE YANGIN FISKİYESİ VAR. VANAYI ARAYIN YETER.",
["pln_pt1_07_03"] = "BU MEKÂNLARDA YANGIN SÖNDÜRME SİSTEMİ BULUNMASI ZORUNLU. VANAYI BULUN!",
