["pln_pt1_11_02"] = "VANTİLATÖRDE BİR KEÇİ Mİ? BU GÜN GİTTİKÇE TUHAFLAŞIYOR. VANTİLATÖRÜ DURDURMAK İÇİN SİGORTA KUTUSUNU BULUN.",
["pln_pt1_11_03"] = "KEÇİNİN FANIN İÇİNDE OLMASININ İYİ BİR SEBEBİ VARDIR ELBET. SİGORTA KUTUSUNU BULUN YETER. FANI DURDURUN.",
["pln_pt1_12_01"] = "DEVRE KUTUSUNA SIZMAK FANI DURDURACAK.",
["pln_pt1_12_02"] = "DEVRE KUTUSU MUHTEMELEN DIŞARIDA. ONA SIZMAK FANI DURDURACAK.",
