["pln_pt1_13_02"] = "KEÇİLER ELEKTRİĞİ ÇOK İYİ İLETİR. ELEKTRİĞİ KAPATIN.",
["pln_pt1_13_03"] = "O KEÇİNİN ÜZERİNDEN ELEKTRİK AKIMI GEÇİYOR! ELEKTRİĞİ KESİN!",
