["pln_pt1_18_01"] = "BİR TANE DAHA VAR! İSKELEYE SIKIŞMIŞ! DİKKAT! ELEKTRİK VAR GİBİ! ELEKTRİĞİ KESİN!",
["pln_pt1_18_02"] = "EKİP, GÖRÜYOR MUSUNUZ? İSKELEDE BAŞKA BİR KEÇİ! AMA VAY, DİKKAT EDİN! O MERDİVENDE ELEKTRİK VAR GİBİ!",
["pln_pt1_18_03"] = "BAKIN, YUKARIDAKİ İSKELEDE! BİR KEÇİ DAHA. AMA DURUN! MERDİVENE ELEKTRİK VERİLMİŞ GİBİ. ELEKTRİĞİ KESİN!",
