["pln_pt1_19_03"] = "UNUTMAYIN, İSKELEYE SIKIŞMIŞ BİR KEÇİ VAR.",
["pln_pt1_20_01"] = "KEÇİ ELEKTRİK KABLOSUNU KEMİRMİŞ GALİBA. MERDİVENDE ELEKTRİK VAR. ELEKTRİĞİ KESİN!",
["pln_pt1_20_02"] = "O KEÇİ TAM BAŞ BELASI. BİR ŞEKİLDE ELEKTRİĞİ AÇMIŞ. ELEKTRİK KUTUSUNDAN KAPATIN.",
["pln_pt1_20_03"] = "KEÇİ MERDİVENE ELEKTRİK VERMEYİ BAŞARMIŞ. KESMEK İÇİN ELEKTRİK PANOSUNU ARAYIN.",
