["pln_pt1_21_02"] = "MERDİVENDE ELEKTRİK VAR. ELEKTRİK KUTUSUNDAN KAPATIN!",
["pln_pt1_21_03"] = "MERDİVENİ KULLANMAK İÇİN ELEKTRİK KUTUSUNU HALLETMELİSİNİZ!",
["pln_pt1_22_01"] = "O DÜKKÂNIN İÇİNE BAKIN. KEÇİLERİMİZDEN BİRİ DALMIŞ OLABİLİR. MATKAPLA AÇIN!",
["pln_pt1_22_02"] = "KEÇİ DÜKKÂNA GİRMİŞTİR DİYE TAHMİN EDİYORUM. KAPIYI MATKAPLA AÇIN!",
["pln_pt1_22_03"] = "ŞU DÜKKÂN ARANACAK İYİ BİR YER GİBİ. KAPIYI MATKAPLA DELİN, EKİP!",
["pln_pt1_23_01"] = "DÜKKÂNIN İÇİNDE BİR KEÇİ OLDUĞUNA OLDUKÇA EMİNİM. KAPIYA BİR MATKAP TAKIN!",
