["pln_pt1_23_03"] = "DÜKKÂNI UNUTMAYIN. KAPIYI MATKAPLA AÇIN. PAYIMA BAHSE GİRERİM, İÇERİDE KEÇİ VAR.",
["pln_pt1_24_01"] = "İŞ BAŞINDAYIZ! KEÇİ BULMA İŞİ!",
