["pln_pt1_24_03"] = "İÇERİDEYİZ. ŞİMDİ O KEÇİNİN PEŞİNE DÜŞÜN!",
["pln_pt1_25_01"] = "O KEÇİ YUKARI TIRMANIP MAHSUR KALMIŞ. AŞAĞI İNDİRMELİYİZ. SOKAK LAMBASINI KESİN!",
["pln_pt1_25_02"] = "O KEÇİYİ GÜZEL SÖZLERLE, ÖDÜL MAMALARIYLA AŞAĞI İNDİREMEZSİNİZ. SOKAK LAMBASINI TESTEREYLE KESİN!",
