["pln_pt1_28_03"] = "POLİSLER KEÇİLERİ KURTARIYOR! VERGİLERİMİZ BUNA MI GİDİYOR!?",
["pln_pt1_brf_01"] = "BU HONDURAS KARTELİNİN ŞEHİR MERKEZİNDEN MAL TAŞIYAN BİR KAMYONU VAR. VLAD ONA SALDIRI AYARLADI. BİZ TEMİZLİKTEYİZ. SONRADAN GİRİP MALIN ÇIKARILMASINI SAĞLAYACAĞIZ. SAHADAKİ KUVVETLER BİZİZ, ANLIYOR MUSUNUZ? ",
