["pln_pt2_14_02"] = "TAMAM EKİP. AYNI ŞEY. ÇIKIP KAFESİ KURUN.",
["pln_pt2_14_03"] = "ÖNCEKİ GİBİ EKİP. O KAFESİ HAZIRLAYIN.",
