["pln_pt2_16_01"] = "HADİ EKİP. ŞİMDİ SIÇMAYIN. ARABAYI ALIP YOLA ÇIKIN!",
["pln_pt2_16_02"] = "MİLLET! BURADAKİ İŞİMİZ BİTTİ. ARABANIZA BİNİP GAZA BASIN!",
["pln_pt2_16_03"] = "NİYE HÂLÂ ORADASINIZ? HADİ, ARABAYA BİNİP GAZI KÖKLEYİN!",
["pln_pt2_17_01"] = "HOP, HERKESİN ARABAYA BİNMESİNİ BEKLEYİN!",
["pln_pt2_17_02"] = "HERKES! ARABAYA! HEMEN!",
["pln_pt2_17_03"] = "DURUN, DURUN. HERKES ARABAYA BİNENE KADAR BEKLEYİN.",
