["pln_pt2_18_02"] = "ARABAYA GERİ BİNİN! SÜRME VAKTİ!",
["pln_pt2_18_03"] = "ARABADA KALIN LAN!",
["pln_pt2_19_01"] = "KAÇIŞINIZ HAZIR. YOLUN AZ İLERİSİNDE KÖPRÜ VAR, TWITCH DİĞER TARAFTA KAMYONLA BEKLİYOR. DOĞRUCA KAMYONUN İÇİNE SÜRÜN, İŞ BİTTİ!",
["pln_pt2_19_02"] = "TAMAM, DİNLEYİN. TWITCH İLERİDE, KÖPRÜNÜN HEMEN DİĞER TARAFINDA BEKLİYOR. KAMYONU VAR. DOĞRUDAN İÇİNE SÜRÜN, BU İŞ BİTSİN.",
["pln_pt2_19_03"] = "TAMAM, İYİ DİNLEYİN. KAÇIŞ ŞÖYLE. İLERİDEKİ KÖPRÜYÜ GEÇİNCE TÜNELDE BİR KAMYON GÖRECEKSİNİZ. O TWITCH. ARABAYI DOĞRUDAN KAMYONUN İÇİNE PARK EDİN, BU DOSYAYI KAPATALIM.",
["pln_pt2_20_01"] = "KURNAZ POLİSLER KÖPRÜYÜ KAPATTI. KONTROL ODASINA GİDİP GERİ ÇEVİRİN.",
["pln_pt2_20_02"] = "LANET OLSUN, POLİSLER KÖPRÜYÜ ÇEVİRDİ! ŞURADAKİ KONTROL ODASINA GİRİP GERİ DÖNDÜRÜN. ÖBÜR TARAFTA OLMANIZ GEREK!",
["pln_pt2_20_03"] = "AH! POLİSLER KÖPRÜYÜ ÇEVİRMİŞ! TAMAM, BİRİNİZ KONTROL ODASINA GİRİP GERİ ÇEVİRSİN. ÖBÜR TARAFA GEÇMELİYİZ!",
["pln_pt2_21_01"] = "TAMAM, KÖPRÜ GERİ DÖNÜYOR. LANET, NE KADAR YAVAŞ! POLİSLERİ UZAK TUTUN!",
["pln_pt2_21_02"] = "TAMAM, KÖPRÜ GERİ DÖNÜYOR. AMA BİRKAÇ DAKİKA SÜRER. POLİSLERİ OYALAYIN EKİP!",
["pln_pt2_21_03"] = "PEKİ. TAMAM. KÖPRÜ ŞİMDİ GERİ DÖNÜYOR. AMA BİRKAÇ DAKİKA SÜRECEK. HAYATTA KALIN EKİP!",
["pln_pt2_22_01"] = "POLİSLER KÖPRÜYÜ DURDURDU. DÖNDÜRMEYE DEVAM ETMEK İÇİN KONTROLLERİ KULLANIN!",
["pln_pt2_22_02"] = "KAHRETSİN! POLİSLER KÖPRÜYÜ DURDURDU. BİRİNİZ İÇERİ GİRİP TEKRAR BAŞLATSIN!",
["pln_pt2_22_03"] = "AH SİKTİR, POLİS KÖPRÜNÜN DÖNÜŞÜNÜ DURDURDU. YENİDEN BAŞLATMAK GEREK. BİRİNİZ İLGİLENSİN!",
["pln_pt2_23_01"] = "KÖPRÜYÜ ESKİ KONUMUNA GETİRMEK İÇİN KONTROL ODASINDAKİ DÜĞMEYİ KULLANIN.",
["pln_pt2_23_02"] = "KONTROL ODASI KÖPRÜYÜ YÖNETİYOR. İÇERİDEKİ DÜĞMELERİ KULLANIN!",
["pln_pt2_23_03"] = "ŞU KONTROL ODASINI GÖRÜYOR MUSUNUZ? KÖPRÜYÜ ORADAN SIFIRLAYABİLİRSİNİZ.",
["pln_pt2_24_01"] = "KÖPRÜ YERİNE GELDİ! SONUNDA. ŞİMDİ HERKES ARABAYA BİNİP TÜYSÜN!",
["pln_pt2_24_02"] = "TAMAM! KÖPRÜ YERİNE DÖNDÜ! ŞİMDİ ARABAYA BİNİP DEFOLUN ORADAN!",
["pln_pt2_24_03"] = "GÜZEL! KÖPRÜ DÜZELDİ! ŞİMDİ ARABAYA MİLLET! BURAYI GERİDE BIRAKMA VAKTİ!",
["pln_pt2_25_01"] = "TWITCH'İN KAMYONU İLERİDE. DOĞRUDAN KASASINA SÜRÜN!",
["pln_pt2_25_02"] = "KAMYONU HER AN GÖRECEKSİNİZ. İÇİNE SÜRÜN YETER, İŞİMİZ BİTECEK!",
["pln_pt2_25_03"] = "KAMYON YAKLAŞIYOR. GAZA BASIP İÇİNE SÜRÜN YETER!",
["pln_pt2_brf_01"] = "TAMAM, SANIRIM EN KÖTÜSÜ GERİDE KALDI. VLAD'IN ŞOFÖRÜ KEÇİLERİ ŞEHİR DIŞINDAKİ BİR ÇİFTLİĞE GÖTÜRDÜ. PAKETLERİ ÇIKARMAYA HAZIRLAR. ORALARDA BEKLEYİN. ÇEVREYİ GÖZLEYİN. KOLAY İŞ, DEĞİL Mİ?",
["pln_rat_stage1_01_any_01"] = "EVE GİRİP HECTOR'IN AŞÇILARINI BULMAYA ÇALIŞIN.",
["pln_rat_stage1_02_any_01"] = "EVE GİRİN.",
["pln_rat_stage1_03_any_01"] = "UNUTMAYIN, EN AZ DÖRT ÇANTA METAMFETAMİN LAZIM.",
["pln_rat_stage1_04_any_01"] = "NE!? MENDOZA KARTELİ HÂLÂ ORADA! HALLEDİN ONLARI!",
["pln_rat_stage1_05_any_01"] = "BAŞKA KİMSE OLMADIĞINDAN EMİN OLUN.",
["pln_rat_stage1_06_any_01"] = "GÖRÜNÜŞE GÖRE HECTOR'IN AŞÇILARI ÖLMÜŞ. METİ KENDİMİZ YAPMALIYIZ!",
["pln_rat_stage1_07_any_01"] = "ACELE ETMELİYİZ! POLİSİN TELSİZİ DELİ GİBİ ÖTÜYOR. ÇOKTAN YOLA ÇIKMIŞLAR!",
["pln_rat_stage1_08_any_01"] = "TAMAM, İŞLEM BAŞLADI, PİŞİYOR. HECTOR ARACILIĞIYLA BİR UZMANLA BAĞLANTIM VAR. SİZE ADIM ADIM YOL GÖSTERECEĞİM.",
["pln_rat_stage1_09_any_01"] = "HİÇBİR SWAT EKİBİNİN LABORATUVARA GİRMESİNE İZİN VERMEYİN. NE PAHASINA OLURSA OLSUN UZAK TUTUN!",
["pln_rat_stage1_10_any_01"] = "GELİYORLAR MİLLET. ÇEVRENİZİN HER YERİ HELİKOPTER VE SWAT MİNİBÜSÜ DOLU. TETİKTE OLUN!",
["pln_rat_stage1_11_any_01"] = "SWAT KERESTE FABRİKASINDAN GELİYOR. UZAK TUTUN!",
["pln_rat_stage1_11_any_02"] = "GELİYORLAR! KERESTE FABRİKASINDAN! TETİKTE OLUN!",
["pln_rat_stage1_11_any_03"] = "KERESTE FABRİKASINDAN GELİYORLAR, DİKKAT EDİN!",
["pln_rat_stage1_12_any_01"] = "DEMİRYOLU KÖPRÜSÜNDEN GELİYORLAR! DİKKAT EDİN!",
["pln_rat_stage1_12_any_02"] = "DEMİRYOLU KÖPRÜSÜ! DEMİRYOLU KÖPRÜSÜNDEN GELİYORLAR, UZAK TUTUN ONLARI.",
["pln_rat_stage1_12_any_03"] = "KERESTE FABRİKASINDAN SWAT EKİPLERİ GELİYOR, UZAK TUTUN ONLARI!",
["pln_rat_stage1_13_any_01"] = "YOLUN YANINDAKİ ORMANDAN SWAT GELİYOR, DİKKATLİ OLUN!",
["pln_rat_stage1_13_any_02"] = "YOLUN YANINDAKİ ORMANDAN GELİYORLAR! UZAK TUTUN!",
["pln_rat_stage1_14_any_01"] = "DİKKATLİ OLUN! KESKİN NİŞANCILAR GELİYOR!",
["pln_rat_stage1_15_any_01"] = "ONLARI UZAK TUTTUNUZ. GÜZEL İŞ! AMA GERİ ÇEKİLMİYORLAR, DAHA FAZLASINA HAZIR OLUN.",
["pln_rat_stage1_15_any_02"] = "AFERİN! PİŞİRMEYE DÖNÜN. DALGALAR ARASINDAKİ SÜREYİ DAHA FAZLA MALZEME BULMAK İÇİN KULLANIN.",
["pln_rat_stage1_16_any_01"] = "MALZEME GEREKECEK. ETRAFI ARAŞTIRIN, BAKALIM NE BULABİLECEKSİNİZ.",
["pln_rat_stage1_17_any_01"] = "BİR MALZEME EKLEMENİZ GEREKİYOR, YANLIŞ OLANI KULLANMADIĞINIZDAN EMİN OLUN. TEK BİR YANLIŞ ADIMDA LABORATUVAR NOEL AĞACI GİBİ ALEV ALIR.",
["pln_rat_stage1_18_any_01"] = "DİKKATLİ OLMAYI UNUTMAYIN! YANLIŞ MALZEMEYİ KULLANAMAYIZ. DİKKATLİ OLMANIZ GEREK!",
["pln_rat_stage1_19_any_01"] = "İŞLEMİN DEVAM ETMESİ İÇİN TUZ RUHU EKLEMENİZ GEREKİYOR!",
["pln_rat_stage1_20_any_01"] = "İŞLEMİ SÜRDÜRMEK İÇİN TUZ RUHU EKLEYİN!",
["pln_rat_stage1_21_any_01"] = "İŞLEMİN SÜRMESİ İÇİN KOSTİK SODAYI EKLEMELİSİNİZ!",
["pln_rat_stage1_22_any_01"] = "İŞLEME DEVAM ETMEK İÇİN KOSTİK SODA EKLEYİN!",
["pln_rat_stage1_23_any_01"] = "İŞLEMİ SÜRDÜRMEK İÇİN HİDROJEN KLORÜR EKLEMENİZ GEREK!",
["pln_rat_stage1_24_any_01"] = "İŞLEME DEVAM ETMEK İÇİN HİDROJEN KLORÜR EKLEYİN!",
["pln_rat_stage1_25_any_01"] = "GÜZEL, DEVAM EDİYOR. GÖZÜNÜZ AÇIK OLSUN, SAVUNMAYA DEVAM EDİN...",
["pln_rat_stage1_26_any_01"] = "VAY! MİLLET? İYİ MİSİNİZ? DİKKATLİ OLUN DEMİŞTİM!",
["pln_rat_stage1_26_any_02"] = "AH, NE!? MİLLET, O MADDELERE DİKKAT ETMELİSİNİZ, SİZE SÖYLEDİM!",
["pln_rat_stage1_27_any_01"] = "LABORATUVARI ARTIK KULLANAMAYIZ, GİTTİ. ELİNİZDEKİNİ ALIN DA GİDELİM.",
["pln_rat_stage1_28_any_01"] = "İŞLEM TAMAMLANDI! ÇANTALAYIN DA BİR TUR DAHA YAPALIM.",
["pln_rat_stage1_29_any_01"] = "ÇANTALARI GÜVENE ALMAK İÇİN MİNİBÜSE GÖTÜRÜN. POLİSLERİN ALIN TERİYLE PİŞİRDİĞİNİZ METAMFETAMİNİ KAÇIRMASINA İZİN VERMEYİN!",
["pln_rat_stage1_30_any_01"] = "AFERİN. DÖRT ÇANTA GİDİP TAKAS YAPMAK İÇİN YETERLİ.",
["pln_rat_stage1_31_any_01"] = "HARİKA! BÜTÜN O ÇANTALARLA TAKAS SORUNSUZ GEÇER.",
["pln_rat_stage1_32_any_01"] = "MİLLET, BEKLEDİĞİMİZDEN AZ ÇANTA VAR AMA YİNE DE TAKASI YAPIP BİLGİYİ VERMELERİNİ UMABİLİRİZ.",
["pln_rat_stage1_33_any_01"] = "HİÇ ÇANTA YOK MU!? BU TAKAS BİZİM İÇİN İYİ OLMAYACAK. UMARIM TAKAS İÇİN KOLUNUZDA BİRKAÇ NUMARA VARDIR.",
["pln_rat_stage1_34_any_01"] = "İYİ DÜŞÜNDÜNÜZ! O TAHTALARLA DAHA FAZLA PENCEREYE BARİKAT KURUN.",
["pln_rat_stage1_brief_01"] = "HECTOR'I DUYDUNUZ. OYALANACAK VAKİT YOK. METAMFETAMİN LABORATUVARINA GİRİP MALLARI GÜVENCEYE ALACAĞIZ.",
["pln_rat_stage1_brief_01b"] = "POLİSİN GELMESİNE DE FAZLA KALMADIĞINDAN EMİNİM. YAŞADIĞIMIZ BU MUHTEŞEM ŞANSSIZLIK SİLSİLESİNE GAYET UYUYOR.",
["pln_rat_stage1_end_a_01"] = "METİ ÇIKARMAKTA İYİ İŞ YAPTINIZ. PEK KOLAY BİR İŞ DEĞİLDİ. LABORATUVARI KİM İSPİYONLADIYSA HECTOR ONUNLA İYİCE İLGİLENECEKTİR. ",
["pln_rat_stage1_end_a_02"] = "O EV ALEVLER İÇİNDE. MALI HECTOR'A GÖTÜRÜP PARAMIZI ALALIM. ACABA MAVİYE NE KADAR VERİR?",
["pln_rat_stage1_end_a_03"] = "SICAĞA DAYANAMIYORSANIZ MUTFAKTAN ÇIKIN, HA? İYİ İŞ. HECTOR'LA ANLAŞMAYA YETECEK METAMFETAMİNİMİZ VAR. ŞEHRE DÖNELİM.",
["pln_rat_stage1_end_b_01"] = "SİZ PİŞİRMEYİ BİLİYORSUNUZ! HECTOR HANGİNİZİN HEİSENBERG OLDUĞUNU MERAK EDİYOR.",
["pln_rat_stage1_end_b_02"] = "EKİBİMİN HEPSİ USTA AŞÇI. O PİŞİRİMDEN O KADAR ÇOK MAL ÇIKARDINIZ Kİ HEPİMİZ İYİCE YOLDAN ÇIKIP BUNU TAM ZAMANLI YAPMALIYIZ!",
["pln_rat_stage1_end_b_03"] = "ANLAŞMA TAMAM MİLLET. KRALİYET AİLESİNİ UTANDIRACAK KADAR KRİSTAL ÜRETTİNİZ. HECTOR'UN KAFASI UÇMUYORSA SİZE METHİYELER DÜZECEK. İYİ İŞ.",
["pln_rat_stage1_end_c_01"] = "LANET OLSUN. TAKASA YETECEK MALIMIZ YOK, ZOR DURUMDAYIZ DEMEK. SESSİZCE HECTOR'A GİDELİM. BAKALIM NE OLACAK.",
["pln_rat_stage1_end_c_02"] = "MALIMIZ EKSİK. BENCE ŞİMDİLİK HECTOR'A SÖYLEMESEK DAHA İYİ. BELKİ SORUNU BAŞKA YOLDAN ÇÖZERİZ. ",
["pln_rat_stage1_end_c_03"] = "BİRAZ EKSİK KALDIK. ŞİMDİLİK OYUNA UYUP HECTOR'IN KÖSTEBEK SORUNUNU BAŞKA TÜRLÜ ÇÖZMEYE ÇALIŞALIM. YARATICIYIZ...",
["pln_rat_stage1_intro_a_01"] = "DÜMDÜZ İLERİDE SAĞDA ESKİ, İKİ KATLI BİR EV GÖRECEKSİNİZ. SÜRPRİZ SÜRPRİZ, PİŞİRME MERKEZİ BURASI.",
["pln_rat_stage1_intro_a_01b"] = "GİRİN, HECTOR'IN AŞÇILARINI KURTARIN, BAŞKA BİR ŞEY TERS GİTMEDEN UYUŞTURUCULARI ÇIKARIN.",
["pln_rat_stage1_intro_a_02"] = "LABORATUVAR, TABİİ BÖYLE BİR DÖKÜNTÜYE LABORATUVAR DENİRSE, TAM İLERİDE. İÇERİ GİRİN, MENDOZA'NIN ASKERLERİNE DİKKAT EDİN.",
["pln_rat_stage1_intro_a_02b"] = "HA EVET, FBI GELMEDEN METİ ÇIKARIN. BİRİLERİ İHBAR ETMİŞ. ZATEN ŞANSINIZ YETERİNCE YAVER GİTMİYORMUŞ GİBİ.",
["pln_rat_stage1_intro_a_03"] = "MENDOZA'NIN ADAMLARI ORADA PİŞİRİYOR. ONLARI TEMİZLEYİP HECTOR'IN METİNİ GERİ ALIN. MALI ALINCA BURADAN ÇIKABİLİRSİNİZ. BAŞLAYIN.",
["pln_rat_stage1_intro_a_04"] = "DOSTUM, ŞU KEŞ YEMİNİN KOKUSUNU BURADAN ALDIĞIMA YEMİN EDEBİLİRİM. METAMFETAMİN LABORATUVARINDAYIZ. FBI GELMEDEN GİRİP ÜÇ ÇUVAL ÜRÜN KAPIN. HECTOR NE İSTERSE HECTOR ALIR. ŞİMDİLİK EN AZINDAN.",
["pln_rat_stage2_brief_01"] = "TAMAM MİLLET, HECTOR'LA KONUŞTUM. MENDOZA'NIN İLERİ GELENLERİ ÜLKEDEN KAÇIYOR AMA HECTOR HENÜZ GİTMELERİNE RAZI DEĞİL. NEREYE GİTTİKLERİNİ ÖĞRENMEK İSTİYOR. ",
["pln_rat_stage2_brief_01b"] = "İÇLERİNDEKİ BİR KÖSTEBEK ONLARI COBRAS SOKAK ÇETESİNE SATMIŞ. ÖYLE AZILI PİÇLER Kİ HECTOR'IN ADAMLARI BİLE ONLARLA İŞ YAPMIYOR. SİZ BURADA DEVREYE GİRİYORSUNUZ... BİLGİ KARŞILIĞINDA ONLARLA METAMFETAMİN TAKAS EDİN.",
["pln_rat_stage2_end_a_01"] = "KOLAY OLDU. İYİ İŞ. NE YAZIK Kİ HECTOR AZ ÖNCE FBI'IN KALAN MENDOZA'LARI YAKALADIĞINI, KONVOYLA HAVAALANINA GÖTÜRDÜĞÜNÜ SÖYLEDİ. YANİ FAZLA VAKTİMİZ YOK.",
["pln_rat_stage2_end_a_02"] = "DEMEK KAFAYI BULMAK ONLAR İÇİN BİLGİDEN ÖNEMLİYMİŞ. MÜPTELALAR SOYUT KAVRAMLARDAN PEK ANLAMAZ. BU SIRADA MENDOZA'LAR KİRALIK BİR OTOBÜSLE HAVAALANINA GİDİYOR, GİZLİ FBI AJANLARI EŞLİĞİNDE. ",
["pln_rat_stage2_end_a_02b"] = "EVET. DEMEK Kİ YAPACAK ÇOK İŞİMİZ VAR...",
["pln_rat_stage2_end_b_01"] = "MİLLET... MİLLET... MİLLET. BİLGİ ALMAMIZ GEREKİYORDU... SADECE PARA DEĞİL. HECTOR BENİ CANLI CANLI YÜZECEK.",
["pln_rat_stage2_end_b_01b"] = "ŞİMDİ BİLGİ OLMADAN GİRİP HAVAALANINA GİDEN MENDOZA'LARI İNDİRMENİZ GEREKİYOR, TAMAM MI? LÜTFEN DERDİM AMA LÜTFEN DEMEM.",
["pln_rat_stage2_end_c_01"] = "O KALLEŞLER... NEYSE, BİZİMLE PAPAZ OLMANIN GENELDE KARŞI TARAF İÇİN ÇOK KÖTÜ SONUÇLANDIĞINI GÖSTERDİNİZ.",
["pln_rat_stage2_end_c_01b"] = "MENDOZA'LAR HAVAALANINA GİDİYOR. O EVRAK ÇANTASINI GETİRİN. EMİNİM ONUNLA YAPACAK BİR ŞEY BULURUZ.",
["pln_rat_stage2_end_d_01"] = "YİNE BAĞDAT GİBİYDİ. GİTMELİSİNİZ. HECTOR HAVAALANINA GİDEN MENDOZA'LARIN İZİNİ BULDU. KONVOYLARINI ON TONLUK BALYOZ GİBİ VURACAĞIZ.",
["pln_rat_stage2_end_d_02"] = "NAKİT YOK, BİLGİ YOK. BUNA ISKALADIK DERİM. GÖTÜMÜ ATEŞTEN KURTARMAZSANIZ HECTOR ÇOK MUTSUZ OLACAK. ÇOK ŞEY İSTEDİĞİMİ BİLİYORUM.",
["pln_rat_stage2_end_e_01"] = "BU... ÇOK PARA. GALİBA ARTIK MET TİCARETİNDEYİZ. AMA O BİLGİ GERÇEKTEN LAZIMDI. HATIRLADINIZ MI? HAZIRLANIN, BİLGİ OLSA DA OLMASA DA O PİSLİKLERİ ALALIM.",
["pln_rat_stage2_intro_a_01"] = "TAMAM, UNUTMAYIN, BARIŞÇIL KALMALI. METAMFETAMİNİ BİLGİYLE, FAZLASINI PARAYLA TAKAS EDİN. KOLAY VE TEMİZ, KAN DÖKMEDEN AYRILIN. ",
["pln_rat_stage2_intro_a_01b"] = "MENDOZA'LAR ÜLKEDEN UÇUP GİTMEDEN YETİŞMEMİZ GEREK.",
["pln_rat_stage2_intro_a_02"] = "MENDOZA'LAR JETLE KAÇMAK ÜZERE. BU MALI ONLAR HAKKINDA BİLGİYLE TAKAS ETMELİYİZ. BU ADAMLAR PİSLİK AMA ONLARLA UĞRAŞMAK İSTEMEZSİNİZ. ",
["pln_rat_stage2_intro_a_02b"] = "ŞU BİR SEFERLİK KENDİNİZİ TUTUN DA TAKASI SESSİZCE YAPIN. TAMAM MI? TAMAM.",
["pln_rat_stage2_intro_a_03"] = "BİLGİLERİ BİR EVRAK ÇANTASINDA YA DA BENZER BİR ŞEYDE OLACAK. TAKASI YAPIN VE BİLGİYİ SİZE TESLİM ETMELERİNİ SAĞLAYIN. BU ADAMLAR PİSLİĞİN TEKİ, GÖZÜNÜZÜ AÇIK TUTUN.",
["pln_rat_stage2_intro_a_03b"] = "BİTİRELİM GİTSİN, UMARIM KAN DÖKMEDEN. ÖNÜMÜZDE ONDAN YETERİNCE VAR.",
["pln_rat_stage3_01_any_01"] = "KONVOY DURDU, OTOBÜSE DOĞRU İLERLEYİN.",
["pln_rat_stage3_02_any_01"] = "UNUTMAYIN, SIÇANIN PEŞİNDEYİZ. OTOBÜSE GİDİN, BAŞINIZI EĞİN, SİPERDEN SİPERE İLERLEYİN.",
["pln_rat_stage3_03_any_01"] = "HER YER AĞIR FBI BİRLİKLERİYLE DOLU, DİKKATLİ OLUN.",
["pln_rat_stage3_04_any_01"] = "OTOBÜS BU, HEPSİNİ İNDİRİN.",
["pln_rat_stage3_05_any_01"] = "PARA SİZİN, ALIN. ŞİFRELER ELİNİZDEYSE DÖŞENMİŞ C4'LERİ ETKİSİZ HÂLE GETİREBİLİRSİNİZ.",
["pln_rat_stage3_06_any_01"] = "GANİMETİ YÜKLEMENİZ İÇİN SİZE HELİKOPTER GÖNDERİYORUM. YAKINDA, FAZLA SÜRMEZ. DAYANIN.",
["pln_rat_stage3_07_any_01"] = "O C4'ÜN ETRAFINDA DİKKATLİ OLUN MİLLET.",
["pln_rat_stage3_08_any_01"] = "OTOBÜS PATLADI! DİKKATLİ OLUN, ATEŞTEN UZAK DURUN!",
["pln_rat_stage3_08_any_02"] = "AH HAYIR! PATLADI, DİKKAT EDİN! O ATEŞTEN UZAK DURUN!",
["pln_rat_stage3_09_any_01"] = "HELİKOPTER ORADA, ÇANTALARI İÇİNE ATIN.",
["pln_rat_stage3_10_any_01"] = "AFERİN, SIÇAN ÖLDÜ, KAÇIŞ HELİKOPTERİ BEKLİYOR. OTOBÜSTEKİ PARAYI ALMAK İSTEMİYORSANIZ HELİKOPTERE GİDİN DE SİZİ ORADAN ÇIKARALIM.",
["pln_rat_stage3_11_any_01"] = "POLİS TELSİZİNİ DUYUYORUM, KOLLUK KUVVETLERİ YOLDA. 30 SANİYE İÇİNDE VARACAKLAR.",
["pln_rat_stage3_12_any_01"] = "POLİS VE SWAT GELDİ, DİKKATLİ OLUN!",
["pln_rat_stage3_13_any_01"] = "O HELİKOPTERE DİKKAT EDİN. POLİSLERİN CİDDİ HASAR VEREBİLECEĞİ KADAR YAKINDA.",
["pln_rat_stage3_brief_01"] = "MEĞER FBI, MENDOZA'LARA ÜLKE DIŞINA KADAR EŞLİK EDİYORMUŞ. BELKİ ANLAŞMALARI VARDIR, BELKİ YOKTUR. AÇIKÇASI GİZLİCE TESLİM Mİ EDİYORLAR, NE YAPIYORLARSA HİÇ UMURUMDA DEĞİL. ",
["pln_rat_stage3_brief_01b"] = "BÜTÜN LİDERLER O OTOBÜSTE, PARALARI DA YANLARINDA. PARAYI ALIN, MENDOZA'NIN ÜST DÜZEY ADAMLARINI ÖLDÜRÜP BU HİKÂYEYİ BİTİRİN. HELİKOPTERLE GİRECEĞİZ.",
["pln_rat_stage3_end_a_01"] = "OTOBÜSÜ MENDOZA'LARDAN TERTEMİZ ETTİNİZ. MALLARIYLA BİRLİKTE ALEVLER İÇİNDE GERÇEK BİR VİKİNG CENAZESİ.",
["pln_rat_stage3_end_a_02"] = "ARTIK MENDOZA YOK. ONLARA GERÇEK BİR VİKİNG CENAZESİ YAPTINIZ AMA VİKİNG DEĞİLLER. ÜZÜCÜ.",
["pln_rat_stage3_end_a_03"] = "PARA VE MENDOZA'LAR ALEVLER İÇİNDE. MESAJI VERDİNİZ, HECTOR BUNU SEVECEK. PARA GELİYOR.",
["pln_rat_stage3_end_b_01"] = "BU MESAJI KİMSE KAÇIRMAYACAK. FBI SİZİ HER YERDE ARAYACAK AMA MERAK ETMEYİN... BEN HALLEDERİM. HARİKA İŞ.",
["pln_rat_stage3_end_b_02"] = "MENDOZA MANGALI GÜRÜLTÜLÜ BİR BAŞARIYDI. HECTOR'I GÖRME VAKTİ.",
["pln_rat_stage3_end_c_01"] = "HARİKA İŞ MİLLET. MENDOZA'LARIN İŞİ BİTTİ, NAKİTLERİ DE HELİKOPTERİMİZDE ÖN KOLTUKTA. TATLI.",
["pln_rat_stage3_end_c_02"] = "OH BE, BU İŞİ KUSURSUZ YAPTINIZ. HECTOR'LA ARAMIZDA NE SORUN VARSA ARTIK DÜZELDİ. HATTA KENDİMİ ZAFER PUROSU YAKACAK KADAR RAHAT HİSSEDİYORUM.",
["pln_rat_stage3_end_c_03"] = "BÜYÜK VURGUN MİLLET. BAKALIM HECTOR BİZE BİR PARTİ VERECEK Mİ?",
["pln_rat_stage3_intro_a_01"] = "EKİP, MENDOZA'NIN DC OPERASYONLARINI BURADA VE ŞİMDİ BİTİRİYORUZ. O OTOBÜSÜ SERT VURUP PARALARINI ALIN. HECTOR SADECE BU PALYAÇOLARIN BİTMESİNİ İSTİYOR, PARA BİZİM. İNİŞE 3, 2, 1, GİDİN!",
["pln_rat_stage3_intro_a_02"] = "TAMAM, HELİKOPTER ŞİMDİ KONVOYUN ÜSTÜNE GELİYOR, KÖPRÜDEYİZ. İYİ İŞ ALEX... SONUNDA... VURUN VE BİTİRİN. NE OLURSA OLSUN PARA BİZİM. HALLEDİN.",
["pln_rat_stage3_intro_a_03"] = "TAMAM, MENDOZA OTOBÜSÜ KÖPRÜDE. DEMEK ON DAKİKA İÇİNDE İNİP İŞİNİ BİTİRECEĞİZ. OTOBÜSÜ VURUN, ADAMLARINI ÖLDÜRÜN, PARAYI ALIN. BASİT.",
["pln_rats_stage1_01_any_01"] = "EVE GİRİP HECTOR'IN AŞÇILARINI BULMAYA ÇALIŞIN.",
["pln_rats_stage1_02_any_01"] = "EVE GİRİN.",
["pln_rats_stage1_03_any_01"] = "UNUTMAYIN, EN AZ DÖRT ÇANTA METAMFETAMİN LAZIM.",
["pln_rats_stage1_04_any_01"] = "NE!? MENDOZA KARTELİ HÂLÂ ORADA! HALLEDİN ONLARI!",
["pln_rats_stage1_05_any_01"] = "BAŞKA KİMSENİN ORADA OLMADIĞINDAN EMİN OLUN.",
["pln_rats_stage1_06_any_01"] = "HECTOR'IN AŞÇILARI ÖLMÜŞ GİBİ. METAMFETAMİNİ KENDİMİZ YAPMALIYIZ!",
["pln_rats_stage1_07_any_01"] = "ACELE ETMELİYİZ! POLİSİN TELSİZİ DELİ GİBİ ÖTÜYOR. ÇOKTAN YOLA ÇIKMIŞLAR!",
["pln_rats_stage1_08_any_01"] = "PEKÂLÂ, İŞLEM BAŞLADI, PİŞİYOR. HECTOR ARACILIĞIYLA BİR UZMANLA BAĞLANTIM VAR. SİZE YOL GÖSTERECEĞİM.",
["pln_rats_stage1_09_any_01"] = "SWAT'LARIN LABORATUVARA GİRMESİNE İZİN VERMEYİN. NE PAHASINA OLURSA OLSUN UZAK TUTUN!",
["pln_rats_stage1_10_any_01"] = "GELİYORLAR MİLLET. ÇEVRENİZİN HER YERİ HELİKOPTER VE SWAT MİNİBÜSÜ DOLU. TETİKTE OLUN!",
["pln_rats_stage1_11_any_01"] = "SWAT EKİBİ KERESTE FABRİKASINDAN GELİYOR. UZAK TUTUN ONLARI!",
["pln_rats_stage1_11_any_02"] = "GELİYORLAR! KERESTE FABRİKASINDAN! TETİKTE OLUN!",
["pln_rats_stage1_11_any_03"] = "KERESTE FABRİKASINDAN GELİYORLAR, DİKKAT EDİN!",
["pln_rats_stage1_12_any_01"] = "DEMİRYOLU KÖPRÜSÜNDEN GELİYORLAR! DİKKAT EDİN!",
["pln_rats_stage1_12_any_02"] = "DEMİRYOLU KÖPRÜSÜ! DEMİRYOLU KÖPRÜSÜNDEN GELİYORLAR, UZAK TUTUN ONLARI.",
["pln_rats_stage1_12_any_03"] = "SWAT KERESTE FABRİKASINDAN GELİYOR, UZAK TUTUN!",
["pln_rats_stage1_13_any_01"] = "YOLUN YANINDAKİ ORMANDAN SWAT GELİYOR, DİKKATLİ OLUN!",
["pln_rats_stage1_13_any_02"] = "YOLUN YANINDAKİ ORMANDAN GELİYORLAR! UZAK TUTUN!",
["pln_rats_stage1_14_any_01"] = "DİKKATLİ OLUN! KESKİN NİŞANCILAR GELİYOR!",
["pln_rats_stage1_15_any_01"] = "ONLARI UZAK TUTTUNUZ. GÜZEL İŞ! AMA GERİ ÇEKİLMİYORLAR, DAHA FAZLASINA HAZIR OLUN.",
["pln_rats_stage1_15_any_02"] = "İYİ İŞ! PİŞİRMEYE DÖNÜN. DALGALAR ARASINDAKİ ZAMANI DAHA FAZLA MALZEME BULMAK İÇİN KULLANIN.",
["pln_rats_stage1_16_any_01"] = "MALZEME GEREKECEK. ETRAFI KOLAÇAN EDİP NE BULABİLİYORSUNUZ BAKIN.",
["pln_rats_stage1_17_any_01"] = "BİR MALZEME EKLEMELİSİNİZ. YANLIŞ OLANI KULLANMAYIN SAKIN. TEK BİR YANLIŞ ADIMDA LABORATUVAR NOEL AĞACI GİBİ ALEV ALIR.",
["pln_rats_stage1_18_any_01"] = "DİKKATLİ OLMAYI UNUTMAYIN! YANLIŞ MALZEMEYİ KULLANAMAYIZ. DİKKATLİ OLMALISINIZ!",
["pln_rats_stage1_19_any_01"] = "İŞLEMİN DEVAM ETMESİ İÇİN TUZ RUHU EKLEMENİZ GEREKİYOR!",
["pln_rats_stage1_20_any_01"] = "İŞLEME DEVAM ETMEK İÇİN TUZ RUHU EKLEYİN!",
["pln_rats_stage1_21_any_01"] = "İŞLEMİN DEVAM ETMESİ İÇİN KOSTİK SODA EKLEMELİSİNİZ!",
["pln_rats_stage1_22_any_01"] = "İŞLEME DEVAM ETMEK İÇİN KOSTİK SODA EKLEYİN!",
["pln_rats_stage1_23_any_01"] = "İŞLEMİN DEVAM ETMESİ İÇİN HİDROJEN KLORÜR EKLEMELİSİNİZ!",
["pln_rats_stage1_24_any_01"] = "İŞLEMİ SÜRDÜRMEK İÇİN HİDROJEN KLORÜR EKLEYİN!",
["pln_rats_stage1_25_any_01"] = "GÜZEL, DEVAM EDİYOR. GÖZÜNÜZ AÇIK OLSUN, SAVUNMAYA DEVAM EDİN...",
["pln_rats_stage1_26_any_01"] = "VAY! MİLLET? İYİ MİSİNİZ? DİKKATLİ OLUN DEMİŞTİM!",
["pln_rats_stage1_26_any_02"] = "AH, NE!? MİLLET, O MADDELERE DİKKAT ETMELİSİNİZ, SİZE SÖYLEDİM!",
["pln_rats_stage1_27_any_01"] = "LABORATUVARI ARTIK KULLANAMAYIZ, GİTTİ. ELİNİZDEKİNİ ALIN DA GİDELİM.",
["pln_rats_stage1_28_any_01"] = "İŞLEM TAMAMLANDI! ÇANTALAYIN DA BİR TUR DAHA YAPALIM.",
["pln_rats_stage1_29_any_01"] = "ÇANTALARI GÜVENE ALMAK İÇİN MİNİBÜSE GÖTÜRÜN. POLİSLERİN ALIN TERİYLE KAZANDIĞINIZ METAMFETAMİNLE KAÇMASINA İZİN VERMEYİN!",
["pln_rats_stage1_30_any_01"] = "İYİ İŞ. DÖRT ÇANTA GİDİP TAKAS YAPMAYA YETER.",
["pln_rats_stage1_31_any_01"] = "HARİKA! BÜTÜN O ÇANTALARLA TAKAS SORUNSUZ GEÇER.",
["pln_rats_stage1_32_any_01"] = "MİLLET, BEKLEDİĞİMİZDEN AZ ÇANTA VAR AMA YİNE DE TAKASI YAPIP BİLGİYİ VERMELERİNİ UMABİLİRİZ.",
["pln_rats_stage1_33_any_01"] = "HİÇ ÇANTA YOK MU!? BU TAKAS BİZE YARAMAYACAK. UMARIM TAKAS İÇİN KOLUNUZDA BİRKAÇ NUMARA VARDIR.",
["pln_rats_stage1_34_any_01"] = "İYİ DÜŞÜNDÜNÜZ! O TAHTALARLA DAHA FAZLA PENCEREYİ KAPATIN.",
["pln_rats_stage2_01_any_01"] = "GANGSTERLER İLERİDE BEKLİYOR OLMALI. İŞLER KARIŞSIN İSTEMİYORSANIZ PARMAKLARINIZI TETİKTEN ÇEKİN. ŞÜPHELİ ŞEYLERE KARŞI GÖZÜNÜZ AÇIK OLSUN.",
["pln_rats_stage2_02_any_01"] = "TAMAM, METAMFETAMİNİ VERME VAKTİ.",
["pln_rats_stage2_03_any_01"] = "DAİREYE GİDİP ALMAYA GELDİĞİMİZ ŞEYİ ALIN.",
["pln_rats_stage2_04_any_01"] = "TAMAM, GEREKENİ ALDIK. ÇIKMA VAKTİ.",
["pln_rats_stage2_05_any_01"] = "TAMAM, İSTİHBARATI ALIP YÜRÜYÜN.",
["pln_rats_stage2_06_any_01"] = "KAYBEDECEK VAKİT YOK. MİNİBÜSE GİDİN!",
["pln_rats_stage2_07_any_01"] = "GÖRÜNÜŞE GÖRE ZOR YOLDAN YAPACAĞIZ. BAŞINIZI EĞİN, BİLGİ İÇİN O DAİRELERİ ARAYIN! KASA ARAYIN!",
["pln_rats_stage2_08_any_01"] = "METAMFETAMİN OLMADAN TAKASI YAPAMAYIZ. YAKINDAKİ DAİRELERİ ARAYIP BİLGİYİ KENDİNİZ ALMANIZ GEREKECEK.",
["pln_rats_stage2_08_any_01b"] = "AMA DİKKAT EDİN. YAKALANIRSANIZ MUHTEMELEN İSTİHBARATI YOK ETMEYE ÇALIŞACAKLAR.",
["pln_rats_stage2_09_any_01"] = "SÖZ VERDİĞİMİZ MİKTARDA METAMFETAMİN GETİRMESEK DE ANLAŞMAYI YAPABİLİRİZ. AMA İŞLER BOZULURSA DİYE HAZIRLIKLI OLUN.",
["pln_rats_stage2_09_any_01b"] = "İŞLER KIZIŞIRSA İSTİHBARATI YOK ETMEYE ÇALIŞIRLAR BÜYÜK İHTİMALLE.",
["pln_rats_stage2_10_any_01"] = "ACELE EDİN, YETİŞEMEDEN İSTİHBARATI YOK EDEBİLİRLER!",
["pln_rats_stage2_11_any_01"] = "İSTİHBARATI YAKMIŞLAR GİBİ. ELİ BOŞ GİTMEMİZ GEREKECEK!",
["pln_rats_stage2_12_any_01"] = "POLİSE HABER VERİLDİ, YAKLAŞIYORLAR. HER AN ORADA OLABİLİRLER.",
["pln_rats_stage2_13_any_01"] = "FEDERALLER OLSUN OLMASIN, O İSTİHBARAT LAZIM! DAİRELERİ ARAMALISINIZ! KASA ARAYIN!",
["pln_rats_stage2_14_any_01"] = "LANET KALLEŞLER! BU KARARLARINA PİŞMAN EDİN, BİLGİYİ DE BULUN! KASA ARAYIN!",
["pln_rats_stage3_01_any_01"] = "KONVOY DURDU, OTOBÜSE DOĞRU İLERLEYİN.",
["pln_rats_stage3_02_any_01"] = "UNUTMAYIN, MUHBİRİN PEŞİNDEYİZ. OTOBÜSE YÖNELİN. BAŞINIZI EĞİP SİPERDEN SİPERE İLERLEYİN.",
["pln_rats_stage3_03_any_01"] = "HER YERDE AĞIR ZIRHLI FBI BİRİMLERİ VAR, DİKKATLİ OLUN.",
["pln_rats_stage3_04_any_01"] = "OTOBÜS BU, HEPSİNİ İNDİRİN.",
["pln_rats_stage3_05_any_01"] = "PARA SİZİN, ALIN. ŞİFRELER ELİNİZDEYSE DÖŞENMİŞ C4'LERİ ETKİSİZ HÂLE GETİREBİLİRSİNİZ.",
["pln_rats_stage3_06_any_01"] = "GANİMETİ BOŞALTMANIZ İÇİN BİR HELİKOPTER GÖNDERİYORUM. YAKINLARDA, FAZLA SÜRMEZ. SIKI DURUN.",
["pln_rats_stage3_07_any_01"] = "O C4'ÜN YANINDA DİKKATLİ OLUN, MİLLET.",
["pln_rats_stage3_08_any_01"] = "OTOBÜS PATLADI! DİKKATLİ OLUN, O ATEŞTEN UZAK DURUN!",
["pln_rats_stage3_08_any_02"] = "AH HAYIR! PATLADI, DİKKAT EDİN! O ATEŞTEN UZAK DURUN!",
["pln_rats_stage3_09_any_01"] = "HELİKOPTER ORADA, ÇANTALARI HELİKOPTERE ATIN.",
["pln_rats_stage3_10_any_01"] = "GÜZEL İŞ, KÖSTEBEK ÖLDÜ, KAÇIŞ HELİKOPTERİ BEKLİYOR. O OTOBÜSTEKİ PARANIN PEŞİNE DÜŞMEK İSTEMİYORSANIZ HELİKOPTERE GİDİN DE SİZİ ORADAN KURTARALIM.",
["pln_rats_stage3_11_any_01"] = "POLİS TELSİZİNİ DUYUYORUM, KOLLUK KUVVETLERİ YOLDA. 30 SANİYE İÇİNDE VARACAKLAR.",
["pln_rats_stage3_12_any_01"] = "POLİS VE SWAT GELDİ, DİKKATLİ OLUN!",
["pln_rats_stage3_13_any_01"] = "O HELİKOPTERE DİKKAT EDİN. POLİSLERİN CİDDİ HASAR VEREBİLECEĞİ KADAR YAKINDA.",
["pln_rt1_01_any_01"] = "ELEKTRİĞİ KESTİLER! IŞIKLAR SÖNDÜ.",
["pln_rt1_01_any_02"] = "EVİN ELEKTRİĞİNİ KESTİLER! IŞIKLAR SÖNDÜ.",
["pln_rt1_01_any_03"] = "POLİS IŞIKLARI SÖNDÜRDÜ, YENİDEN AÇIN.",
["pln_rt1_02_any_01"] = "ELEKTRİĞİ GERİ GETİRİN, YOKSA İŞLER BİR ANDA SARPA SARAR.",
["pln_rt1_02_any_02"] = "O IŞIKLARI GERİ AÇMALIYIZ. İŞE KOYULUN!",
["pln_rt1_03_any_01"] = "DİKKAT, EVİN DIŞINDA HAREKET GÖRÜYORUM.",
["pln_rt1_03_any_02"] = "MİSAFİRİMİZ VAR! MUHTEMELEN MENDOZA'LAR GELDİ.",
["pln_rt1_04_any_01"] = "TUZ RUHU, KOSTİK SODA VE HİDROJEN KLORÜR ARIYORSUNUZ.",
["pln_rt1_04_any_02"] = "PİŞİRMEK İÇİN KİMYASAL LAZIM. TUZ RUHU, KOSTİK SODA VE HİDROJEN KLORÜR. KOLAY.",
["pln_rt1_05_any_01"] = "EVE GİRİP HECTOR'IN AŞÇILARINI BULABİLİR MİSİNİZ BAKIN.",
["pln_rt1_05_any_02"] = "İÇERİ GİRİN, O AŞÇILAR LAZIM.",
["pln_rt1_06_any_01"] = "EVE GİRİN.",
["pln_rt1_06_any_02"] = "HADİ, KIMILDAYIN DA EVE GİRİN.",
["pln_rt1_07_any_01"] = "UNUTMAYIN, EN AZ 3 ÇANTA METAMFETAMİN LAZIM.",
["pln_rt1_07_any_02"] = "MİLLET, TAKAS İÇİN ÜÇ ÇANTA YETERLİ OLMALI.",
["pln_rt1_08_any_01"] = "LANET OLSUN! BİRİ BİZDEN ÖNCE GELMİŞ... DİKKATLİ OLUN...",
["pln_rt1_08_any_02"] = "DİKKAT! ADAMLARI HÂLÂ GİTMEMİŞ, İNDİRİN ONLARI!",
["pln_rt1_09_any_01"] = "BAŞKA KİMSENİN ORADA OLMADIĞINDAN EMİN OLUN.",
["pln_rt1_09_any_02"] = "RAKİPLER İÇİN ORAYA BAKIN.",
["pln_rt1_10_any_01"] = "YANİ... AŞÇILAR ÖLDÜYSE... O ZAMAN BİZ... KENDİMİZ PİŞİRMELİYİZ.",
["pln_rt1_10_any_02"] = "HECTOR'IN AŞÇILARI ÖLMÜŞ. PİŞİRMEYİ KENDİMİZ YAPMALIYIZ... TAMAM...",
["pln_rt1_11_any_01"] = "TAMAM. BİR SOLUKLANDIK. TANRIM. İYİ İŞ.",
["pln_rt1_11_any_02"] = "PİŞİRMEYE DEVAM MİLLET. TEMPO!",
["pln_rt1_11_any_03"] = "PİŞİRMEYİ BAŞLATIN; BURADA KALAMAYIZ, HİÇ KALAMAYIZ HEM DE!",
["pln_rt1_11_any_04"] = "O SES SAF ZEHRİN PİŞME SESİ. YETERİNCE ALINCA SİKTİRİP GİDİN.",
["pln_rt1_12_any_01"] = "GÜZEL, TAMAM, TEPKİME İYİ GÖRÜNÜYOR, DEVAM EDİN.",
["pln_rt1_12_any_02"] = "TAMAM, ŞİMDİLİK DENGELİ GÖRÜNÜYOR. DAHA MALZEME EKLEYİN...",
["pln_rt1_12_any_03"] = "ŞŞŞT! O SES NE... HIMM, SANKİ... YOK, SORUN YOK GİBİ.",
["pln_rt1_12_any_04"] = "TAMAM, TAMAM GÜZEL.",
["pln_rt1_12_any_05"] = "PEKÂLÂ, BU WEB SAYFASINDA... AZ ÖNCE NE EKLEDİNİZ? PEKÂLÂ. TAMAM, TAMAM.",
["pln_rt1_12_any_06"] = "HI HI, İYİ İYİ.",
["pln_rt1_12_any_07"] = "TAMAM, ONU DENEYELİM.",
["pln_rt1_12_any_08"] = "TAMAM, SAĞLAM.",
["pln_rt1_12_any_09"] = "GÜZEL... İYİ GİBİ.",
["pln_rt1_12_any_10"] = "SAĞLAM... EMİNİM. GÜZEL PİŞİYOR.",
["pln_rt1_12_any_11"] = "TAMAM, DUMANI OLABİLDİĞİNCE AZ TUTUN... DEVAM EDİN.",
["pln_rt1_13_any_01"] = "EVİN İÇİNDELER!",
["pln_rt1_13_any_02"] = "İÇERİDELER!",
["pln_rt1_13_any_03"] = "EVE ZORLA GİRİYORLAR!",
["pln_rt1_14_any_01"] = "BİNAYA TIRMANIYORLAR!",
["pln_rt1_14_any_02"] = "POLİSLER DIŞARIDAN TIRMANIYOR. PENCERELERE GİDİN!",
["pln_rt1_14_any_03"] = "SIÇTIK, DIŞARIDA SÜRÜNENLER VAR. PENCERELERE DİKKAT!",
["pln_rt1_15_any_01"] = "BALKONDAN GELİYORLAR!",
["pln_rt1_15_any_02"] = "BALKONA, HEMEN!",
["pln_rt1_15_any_03"] = "SWAT, BALKONDA SWAT VAR!",
["pln_rt1_20_any_02"] = "AH, TAMAM... TUZ, TUZ RUHU. DAHA EKLEYİN.",
["pln_rt1_20_any_03"] = "TAMAM, KOSTİK EKLEYİN... HAYIR, DURUN, ASİT EKLEYİN. TUZ RUHU.",
["pln_rt1_20_any_04"] = "TU... TUZ RUHU, İÇİNE BİRAZ DAHA LAZIM.",
["pln_rt1_20_any_05"] = "GÜZEL PİŞİYOR AMA DAHA FAZLA ASİT GEREK.",
["pln_rt1_20_any_06"] = "ASİT MİLLET, ASİT. BİRAZ BULUP İÇİNE DÖKÜN. ",
["pln_rt1_20_any_07"] = "BU SİTEYE BAKIYORUM... BU ADIMDA ASİT KULLANILIR DİYOR... TUZ RUHUMUZ VAR, DEĞİL Mİ?",
["pln_rt1_20_any_08"] = "HMM, EVET KOSTİK SODA DEĞİL... EVET. ASİT OLMALI. EVET, EMİNİM BU.",
["pln_rt1_20_any_09"] = "ŞİMDİ TUZ RUHU OLDUĞUNDAN %100 EMİNİM. EKLEYİN GİTSİN.",
["pln_rt1_22_any_02"] = "SICAKLIĞI YÜKSELTMEK İÇİN MADEN SUYU GEREKTİĞİ YAZIYOR... TUHAF. NE BULABİLİYORSUNUZ?",
["pln_rt1_22_any_03"] = "ŞİMDİ KOSTİK BAZ TEPKİMESİ EKLENİYOR. TAMAM, ETRAFTA SODA VAR MI? EKLEYİN.",
["pln_rt1_22_any_04"] = "KOSTİK SODA, EVET, BU. KULLANIN.",
["pln_rt1_22_any_05"] = "KOSTİK KLORÜR. SIVI HÂLDE DİYOR... BİR DAKİKA... SODA OLMALI, DEĞİL Mİ?",
["pln_rt1_22_any_06"] = "BU NOKTADA SADECE TAHMİN EDİYORUM... İNTERNETTEKİ ŞU AÇIKLAMALAR PEK GÜVENİLİR DEĞİL.",
["pln_rt1_22_any_07"] = "KOSTİK SODA DENEYİN... YA DA HİDROJEN... YOK YOK, BEKLEYİN, SODA... ONU KULLANIN. EVET.",
["pln_rt1_22_any_08"] = "KESİNLİKLE HİDROJEN KLORÜR GEREK... TAMAM, BEKLEYİN, SODA... EVET, KOSTİK SODA!",
["pln_rt1_22_any_09"] = "BURAYA KOSTİK SODA GEREKTİĞİNDEN %100 EMİNİM. BİRAZ ATIN İÇİNE.",
["pln_rt1_24_any_02"] = "KOSTİK KLORÜR. KATI BİR TÜRÜ DİYOR... BİR DAKİKA... ŞU HİDROJEN OLMALI, DEĞİL Mİ? ",
["pln_rt1_24_any_03"] = "HİDROJEN... GAZ MI BU... KATI OLAMAZ... EKLE DİYOR. SİZDE GAZ TÜPÜ VAR MI?",
["pln_rt1_24_any_04"] = "BU SİTE BAŞKA BİR ŞEY SÖYLÜYOR... KLORÜR, SODA, HİDROJEN KARIŞIMI. BİLMİYORUM, BİR ŞEY DENEYİN.",
["pln_rt1_24_any_05"] = "HİDROJEN KLORÜR GEREKİYOR, KESİN.",
["pln_rt1_24_any_06"] = "KESİNLİKLE HİDROJEN KLORÜR GEREK... YOK YOK, BEKLEYİN... EVET, TAMAM.",
["pln_rt1_24_any_07"] = "HAY SİKEYİM, O AŞÇILARA İHTİYACIMIZ VARDI. HİDROJENİ SEÇİYORUM.",
["pln_rt1_24_any_08"] = "HASSİKTİR, O AŞÇILARA İHTİYACIMIZ VARDI. BEN KLORÜR DİYORUM.",
["pln_rt1_24_any_09"] = "HASSİKTİR, O LANET AŞÇILARA İHTİYACIMIZ VARDI. BEN KOSTİK SODA DİYORUM.",
["pln_rt1_24_any_10"] = "YÜZDE 100 EMİN DEĞİLİM AMA SANIRIM ŞİMDİ HİDROJEN KLORÜR. EVET, O OLMALI.",
["pln_rt1_25_01"] = "KUSURA BAKMAYIN.",
["pln_rt1_25_02"] = "BU KONUDA GERÇEKTEN BİRAZ OKUYUP BİLGİ EDİNMELİYİM, DEĞİL Mİ?",
["pln_rt1_25_03"] = "DOĞRU OLAN BU DEĞİLMİŞ GALİBA.",
["pln_rt1_25_04"] = "YOK. HAYIR, DOĞRU OLAN BU DEĞİLDİ...",
["pln_rt1_25_05"] = "HAY AKSİ.",
["pln_rt1_25_06"] = "AA, MEĞER DOĞRU MALZEME BU DEĞİLMİŞ.",
["pln_rt1_25_07"] = "İNTERNETE GÜVENİNCE BÖYLE OLUYOR HERHÂLDE.",
["pln_rt1_25_08"] = "VAY. İHTİMAL NEYDİ Kİ? EVET, BELKİ DE PEK YÜKSEK DEĞİLDİ...",
["pln_rt1_25_09"] = "HAY AKSİ. SANIRIM BU BENİM HATAM.",
["pln_rt1_25_10"] = "ARADA SIRADA BANA GÜVENMEYİN, MİLLET.",
["pln_rt1_25_11"] = "YOK, HAYIR... BU DOĞRU DEĞİLDİ...",
["pln_rt1_25_12"] = "VAY, FENA ÇARPTI.",
["pln_rt1_25_13"] = "O BÜYÜK PATLAMAYI DUYDUNUZ MU? MİLLET?",
["pln_rt1_25_14"] = "METTEN ÖLÜM...",
["pln_rt1_25_15"] = "DEMEK HİDROKLORİK ASİT AYNI ŞEYMİŞ... HER GÜN YENİ BİR ŞEY ÖĞRENİYOR İNSAN.",
["pln_rt1_25_16"] = "DEMEK SODYUM HİDROKSİT AYNI ŞEYMİŞ... HAH, HER GÜN YENİ BİR ŞEY ÖĞRENİYOR İNSAN.",
["pln_rt1_25_17"] = "SİKTİR. SADECE... SİKTİR.",
["pln_rt1_25_18"] = "EVET, İÇİMDEN BİR SES O MALZEMENİN YANLIŞ OLDUĞUNU SÖYLÜYORDU...",
["pln_rt1_25_19"] = "YANLIŞ MALZEME OLDUĞUNA DAİR İÇİMDE BİR HİS VARDI...",
["pln_rt1_25_20"] = "MEĞER BOMBA YAPMAKTA ÇOK İYİYMİŞİZ...",
["pln_rt1_25_21"] = "BEKLEYİN MİLLET, GALİBA ŞU CAS KAYIT NUMARALARINI KARIŞTIRIYORUM. ...MİLLET?",
["pln_rt1_a_01"] = "PEKÂLÂ, BAKALIM...",
["pln_rt1_a_02"] = "BEKLEYİN...",
["pln_rt1_a_03"] = "TAMAM, SIRADA NE VAR...",
["pln_rt1_a_04"] = "PEKİİİ, SIRADAKİ ADIM...",
["pln_rt1_a_05"] = "ŞİMDİ BİZE GEREKEN...",
["pln_rt1_a_06"] = "TAMAM, SIRADAKİ MALZEME...",
["pln_rt1_a_07"] = "TAMAM, BUNDAN SONRA NE GELİYOR...",
["pln_rt1_a_08"] = "EE... HI HI...",
["pln_rt1_a_09"] = "ŞEY, DOĞRU OKUYORSAM... ŞEY...",
["pln_rt1_a_10"] = "ŞEY, UMARIM DOĞRU ANLAMIŞIMDIR...",
