["pln_rt1_j_01"] = "...SANIRIM.",
["pln_rt1_j_02"] = "...SANIRIM.",
["pln_rt1_j_03"] = "...HESAPLARIM DOĞRUYSA TABİİ.",
["pln_rt1_j_04"] = "...EN AZINDAN ÖYLE SANIYORUM.",
["pln_rt1_j_05"] = "...BİR ŞEYİ KAÇIRMADIYSAM...",
["pln_rt1_j_06"] = "...EMİNİM. BAYAĞI EMİNİM.",
["pln_rt1_j_07"] = "...KESİNLİKLE. YA DA BÜYÜK İHTİMALLE.",
["pln_rt1_j_08"] = "...EN İYİ TAHMİNİM BU.",
["pln_rt1_j_09"] = "...EN İYİ TAHMİNİM BU.",
["pln_rt1_j_10"] = "...ÖYLE OLMALI.",
["pln_rt1_j_11"] = "...BU BENİM UZMANLIĞIM DEĞİL.",
["pln_rt1_j_12"] = "...BU PEK BENİM UZMANLIK ALANIM DEĞİL ASLINDA.",
["pln_rt1_j_13"] = "...BU İNTERNET SİTESİ DOĞRU OLSA İYİ OLUR.",
["pln_rt1_j_14"] = "...OLABİLECEK EN KÖTÜ ŞEY NE Kİ, DEĞİL Mİ?",
["pln_rt1_j_15"] = "...İNTERNETTEKİ BU AÇIKLAMALAR EN İYİ İHTİMALLE ŞÜPHELİ.",
["pln_rt1_j_16"] = "...EVET... EVET.",
["pln_rt1_j_17"] = "...BİR DE ŞANS DİLEYİN.",
["pln_rt1_j_18"] = "...BİR DE UĞURLU TILSIMLARINIZI ÖPÜN.",
["pln_rt1_j_19"] = "...ASLINDA YAZI TURA GİBİ.",
