["pln_rt1_j_28"] = "...%57 EMİNİM.",
["pln_rt1b_01_01"] = "LANET OLSUN, POLİS BURAYI GÖZETLİYORMUŞ GALİBA. KIPIRDAYIN!",
["pln_rt1b_01_02"] = "AH LANET. POLİSLER YOLDA. MEKÂNI GÖZETLİYORLARMIŞ GALİBA.",
["pln_rt1b_01_03"] = "KAYBEDECEK VAKİT YOK. İÇERİ GİRİN!",
["pln_rt1b_02_01"] = "MALZEMELER AZALIYOR MU? KALIP BİRAZ DAHA PİŞİRMEK İSTERSENİZ HAZIRDA BEKLEYEN BİR İKMALİNİZ VAR... HELİKOPTERE İŞARET VERİN YETER. YA DA ŞİMDİ KAÇABİLİRSİNİZ. SEÇİM SİZİN.",
["pln_rt1b_02_02"] = "SADECE BİRKAÇ MALZEME KALDI. DAHA FAZLASINI İSTİYORSANIZ İŞARET FİŞEĞİYLE HELİKOPTERİ ÇAĞIRIN. DAHA ÇOK PİŞİRMEK İÇİN GEREKEN ONDA. YA DA ŞİMDİ SIVIŞABİLİRSİNİZ. SİZE KALMIŞ.",
["pln_rt1b_02_03"] = "BURADA MALZEME AZALIYOR. DAHA FAZLA MALZEME ALMAK İSTİYORSANIZ İŞARET FİŞEĞİYLE HELİKOPTERE HABER VERİN. PİLOTUN ÜCRETİ SAATE GÖRE, GELDİĞİNE DEĞSİN. YA DA KAÇABİLİRSİNİZ. KARAR SİZİN.",
["pln_rt1b_03_01"] = "İYİ YER. ŞİMDİ BEKLİYORUZ.",
["pln_rt1b_03_02"] = "TAMAM, ŞİMDİ PİLOTU BEKLEYİN.",
["pln_rt1b_03_03"] = "İŞTE BÖYLE. ŞİMDİ PİLOTUN HABER VERMESİNİ BEKLEYİN.",
["pln_rt1b_04_01"] = "YÜK BIRAKILDI. KAPIP LABORATUVARIN YANINA KOYUN.",
["pln_rt1b_04_02"] = "MALZEMELER ORADA. ALIN! EVİN İÇİNDE GÜVENCEYE ALIN.",
["pln_rt1b_04_03"] = "PİLOT MALZEMELERİ BIRAKTI. EVE TAŞIYIN.",
["pln_rt1b_05_01"] = "PİŞİRİRKEN DİKKATLİ OLUN BEYLER.",
["pln_rt1b_05_02"] = "TAMAM. BURAYI YAKMAYIN MİLLET.",
["pln_rt1b_05_03"] = "HARİKA. BİRAZ DAHA MAL PİŞİRELİM. HİÇBİR ŞEYİ YAKMAYIN YETER.",
["pln_rt1b_06_01"] = "İŞİ BİLİYORSUNUZ: DAHA FAZLA MALZEME ALMAK İÇİN HELİKOPTERE İŞARET VERİN. YA DA ÇIKIP GİDİN, SİZE KALMIŞ.",
["pln_rt1b_06_02"] = "NE YAPACAĞINIZI BİLİYORSUNUZ. HELİKOPTERE İŞARET VERİN, DAHA FAZLA MALZEME BIRAKALIM. YA DA KAÇIN. KARAR SİZİN.",
["pln_rt1b_06_03"] = "MALZEMELER YİNE Mİ BİTTİ? SORUN DEĞİL, DAHA FAZLASI İÇİN HELİKOPTERE İŞARET VERİN. YA DA ORADAN ÇIKIN. KARAR SİZİN.",
["pln_rt1b_07_01"] = "HAM MADDELERİ ALIP EVE TAŞIYIN.",
["pln_rt1b_07_02"] = "EKİP, ÇANTAYI KAPIP MET LABORATUVARININ YANINA BIRAKIN.",
["pln_rt1b_07_03"] = "MALZEMELER SİZİ BEKLİYOR BEYLER. LABORATUVARIN YANINDA GÜVENCEYE ALIN.",
["pln_rt1b_08_01"] = "LABORATUVARI ARTIK KULLANAMAYIZ, YOK OLDU",
["pln_rt1b_brf_01_01"] = "BASİT BİR İŞ AMA BU, KOLAY OLACAĞI ANLAMINA GELMİYOR. ORMANA GİDECEĞİZ. YERİ HATIRLIYORSUNUZ. ORADA HECTOR İÇİN BİRKAÇ İŞ YAPMIŞTIK. NEYSE, MEKÂNI KOLAÇAN ETTİM, HÂLÂ SAĞLAM. O YÜZDEN ORAYA GİDİP YAPABİLDİĞİMİZ KADAR METAMFETAMİN PİŞİRECEĞİZ. İSTEDİĞİNİZ KADAR KALABİLİRSİNİZ. MALZEMELERİNİZ BİTERSE UÇAKLA DAHA FAZLASINI GETİRTİRİM. KOLAY PARA OLMALI.",
["pln_rt1b_cbf_01_01"] = "ORMANDAKİ O TEKİNSİZ ESKİ EVİ HATIRLIYOR MUSUNUZ? HECTOR'IN ADAMLARININ METAMFETAMİN PİŞİRDİĞİ YER? ORAYA GERİ DÖNÜYORUZ.",
["pln_rt1b_cnc_01_01"] = "ORMANDAKİ METAMFETAMİN LABORATUVARINDA PİŞİRMEYE DÖNÜYORUZ. BU SEFER HECTOR'IN BOKLARI YOK. SADECE KÂR İÇİN.",
["pln_rt1b_end_01_01"] = "EH, SUÇ TARİHİNİN ÇUVALLAMALARI ARASINDA BU ÜST SIRALARDA. POLİSLERİN GÜLDÜĞÜNÜ BURADAN DUYUYORUM. BİR DAHAKİ SEFERE BOL ŞANS.",
["pln_rt1b_end_02_01"] = "EH, FENA MİKTAR ALMADINIZ. BENZİN PARASINI ANCA ÇIKARIR. BELKİ BİR DAHAKİNE DAHA İLERİ GİDERİZ.",
["pln_rt1b_end_03_01"] = "GÜZEL VURGUN! BU, EPEY PARA GETİRECEK. İYİ İŞ!",
["pln_rt1b_end_04_01"] = "VAY BE! HARİKAYDINIZ! KAZANDIĞINIZ PARANIN TADINI ÇIKARIN, HAK ETTİNİZ.",
["pln_rt1b_intro_01_01"] = "TAMAM EKİP. GELDİK.",
["pln_rt1b_intro_01_02"] = "YER BURASI. NEREDEYSE HİÇ DEĞİŞMEMİŞ.",
["pln_rt1b_intro_01_03"] = "KİRLİ İŞ AMA KOLAY PARA.",
["pln_rt3_07_any_02"] = "C4'E DİKKAT EDİN, BÜTÜN OTOBÜSÜ DÖŞEMİŞLER.",
["pln_rt3_13_any_02"] = "O HELİKOPTERE GİDİN MİLLET. BİZ DE BU KÖPRÜDEN ÇIKMAK İSTİYORUZ.",
["pln_rt3_14_any_01"] = "C4'Ü ETKİSİZ HÂLE GETİRMEK İÇİN KODLARI KULLANIN!",
["pln_rt3_14_any_02"] = "KODUNUZU KULLANIN, C4'Ü ETKİSİZ HÂLE GETİRİN!",
["pln_rt3_14_any_03"] = "O C4 BOMBALARI, ÜZERLERİNDE KODU KULLANIN!",
["pln_rt3_14_any_04"] = "ŞİFRE O C4'Ü ETKİSİZ HÂLE GETİRECEK! ",
["pln_rt3_14_any_05"] = "BİR C4 DAHA, ETKİSİZ HÂLE GETİRİN!",
["pln_rt3_15_any_01"] = "HARİKA! HEPSİ TAMAM.",
["pln_rt3_15_any_02"] = "HARİKA, HEPSİNİ ALDINIZ... SANIRIM.",
["pln_rt3_16_any_01"] = "ÇABUK!",
["pln_rt3_16_any_02"] = "HIZLANIN!",
["pln_rt3_17_any_01"] = "ÇIKIN ORADAN!",
["pln_rt3_17_any_02"] = "PATLAYACAK! KOŞUN!",
["pln_rt3_17_any_03"] = "SİKTİRİN GİDİN ORADAN!",
["pln_rt3_17_any_04"] = "ÇIKIN! HEMEN OTOBÜSTEN ÇIKIN!",
["pln_rt3_18_any_01"] = "O OTOBÜSTEKİ BÜTÜN SIÇANLARI ÖLDÜRÜN. HECTOR SONRAKİ DURAKTA KİMSENİN İNMESİNİ İSTEMİYOR.",
["pln_rt3_18_any_02"] = "O OTOBÜS. GİDİP KURŞUNA BOĞUN. MENDOZA'LARIN HEPSİ ORADA!",
["pln_rt3_19_any_01"] = "HEPSİNİ TEMİZLEDİNİZ. BÜTÜN MENDOZA'LAR TARİH OLDU. HELİKOPTERE GİDİN YA DA OTOBÜSTEKİ PARALARININ PEŞİNE DÜŞÜN.",
["pln_run_01_01"] = "YAKALAYIN ONU!",
["pln_run_01_02"] = "GİDİP YAKALAYIN!",
["pln_run_01_03"] = "KAÇMASINA İZİN VERMEYİN!",
["pln_run_02_01"] = "KAÇIYOR!",
["pln_run_02_02"] = "VURUN ONU! KAÇIYOR!",
["pln_run_02_03"] = "VURUN ONU!",
["pln_run_03_01"] = "BÜTÜN KASABA AYAĞA KALKTI! POLİS HER YERİ KAPATIYOR!",
["pln_run_03_02"] = "HER YERDEN POLİS SİRENLERİ DUYUYORUM. BASKI ÇOK OLACAK, MİLLET!",
["pln_run_03_03"] = "BÜTÜN BÖLGE POLİSLERLE DOLUYOR GİBİ. DİKKATLİ OLUN!",
["pln_run_04_01"] = "EDDİE'Yİ VURDULAR! YAYA DEVAM ETMENİZ GEREKECEK.",
["pln_run_04_02"] = "EDDİE'Yİ İNDİRDİLER! HÂLÂ YAYASINIZ MİLLET!",
["pln_run_04_03"] = "ŞOFÖRÜ VURDULAR! YAYA DEVAM ETMELİSİNİZ!",
["pln_run_05_01"] = "HAREKETE GEÇMELİSİNİZ!",
["pln_run_05_02"] = "HADİ, MATT'İ YAKALAYIN!",
["pln_run_05_03"] = "GİDİN! DURMAYIN!",
["pln_run_06_01"] = "POLİSLERİ YARIP EDDİE'YLE BULUŞMALISINIZ. İLERLEYİN!",
["pln_run_06_02"] = "HAREKETE GEÇİN! POLİSLERİ AŞIP EDDİE'YLE BULUŞUN!",
