["pln_rvd_brf_01"] = "TAMAM MİLLET. CABOT'IN ADAMLARI DÜKKÂNIN DIŞINDA SİZİ BEKLEYECEK. SÖYLEDİĞİNE GÖRE HIZLI VE KOLAY OLMALI. BU PROFESYONEL LA GANGSTERLERİNE PAYDAY GANG'İN NELER YAPABİLDİĞİNİ GÖSTERİN.",
["pln_rvd_cbf_01"] = "MİLLET, ALASKA'DA OLANLARI KONUŞMAMIZ GEREK AMA HÂLÂ BATIDAYKEN ÖNCE BAŞKA BİR İŞİM VAR. L.A.'DE ESKİ BİR DOSTUMUN OĞLU VAR, CABOT SUÇ AİLESİNDEN. ELMASLARI ALMAK İÇİN BİR KUYUMCUYU SOYMASINA YARDIM LAZIM. YILLAR ÖNCE BABASI BENİ ZOR DURUMDAN KURTARDIĞI İÇİN ONA BÜYÜK BORCUM VAR. KARŞILIĞINDA BİRAZ EK GÜÇ SÖZÜ VERDİM. BU ADAMLAR PROFESYONEL, TAM KARAKTERLER. KOD ADLARI BİLE KULLANIYORLAR! VAR MISINIZ?",
["pln_rvd_cnc_01"] = "L.A.'DE ESKİ BİR DOSTUMA YARDIM EDİYORUZ. ELMAS SORUNU VAR.",
