["pln_sfr_brf_01"] = "POLİSLERE KİM HABER VERDİ BİLMİYORUM AMA İÇERİDE KİMLERİN OLDUĞUNU BİLMEDİKLERİNE DAİR SAĞLAM BİLGİM VAR. OLASI BİR UYUŞTURUCU OPERASYONUNA SIRADAN BASKIN BEKLİYORLAR. ONLARI SICAK KARŞILAYIN, İSTİHBARATLARINI DOĞRU ALMALARI GEREKTİĞİNİ ÖĞRETİN.",
["pln_sfr_cbf_01"] = "DİNLEYİN! BİRİ GÜVENLİ EVDE ŞÜPHELİ FAALİYET OLDUĞUNA DAİR POLİSE İHBAR VERMİŞ. ŞU AN ARAMA VE EL KOYMA İÇİN BİRLİKLER YOLDA. AMA SİZ OLDUĞUNUZU BİLMİYORLAR. BÜYÜK SÜRPRİZ YAŞAYACAKLAR.",
