["pln_sh11_12_01"] = "UNUTMAYIN, BUNDAN SONRA BÖYLE ‘ÖZEL’ İYİLİKLER İÇİN PARA ÖDEMENİZ GEREKECEK. BAĞLANTILARIM BEDAVAYA ÇALIŞMAZ.",
["pln_sh11_12_02"] = "BİR DAHAKİ SEFERE BÖYLE \"ÖZEL\" İYİLİKLER İÇİN ÖDEME YAPMALISIN. BAĞLANTILARIM KIÇLARINI TEHLİKEYE ATIYOR, KARŞILIĞINDA İYİ PARA BEKLİYORLAR.",
["pln_sh11_12_03"] = "BU SEFER ARKANIZI KOLLADIM AMA BUNDAN SONRA BÖYLE ‘ÖZEL’ İYİLİKLER İÇİN PARA ÖDEMENİZ GEREKECEK. BAĞLANTILARIM İYİ İNSANLARDIR VE KARŞILIĞINDA İYİ PARA BEKLERLER.",
