["pln_sh11_19_03"] = "KONTROLDEKİ ADAMIN APTAL OLMASI ŞANSIMIZA AMA ŞÜPHELENİYOR. BİR DAHAKİ SEFERE BÜYÜK İHTİMALLE ALARM VERECEK.",
