["pln_sh11_22_01"] = "MÜKEMMEL. ŞİMDİ BİR ŞEY ÇALMAYI UNUTMA. BUNU SIRADAN BİR SOYGUNDAN BAŞKA HİÇBİR ŞEY GİBİ GÖSTERMEMELİYİZ.",
