["pln_sh11_24_03"] = "TAMAM, DİKKATLİ OLMA VAKTİ. BÖLGEDE DEVRİYE GEZEN BAŞKA BİR GÜVENLİKÇİ VAR. BAHSE GİRERİM KAYIP ARKADAŞLARINI ARIYOR. NE OLURSA OLSUN BU ADAMI ÖLDÜRMEYİN. ANLAŞILDI MI? ONU ÖLDÜRMEYİN, YOKSA SIÇTIK.",
["pln_sh11_25_01"] = "BİR HEDEF GÖRÜRSEN HAREKETLERİNİ TAKİP ETMEK İÇİN ONU \"İŞARETLEYEBİLİRSİN\".",
["pln_sh11_25_02"] = "HEDEFLERİ TAKİP ETMEK İÇİN 'İŞARETLEYEBİLİRSİN'.",
