["pln_sh11_30_01"] = "İYİ İŞ ÇIKARDIN. DÜRÜST OLAYIM, BEKLEDİĞİMDEN İYİ. ALMAYA GELDİĞİMİZİ ALDIK. ÇALDIĞIN ALTINDAN DA İYİ PARA KAZANIRIZ BENCE. YENİDEN BAŞLAMAN İÇİN FAZLASIYLA YETER.",
["pln_sh11_30_02"] = "BİRLİKTE YAPTIĞIMIZ EN SORUNSUZ İŞ DEĞİLDİ AMA ALMAYA GELDİĞİMİZİ ALDIK. ALDIĞIN ALTINLA BİRLİKTE İYİ PARA ETMESİ GEREK. YENİDEN AYAĞA KALKMANA FAZLASIYLA YETER.",
["pln_sh11_30_03"] = "BİRAZ SARSINTILI GEÇTİ AMA SONU GAYET İYİ OLDU. USB BELLEĞİ ALDIK, ÜSTÜNE ALTIN DA KAZANDIK. YENİDEN BAŞLAMAK İÇİN GÜZEL BİR PARA SAĞLAR.",
["pln_sh11_31_01"] = "LANET OLSUN! ALARM! ORADAN ÇABUCAK ÇIKMANIZ GEREKİYOR!",
["pln_sh11_31_02"] = "LANET OLSUN DALLAS! ALARMI ÇALDIRDIN! OLMAMASI GEREKEN TEK ŞEYDİ BU! NEYSE, YAPABİLİRSEN KAÇMAYA ÇALIŞ...",
["pln_sh11_31_03"] = "SİKTİR, ALARM ÇALDI! BU SOYGUN BİTTİ. AĞIR TOPLAR GELMEDEN KAÇMAYA ÇALIŞ. ÇABUK!",
["pln_sh11_brf_01_01"] = "DALLAS, ESKİ DOSTUM, İKİ YIL SONRA DÖNMENE SEVİNDİM. TİTİZ BİRİ OLDUĞUMU BİLİYORSUN. O YÜZDEN ÜSTÜNDEKİ PASI ATMANI İSTEMEM ŞAŞIRTMASIN. ESKİ GÜNLERDEKİ GİBİ TALİMATLARIMA UY, ÇOCUK OYUNCAĞI OLACAK. SONRA İHTİYACIMIZ OLACAK BAZI ERİŞİM KODLARININ PEŞİNDEYİZ AMA BASİT BİR SOYGUNDAN İBARET GÖRÜNMELİ. SESSİZ YAPACAKSIN, ONA GÖRE GİYİN.",
["pln_sh11_cbf_01_01"] = "POLİSLERİN DEPO TESİSİNE GİR VE DAHA SONRA İHTİYACIMIZ OLACAK ERİŞİM KODLARINI ELE GEÇİR.",
