["pln_sh21_06_02"] = "VE YERE SERİLDİLER. TAMAM, BAHSE GİRERİM KOKAİN O KASADA. MATKAP VAKTİ.",
["pln_sh21_06_03"] = "KOLAYDI. TAMAM, MATKABINI YERLEŞTİRİP O KASA'YI AÇ.",
["pln_sh21_07_01"] = "MATKABI BEKLERKEN OFİSE BAKIN. BELKİ ALABİLECEĞİMİZ BAŞKA GANİMET VARDIR.",
["pln_sh21_07_02"] = "MATKABIN BİTMESİNİ BEKLERKEN İLGİNÇ BİR ŞEY BULABİLİR MİSİNİZ, BAKIN.",
["pln_sh21_07_03"] = "MATKABI BEKLERKEN DEĞERLİ BAŞKA BİR ŞEY VAR MI BAKALIM.",
["pln_sh21_08_01"] = "DİKKAT DALLAS! POLİSLER GELDİ! İNDİR ONLARI!",
["pln_sh21_08_02"] = "DALLAS! POLİS BURADA, NE YAPACAĞINI BİLİYORSUN!",
["pln_sh21_08_03"] = "KAHRETSİN, POLİSLER BEKLEDİĞİMDEN HIZLI GELDİ! İNDİRİN ONLARI!",
["pln_sh21_09_01"] = "VAY CANINA! KARŞI BİNAYA KESKİN NİŞANCI YERLEŞTİRDİLER! BAŞINIZI EĞİN VE ONU İNDİRİN!",
["pln_sh21_09_02"] = "PİÇLER BİR KESKİN NİŞANCI GETİRDİ! CADDENİN KARŞISINDAKİ BİNADA. SİPER BULUP İNDİRİN!",
["pln_sh21_09_03"] = "POLİSLER BİR KESKİN NİŞANCI GETİRDİ! CADDENİN KARŞISINDAKİ BİNADA. NİŞAN ALIP İNDİRİN!",
["pln_sh21_10_01"] = "SWAT EKİBİ GELDİ DALLAS! İNDİR ONLARI!",
["pln_sh21_10_02"] = "SWAT EKİBİ GELDİ! DALLAS, ONLARI İNDİRMELİSİN!",
["pln_sh21_10_03"] = "PİÇLER SWAT EKİBİNİ ÇAĞIRDI! TAMAM DALLAS, ÇAYLAK OLMADIĞINI GÖSTER, İNDİR ONLARI!",
["pln_sh21_11_01"] = "İYİ İŞ DALLAS. ŞİMDİ KOKAİNİ ALIP MİNİBÜSE DÖN. BURADAKİ İŞİMİZ BİTTİ.",
["pln_sh21_11_02"] = "SİZİNLE UĞRAŞMAMALARI GEREKTİĞİNİ İYİCE GÖSTERDİNİZ. ŞİMDİ KOKAİNİ ALIP MİNİBÜSE DÖNÜN. BURADAN GİTME VAKTİ.",
["pln_sh21_11_03"] = "ETKİLEYİCİ İŞ, DALLAS! TAMAM, KOKAİNİ ALIP MİNİBÜSE KOŞ.",
["pln_sh21_12_01"] = "İŞTE BÖYLE, BAŞARDIN! KOKAİNİ MİNİBÜSE AT DA GİDELİM.",
["pln_sh21_12_02"] = "BAŞARDINIZ! ŞİMDİ KOKAİNİ ARKAYA ATIN DA GİDELİM.",
["pln_sh21_12_03"] = "İYİ İŞ! KOKAİNİ MİNİBÜSE ATIP ÇIK ORADAN!",
["pln_sh21_brf_01_01"] = "TAMAM DALLAS. BİRLİKTE ÇALIŞMAYALI İKİ YIL OLDU. SENDE HÂLÂ O BECERİNİN OLDUĞUNU GÖRMEM GEREKİYOR. BASİT BİR ŞEYLE BAŞLAYALIM, OLUR MU? BİR TANIDIĞIM GEÇENLERDE KOKAİN ALIŞVERİŞİNDE AŞAĞILIK BİR MAFYA HERİFİNE SOYULMUŞ. GECE KULÜBÜNE GİRİP ÇALINAN KOKAİNİ BULMAYA VE GERİ ALMAYA ÇALIŞMANI İSTİYORUM. KOLAY, DEĞİL Mİ?",
["pln_sh21_cbf_01_01"] = "GECE KULÜBÜNE GİRİP ÇALINAN KOKAİNİ GERİ AL.",
["pln_sh21_cbf_01_02"] = "BU KOLAY BİR İŞ. GİRİN, KOKAİNİ ALIN VE ÇIKIN.",
["pln_sh21_intro_01_01"] = "TAMAM, ÖNCE EN ÖNEMLİ ŞEY. HER PROFESYONEL SOYGUNCU GİBİ ÇEVREDE ‘KEŞİF’ YAPARAK BAŞLAYACAĞIZ. ",
["pln_sh21_intro_01_02"] = "GECE KULÜBÜNDEYİZ. DANS ETME VAKTİ. EĞLENCE BAŞLAMADAN ÖNCE BİRAZ \"KEŞİF\" YAP. ÖNCE ETRAFI KOLAÇAN ET, DOĞAL DAVRAN.",
["pln_sh21_intro_01_03"] = "ESKİ GÜNLERDEKİ GİBİ EĞLENMEYE HAZIR MISIN DALLAS?",
["pln_sh22_01_01"] = "SİZİ ALMAYA HELİKOPTER GELİYOR AMA BİRAZ SÜRECEK.",
["pln_sh22_01_02"] = "SENİ ALMASI İÇİN HELİKOPTER AYARLIYORUM AMA BİRAZ ZAMAN ALACAK.",
["pln_sh22_01_03"] = "SİZİ ALMASI İÇİN HELİKOPTER ÇAĞIRIYORUM!",
["pln_sh22_02_01"] = "HASS...! SWAT EKİBİ GELİYOR! İNDİRİN ONLARI!",
["pln_sh22_02_02"] = "DİKKAT, SWAT EKİBİ GELDİ! ",
["pln_sh22_02_03"] = "PİÇLER SWAT ÇAĞIRDI! CEHENNEMİ YAŞATIN!",
["pln_sh22_03_01"] = "DİKİLİP DURMAYIN! EKİP ARKADAŞINIZI KALDIRIN!",
["pln_sh22_03_02"] = "EKİP ARKADAŞINIZ DÜŞTÜ! YARDIM EDİN!",
["pln_sh22_03_03"] = "ARKADAŞINIZIN YARDIMINIZA İHTİYACI VAR! GİDİN!",
["pln_sh22_04_01"] = "MİNİBÜSTEKİ KOKAİNİ UNUTMA, YOKSA HEPSİ BOŞUNA OLUR!",
["pln_sh22_04_02"] = "KOKAİNİ MİNİBÜSTEN ALIN!",
["pln_sh22_04_03"] = "DALLAS! POLİSLERDEN ÖNCE MİNİBÜSTEN KOKAİNİ AL!",
["pln_sh22_05_01"] = "DÜKKÂNA GİRİP BİR REHİNE ALIN Kİ POLİSLERDEN DOSTUMUZU TAKASLA GERİ ALABİLELİM.",
["pln_sh22_05_02"] = "DÜKKÂNA GİRİP TEZGÂHTARI REHİN ALIN Kİ POLİSLERLE TAKAS YAPABİLELİM.",
["pln_sh22_05_03"] = "DÜKKÂNA GİDİP BİR REHİNE ALIN Kİ POLİSLERLE PAZARLIK YAPIP DOSTUMUZU GERİ ALABİLELİM.",
["pln_sh22_06_01"] = "MÜKEMMEL. ŞİMDİ REHİNEYİ ARKA TARAFA, POLİSLERDEN UZAĞA GÖTÜR.",
["pln_sh22_06_02"] = "BURADA ÇOK FAZLA KURŞUN UÇUŞUYOR! REHİNEYİ ARKADAKİ ODAYA GÖTÜRÜN.",
["pln_sh22_06_03"] = "TAMAM, GÜZEL. ŞİMDİ REHİNEYİ ARKADAKİ ODAYA GÖTÜRÜN.",
["pln_sh22_07_01"] = "ARKANIZA YASLANIN, POLİSLE ANLAŞMAYI BEN YAPAYIM.",
["pln_sh22_07_02"] = "BEN POLİSLERLE ANLAŞIRKEN SİZ ŞİMDİLİK RAHAT OLUN.",
["pln_sh22_07_03"] = "DOSTUMUZU GERİ ALMAK İÇİN POLİSLERLE ANLAŞACAĞIM. SİZ BEKLEYİN.",
["pln_sh22_08_01"] = "TAMAM, HALLETTİM. DOSTUMUZU TAKASLA GERİ ALMAK İÇİN REHİNEYİ ŞİMDİ BIRAKIN.",
["pln_sh22_08_02"] = "TAMAM, ANLAŞMAYI YAPTIM. REHİNENİN KELEPÇELERİNİ ÇIKARIN DA EKİP ARKADAŞIMIZI GERİ ALALIM.",
["pln_sh22_08_03"] = "ANLAŞMA TAMAM. ARTIK TAKASI YAPABİLİRSİNİZ.",
["pln_sh22_09_01"] = "KOKAİNİ BIRAK, BİR DOKTOR ÇANTASI YERLEŞTİRİP İYİLEŞ.",
["pln_sh22_09_02"] = "TAMAM, BU ARADA İYİLEŞİN. KOKAİNİ BIRAKIN VE BİR DOKTOR ÇANTASI KOYUN.",
["pln_sh22_09_03"] = "BU ZAMANI İYİLEŞMEK İÇİN KULLANIN. KOKAİNİ BIRAKIP BİR DOKTOR ÇANTASI YERLEŞTİRİN.",
["pln_sh22_10_01"] = "GÜZEL. ŞİMDİ KOKAİNİ TEKRAR ALMAYI UNUTMAYIN.",
["pln_sh22_10_02"] = "BİRAZ İLACIN ÇÖZEMEYECEĞİ ŞEY YOK. ŞİMDİ KOKAİNİ ALIN.",
["pln_sh22_10_03"] = "TAMAM, YİNE SAVAŞA HAZIR OLMALISIN. KOKAİNİ AL.",
["pln_sh22_11_01"] = "TAMAM, ÇIKIN ORADAN. KİLİDİ AÇACAK VAKTİNİZ YOK, KAPI KOLUNU VURUN GİTSİN.",
["pln_sh22_11_02"] = "GİTME VAKTİ. KİLİT AÇMAYA ZAMAN YOK, KAPI KOLUNU VURUP KOPARIN.",
["pln_sh22_11_03"] = "TAMAM, GİTME VAKTİ. O KAPININ KİLİDİNİ MAYMUNCUKLA AÇMAYIN, KOLUNU VURUP KOPARIN.",
["pln_sh22_12_01"] = "DURUN! O POLİSİ VURMAYIN, YALNIZ! GÖZÜNÜ KORKUTUP BİZİM İÇİN ÇALIŞTIRIN!",
["pln_sh22_12_02"] = "O POLİSİ VURMAYIN! ÜÇE BİRSİNİZ. KORKUTUP BİZİM İÇİN ÇALIŞTIRIN.",
["pln_sh22_12_03"] = "DURUN, VURMAYIN! KORKUTUP TESLİM OLMASINI SAĞLAYIN. İŞİMİZE YARAYABİLİR.",
["pln_sh22_13_01"] = "HELİKOPTERİN SİZİ ALACAĞI ÇATIYA GİTME VAKTİ!",
["pln_sh22_13_02"] = "HEMEN ÇATIYA ÇIKIP HELİKOPTERİ BEKLEYİN!",
["pln_sh22_13_03"] = "ÇATIYA ÇIKIP \"HELİKOPTEERİ\" BEKLEYİN!",
["pln_sh22_14_01"] = "ÇATIDA SWAT VAR! GÖRÜNÜŞE GÖRE ÖYLE KOLAY VAZGEÇMEYECEKLER!",
["pln_sh22_14_02"] = "DİKKAT! ÇATIDA SWAT!",
["pln_sh22_14_03"] = "DİKKAT! SWAT!",
["pln_sh22_15_01"] = "DİKKAT, KESKİN NİŞANCI!",
["pln_sh22_15_02"] = "KESKİN NİŞANCI! SİPER ALIN!",
["pln_sh22_15_03"] = "KESKİN NİŞANCI GETİRDİLER!",
["pln_sh22_16_01"] = "PİÇLER SHIELD ÇAĞIRDI! YANDAN DOLANMAYA ÇALIŞ!",
["pln_sh22_16_02"] = "LANET, SHIELD! ARKASINA GEÇMEYE ÇALIŞIN!",
["pln_sh22_16_03"] = "SHIELD! ETRAFINDAN DOLANIP İNDİRİN!",
["pln_sh22_17_01"] = "HELİKOPTER GELDİ! KOKAİNİ İÇİNE ATIN!",
["pln_sh22_17_02"] = "TAMAM, SİZİ ALACAK HELİKOPTER BU! KOKAİNİ ÇABUCAK YÜKLEYİN!",
["pln_sh22_17_03"] = "ARACIN BURADA! KOKAİNİ HELİKOPTERE AT!",
["pln_sh22_18_01"] = "İŞTE BU! GİTME VAKTİ! HÂLÂ FORMDASIN DALLAS!",
["pln_sh22_18_02"] = "İYİ İŞ! HÂLÂ FORMUNDA OLDUĞUNU KANITLADIN, DALLAS.",
["pln_sh22_18_03"] = "BENİ ETKİLEDİN DALLAS. İKİ YIL SENİ HİÇ YAVAŞLATMAMIŞ. ŞİMDİ ÇIK ORAYA!",
["pln_sh22_brf_01_01"] = "DAHA BİTMEDİ DALLAS! BEKLEDİĞİMDEN FAZLA DİKKAT ÇEKTİK, POLİSLER PEŞİNİZDE. ÖNÜNÜZÜ KESİP İŞİ SARPA SARDIRMADAN ONLARI ATLATMAYA ÇALIŞIN! ",
["pln_sh_int_01_01"] = "TEKRAR HOŞ GELDİN! GÖRDÜN MÜ, TELEFONA CEVAP VERMEN BİLE GEREKMEDİ. HER ZAMANKİ GİBİ GÖZÜM ÜSTÜNDE!",
["pln_sh_int_02_01"] = "GERÇEK SOYGUNCULARA LAYIK BİR TATİL GEÇİRDİĞİNE EMİNİM. ÇOK ÇALIŞTIN, İHTİYACIN VARDI AMA SANA BİR KEZ DAHA İHTİYACIMIZ VAR.",
["pln_sh_int_03_01"] = "MUTFAĞIN ARKASINDA BİR ODA VAR. ORAYA GİT, BAŞLANGIÇ EKİPMANINI HAZIRLADIM.",
["pln_sh_int_04_01"] = "ÖN SİPARİŞ PAKETİNİ ARKA TARAFA KOYDUM. GİT AL!",
["pln_sh_int_05_01"] = "İŞTE OLDU. ŞİMDİ MASKENİ TAK.",
["pln_sh_int_06_01"] = "TAMAM, BENİ NET DUYDUĞUNUZU VARSAYIYORUM. KAYBEDECEK VAKTİMİZ YOK, DOĞRUDAN BAŞLAYALIM.",
["pln_sh_int_07_01"] = "ÖNCELİKLE, O BAŞLANGIÇ KİTİNİN DIŞINDA ARKA SOKAKTA SENİ BEKLEYEN BİR PAKET DAHA VAR.",
["pln_sh_int_08_01"] = "SUÇ ORTAĞIM SANA YARDIM EDECEK. BEKLİYOR.",
["pln_sh_int_09_01"] = "YUKARI BAKIN.",
["pln_sh_int_10_01"] = "YAKALA!",
["pln_sh_int_11_01"] = "İYİ YAKALADIN! BUNA HAZIRSIN!",
["pln_sh_int_12_01"] = "GÜZEL! ÖNCEDEN YOLLADIĞINIZ PARA BU. OVERKILL TEŞEKKÜRLERİNİ SUNAR!",
["pln_sh_int_13_01"] = "O ÇANTAYI ALIN, BAŞLANGIÇ İÇİN BİRAZ PARA. OTURMA ODASINA GÖTÜRÜN.",
["pln_sh_int_14_01"] = "ALIN. AKLADIĞIM PARANIZ BU. OVERKILL'E CÖMERT KATKINIZ İÇİN BİRAZ DA FAZLASI VAR.",
["pln_sh_int_15_01"] = "İÇERİ GİRİP SAYABİLMEK İÇİN ÇANTAYI MASAYA BIRAKIN. UMARIM HEPSİ TAMDIR.",
["pln_sh_int_16_01"] = "TAMAM, ŞİMDİ SAY.",
["pln_sh_int_17_01"] = "GÜZEL, 25 BİN. İYİ HARCAYIN.",
["pln_sh_int_18_01"] = "TAMAM, BAŞLANGIÇ İÇİN 5 BİN OLMALI.",
["pln_sh_int_19_01"] = "BİRAZ NAKİT. BAŞLANGIÇ İÇİN HOŞ GELDİN HEDİYESİ SAYIN. ÇOK DAHA FAZLASINI KAZANACAĞINIZI UMUYORUM.",
["pln_sh_int_20_01"] = "MERAK ETMEYİN, ARKA TARAFTA SİZİ KİMSE DUYMAZ. YİNE DE TEDBİRİ ELDEN BIRAKMAYIN, SESSİZ OLUN...",
["pln_sh_int_21_01"] = "ŞİMDİ PARAYI AL.",
["pln_sh_int_22_01"] = "TAMAM, BURASI GÜVENLİ EVİN. İŞ DIŞINDA ZAMANINI BURADA GEÇİRECEKSİN. ŞİMDİLİK PEK BİR ŞEY YOK AMA BİRAZ ZAMAN VER. ÜZERİNDE ÇALIŞIYORUM. YAKINDA BİRAZ DEKORASYON YAPMANA DA İZİN VERECEĞİM.",
["pln_sh_int_23_01"] = "ELBETTE BİLİYORSUNUZDUR, BU GÜVENLİ EVİN SUNDUKLARI BU KADAR DEĞİL. ÜZERİNDE ÇALIŞTIĞIM ŞEYİ GÖSTEREYİM.",
["pln_sh_int_24_01"] = "DIŞARI ÇIKIP İŞE BAŞLAMAK İSTEDİĞİNİZİ BİLİYORUM AMA NE YAPACAĞINIZI BİLDİĞİNİZDEN EMİN OLMALIYIM. ZAMAN DEĞİŞİYOR, YENİ EKİPMANLAR, YENİ OYUNCAKLAR. HER ŞEYİ BİLDİĞİNİZİ KONTROL ETMEK İSTİYORUM SADECE.",
["pln_sh_int_25_01"] = "ŞU HEYKELİ GÖRÜYOR MUSUN? ADALET TANRIÇASI. ELİNE BİRAZ PARA VER.",
["pln_sh_int_26_01"] = "AŞAĞI İN, SANA BİR SIR GÖSTERECEĞİM.",
["pln_sh_int_27_01"] = "BEYLER... GÜVENLİ EVİNİZE HOŞ GELDİNİZ.",
["pln_sh_int_28_01"] = "TAMAM, SOLUNDA CRIME.NET İSTASYONUN VAR. SÖZLEŞMELERİNİ BURADAN ALIRSIN. SAĞINDA GÜVENLİK KAMERALARIN VAR. ETRAFA BAK, DAHA FAZLASINI ANLATIRIM.",
["pln_sh_int_29_01"] = "EVET, TAM İLERİDE ÖZEL KASA DAİREN VAR. ORAYI DOLDURACAĞIZ.",
["pln_sh_int_30_01"] = "AŞAĞIDA KENDİ KASA DAİREN. SAĞDA KAMERA SİSTEMİN. SOLDA CRIME.NET İSTASYONUN. BAŞLAYALIM.",
["pln_sh_int_31_01"] = "CRIME.NET'E HOŞ GELDİN. BURASI SENİN SUÇ TOPLULUĞUN. SENİ DC'NİN HER YANINDA SENİN GİBİLERİ ARAYAN SUÇ BAĞLANTILARIYLA BULUŞTURACAĞIM. BU AĞ KARŞILIKLI GÜVEN VE PARA ÜZERİNE KURULU.",
["pln_sh_int_31_01b"] = "BUNU İKİ YILI AŞKIN SÜREDİR BÜYÜTÜYORUZ. KENDİ BAŞINA KURABİLECEĞİN BİRÇOK YENİ BAĞLANTI DA OLMALI.",
["pln_sh_int_32_01"] = "YENİ BİR BAĞLANTINIZ VAR. ADI VLAD. CRIME.NET'TEN BULUN, BAKALIM BİZE NE AYARLAYABİLECEK.",
["pln_sh_int_33_01"] = "CRIME.NET'TE YENİ BAĞLANTI VAR MİLLET. GÖZÜ YÜKSEKLERDE, ŞAİBELİ BİR SİYASETÇİ. ŞİMDİLİK ONA THE ELEPHANT DİYORUZ. BİR BAKIN.",
["pln_sh_int_34_01"] = "CRIME.NET'İN GÜNCELLENDİ. ŞEHİRDE BÜYÜK BİR UYUŞTURUCU KARTELİ LİDERİ VAR. ADI HECTOR MORALEZ. BİR BAK.",
["pln_sh_int_35_01"] = "BURAYA BİRKAÇ ÇANTA KOYDUM. FARKLI AĞIRLIKLARI DENEYEBİLİRSİN. ALTIN AĞIRDIR, BİLİRSİN. HİSSİNİ VE NE KADAR UZAĞA ATABİLDİĞİNİ ANLAMAK İYİ OLUR.",
["pln_sh_int_36_01"] = "KAPILAR. BUNLARI DA DENEYEBİLİRSİN. AÇMANIN BİRÇOK YOLU OLDUĞUNU UNUTMA. BİZİM İŞİMİZDE KAPILARI KAPATMAK ANLAMSIZ, ÖNEMLİ OLAN AÇMAK.",
["pln_sh_int_37_01"] = "BU ODAYI SEVİYORUM. SİLAHLARINI BURADA DENE.",
["pln_sh_int_38_01"] = "ATEŞ EDİN. YENİDEN DİKİLECEKLER.",
["pln_sh_int_39_01"] = "BAKALIM, BAŞKA NE VAR. BURADA HER NESNEYİ DENEYEBİLİRSİN. EKİPMANI ALIP UYDUĞU BİR ŞEY BUL YETER.",
["pln_sh_int_40_01"] = "YANİ KASALARI MATKAPLA AÇABİLİRSİNİZ, BECERİNİZ VARSA MAYMUNCUKLA BİLE AÇARSINIZ.",
