["pln_sh_int_42_01"] = "KAMERALAR. HERKES KAMERALARDAN NEFRET EDER. GİZLİLİĞİNİZİ SINAMANIZ İÇİN BİRKAÇ FARKLI DÜZENİ OLAN BİR ODA HAZIRLADIM. BAŞARAMAMAK AYIP DEĞİL. SİZE ATEŞ EDEN DE YOK, O DA GÜZEL.",
