["pln_tr1_brf_01_01"] = "BULDUĞUNUZ PLAN, RC1 KOD ADLI YENİ BİR PİYADE TARETİ İÇİNDİ. TAM YENİ NESİL BİR ŞEY. BİRAZ DAHA ARAŞTIRINCA PENTAGON'A GİDEN ÖZEL KİRALANMIŞ BİR TRENİN HABERİNİ ALDIM. DEMİRYOLU AĞINA GİRDİM. MAKASLARDAKİ BİR AKSAKLIK YÜZÜNDEN DURDUKLARINI SANIYORLAR. ÜÇ VAGON VAR. BİRİNDE DONANIM, DİĞER İKİSİNDE MÜHİMMATI VAR. HEPSİ SATILIR AMA ÖNCELİĞİNİZ TARET. SİZİ BEKLEMİYOR OLACAKLAR.",
