["pln_ukranian_stage1_47_any_02"] = "VARSA YÖNLENDİRİLMİŞ PATLAYICI KULLANABİLİRSİNİZ. MATKAPTAN HIZLIDIR AMA BİRİ DUYABİLİR.",
