["pln_ukranian_stage1_48_any_05"] = "KESKİN NİŞANCI ÇAĞIRIYORLAR. ÇOK FAZLA SİVİL KAYBI VAR.",
["pln_ukranian_stage1_49_any_01"] = "POLİS KESKİN NİŞANCILARI, LANET OLSUN! ŞİMDİ GERÇEKTEN YANDIK!",
["pln_ukranian_stage1_49_any_02"] = "KESKİN NİŞANCILAR YERLEŞTİ, BAŞINIZI EĞİN!",
["pln_ukranian_stage1_49_any_03"] = "KESKİN NİŞANCILAR! ÇOK FAZLA SİVİL ÖLDÜ, ORADA KALAMAZSINIZ!",
["pln_ukranian_stage1_49_any_04"] = "KESKİN NİŞANCILAR GELDİ. BURADA KALAMAYIZ!",
["pln_ukranian_stage1_50_any_01"] = "TAMAM, ARADIĞIMIZ TAÇ BU!",
["pln_ukranian_stage1_50_any_02"] = "İŞTE ORADA! SONUNDA!",
["pln_ukranian_stage1_50_any_03"] = "TAMAM, TAÇ BU!",
["pln_ukranian_stage1_51_any_01"] = "KAÇIŞ MİNİBÜSÜ HAZIR, HAZIR OLDUĞUNUZDA GİDİN!",
["pln_ukranian_stage1_52_any_01"] = "MUHTEŞEM! BİZE FAZLADAN PARA, İÇKİLER BENDEN!",
["pln_ukranian_stage1_52_any_02"] = "FAZLADAN HER GANİMET CEPLERE GİDER. NE KADAR ÇOK, O KADAR İYİ!",
["pln_ukranian_stage1_52_any_03"] = "BEKLEDİĞİMDEN ÇOK GANİMET. AFERİN!",
["pln_ukranian_stage1_52_any_04"] = "SAĞLAM VURGUN. İYİ İŞ ÇIKARDINIZ!",
["pln_ukranian_stage1_53_any_01"] = "KİMSE SİZİ DUYMADI BİLE. GERÇEK PROFESYONELLER!",
["pln_ukranian_stage1_53_any_02"] = "PROFESYONEL OLDUĞUNUZU BİLİYORDUM, KİMSE SİZİ DUYMADI BİLE. MÜTHİŞ!",
["pln_ukranian_stage1_53_any_03"] = "SOĞUKKANLI VE HESAPLI, TAM İSTEDİĞİMİZ GİBİ!",
["pln_ukranian_stage1_54_any_01"] = "HARİKA! ARTIK KAÇABİLİRSİNİZ AMA FAZLADAN GANİMETİN PEŞİNE DE DÜŞEBİLİRSİNİZ.",
["pln_ukranian_stage1_54_any_02"] = "TAMAM, SEÇİM ŞU: ŞİMDİ KAÇIN YA DA DAHA FAZLA GANİMET TOPLAYIN. KARAR SİZİN!",
["pln_ukranian_stage1_55_any_01"] = "ARA SOKAKLARDA HAREKET VAR. TETİKTE OLUN!",
["pln_ukranian_stage1_55_any_02"] = "ARA SOKAKLARDA HAREKET VAR. UYANIK OLUN!",
["pln_ukranian_stage1_brief_01"] = "VLAD, DMİTRİ DENEN BU HERİFTEN HİÇ HOŞLANMIYOR. MEMLEKETTEN KALMA HUSUMETLERDEN BİRİ; BELKİ KIZ KARDEŞİNİ FALAN SİKMİŞTİR. ",
["pln_ukranian_stage1_brief_01b"] = "NEYSE, ADAMIN HESABINI KAPATMASINA YARDIM EDELİM. TACI ALIYORUZ, ANLADIĞIM KADARIYLA ARKA ODADA.",
["pln_ukranian_stage1_brief_01c"] = "POLİSİ ÇOK ERKEN ÜSTÜNÜZE ÇEKMEYİN, YOKSA KAÇIŞ ZOR OLUR. DESTEKLERİNİZİ KONTROL EDİN. GİDELİM.",
["pln_ukranian_stage1_end_a_01"] = "TAMAM, GİDİYORUZ. TAÇ VLAD'A GİDECEK, İSTEDİĞİ İNTİKAMI ALACAK. YARDIMCI OLABİLDİĞİMİZE SEVİNDİM. GÜVENLİ EVDE GÖRÜŞÜRÜZ.",
["pln_ukranian_stage1_end_a_02"] = "GÜZEL İŞ. VLAD İSTEDİĞİNİ ALDI. FAZLADAN BİRAZ MÜCEVHER FENA OLMAZDI, YALAN SÖYLEMEYEYİM, AMA YARIN DA GÜN VAR.",
["pln_ukranian_stage1_end_a_03"] = "O TACIN PARASINI ALMA VAKTİ. VLAD SEVİNECEK. AZ ÖNCE BİR DÜĞÜNÜ BASTINIZ.",
["pln_ukranian_stage1_end_b_01"] = "GÜZEL, MÜCEVHERLER VE TAÇ TAMAM. VLAD'DAN PARAYI ALMA VAKTİ GELDİ. ÇOK SEVİNECEK. ",
["pln_ukranian_stage1_end_b_02"] = "GÜZEL İŞ EKİP. TAÇ GÜVENDE, VLAD DA SEVİNÇTEN YERİNDE DURAMIYOR. GİDİP DELİ RUS'U GÖRELİM.",
["pln_ukranian_stage1_end_b_03"] = "BUNA NE DİYORLAR? BLİNG Mİ? NEYSE, PARA KAZANMA VAKTİ.",
["pln_ukranian_stage1_end_c_01"] = "İŞTE SOYGUN BUNA DENİR. HER ŞEYİ ALMAKTA İYİ İŞ ÇIKARDINIZ, ÇOK UĞRAŞTINIZ. TAÇ DA BU DURUMDA İKRAMİYE OLDU. VLAD ÇOK MUTLU. ",
["pln_ukranian_stage1_end_c_02"] = "BU İŞİN ŞEREFİNE İÇKİLER BENDEN... MÜKEMMEL SOYGUNDU MİLLET. ",
["pln_ukranian_stage1_end_c_03"] = "PÜRÜZSÜZ OPERASYON, EKİP. HER ŞEYİ VE TACI ÇALDINIZ. ŞEHİRDEYİZ, BURADA ADIMIZI DUYURUYORUZ. HARİKA İŞ.",
["pln_ukranian_stage1_intro_a_01"] = "UNUTMAYIN. GİRİN, TACI ALIN. ŞANSINIZ VARSA BİRAZ DAHA MÜCEVHER İÇİN DÜKKÂNI SOYUN. İÇERİSİ DOLU. AMA GÜVENLİKÇİLERE, KAMERALARA, METAL DEDEKTÖRLERİNE DİKKAT EDİN. ",
["pln_ukranian_stage1_intro_a_01b"] = "SAHİBİ GÜVENLİĞE KAFAYI TAKMIŞ. KAÇIŞ MİNİBÜSÜ BIRAKILDIĞINIZ YERİN YAKININDA OLACAK.",
["pln_ukranian_stage1_intro_a_02"] = "TAMAM, VLAD İÇİN HER ZAMANKİ İŞ. TACI ALACAĞIZ, İSTERSENİZ MÜCEVHERLERİ DE. TACI ALDIĞINIZ SÜRECE BU İŞİ İSTEDİĞİNİZ GİBİ YAPABİLİRSİNİZ. BİTİNCE MİNİBÜSE DÖNÜN. ",
["pln_ukranian_stage1_intro_a_03"] = "ORTALIĞI KOLLAYIN MİLLET, POLİSLER ÇOK ERKEN GELSİN İSTEMEYİZ. KAMERA VE MUHAFIZLARDAN KAÇININ. YAPABİLİRSENİZ EK MÜCEVHERLERİ DE ALIN. GELDİĞİMİZ MİNİBÜSLE ÇIKACAĞIZ.",
["pln_vih_01_01"] = "KAÇIŞ ARACI GELDİ! TEKRAR EDİYORUM, KAÇIŞ ARACI GELDİ!",
["pln_vih_01_02"] = "KAÇIŞ ARACI GELDİ. GİDEBİLİRİZ!",
["pln_vih_01_03"] = "KAÇIŞ ARACI GELDİ!",
["pln_vih_01_04"] = "KAÇIŞ ARACI GELDİ, HAZIR OLUN!",
["pln_vih_01_05"] = "KAÇIŞ ARACI YENİ GELDİ. HAZIR MISINIZ?",
["pln_vih_01_06"] = "KAÇIŞ ARACI OLAY YERİNDE. HAZIR OLDUĞUNUZDA BEYLER!",
["pln_vih_02_01"] = "ÇANTALARI MİNİBÜSE GETİRİN.",
["pln_vih_02_02"] = "O ÇANTALARI GANİMET MİNİBÜSÜNE YÜKLEYİN.",
["pln_vih_02_03"] = "ÇANTALARI MİNİBÜSE GÖTÜRMENİZ GEREKİYOR.",
["pln_vih_02_04"] = "GANİMETİ MİNİBÜSE GÖTÜRÜN.",
["pln_vih_02_05"] = "ÇANTALARI MİNİBÜSE TAŞIMAYA DEVAM EDİN, MİLLET.",
["pln_vih_02_06"] = "ÇANTALARI MİNİBÜSE KOYUN MİLLET.",
["pln_vit_cbf_01"] = "TAMAM MİLLET. İŞTE BU. GELMİŞ GEÇMİŞ EN BÜYÜK SOYGUN. BUNUN İÇİN ÇALIŞTINIZ. SİKTİĞİMİN BEYAZ SARAY'I! İÇERİDE BÜTÜN SORUNLARIMIZIN CEVABI VAR. BUNUN ÖNEMLİ BİR PARÇASI DA BİR DİZİ BELGE: HÂLÂ YASAL VE GEÇERLİ OLAN AMA ÜZERLERİNDE HİÇ İSİM BULUNMAYAN BAŞKANLIK AFLARI! ONLARI ALIRSANIZ HİÇBİR CEZA ALMADAN KURTULUP EMEKLİ OLABİLİRSİNİZ. FAZLA VAKTİM KALMADI; LANET MURKY VİRÜSÜ HER SANİYE BEDENİMİN BİRAZ DAHA FAZLASINI YİYİP BİTİRİYOR AMA KAHRETSİN, BU İŞİ SONUNA KADAR GÖTÜRECEĞİM. BUNU BENİM YERİME LOCKE YÖNETECEK AMA MERAK ETMEYİN... BURALARDA OLACAĞIM. OVAL OFİS'İ DE ÇOK DAĞITMAYIN, ANLADINIZ MI?",
["pln_vit_end_win_01"] = "SİZ... BAŞARDINIZ MİLLET. YAPTINIZ. LANET WHİTE HOUSE'U! SİZİNLE GURUR DUYUYORUM. HEM DE ÇOK! ARTIK ÖZGÜRSÜNÜZ... ÖZGÜRCE... AH... BU...? AMAN TANRIM... ",
["pln_watchdogs_new_stage1_01_any_01"] = "TAMAM MİLLET, ORADAN ÇIKMANIN TEK YOLU O KAPILAR.",
["pln_watchdogs_new_stage1_01_any_02"] = "TAMAM, BENİ DİNLEYİN. O KAPILAR AÇILINCA ÇIKMAYA HAZIR OLSANIZ İYİ OLUR.",
["pln_watchdogs_new_stage1_01_any_03"] = "BAKIN, ATEŞ ETMEYE BAŞLADIKLARINDA O KAPILAR DAYANMAYACAK.",
["pln_watchdogs_new_stage1_02_any_01"] = "HEY, DIŞARIDA BİR SÜRÜ POLİS VAR! KAPILAR AÇILINCA ONLARLA BAŞ ETMEYE HAZIRLANIN.",
["pln_watchdogs_new_stage1_02_any_02"] = "HEY, EMNİYETİN YARISI DIŞARIDA. KENDİNİZİ SAVUNMAYA HAZIR MISINIZ!?",
["pln_watchdogs_new_stage1_02_any_03"] = "DIŞARIDA ETRAFIMIZI SARDILAR. SAVAŞA HAZIRLANIN!",
["pln_watchdogs_new_stage1_03_any_01"] = "ONLARI DURDURUN, ŞU AN KAÇIŞ ŞOFÖRÜ ARIYORUM!",
["pln_watchdogs_new_stage1_03_any_02"] = "DAYANIN! DAYANIN! ŞU LANET ANDA SİZE BİR KAÇIŞ ŞOFÖRÜ ARIYORUM!",
["pln_watchdogs_new_stage1_03_any_03"] = "KARŞI ATEŞ AÇIN! SİZE BİR ŞOFÖR AYARLIYORUM, ONLARI KOKAİNDEN UZAK TUTMALISINIZ!",
["pln_watchdogs_new_stage1_03_any_04"] = "KARŞI ATEŞ AÇIN, ONLARI MEVZİNİZE YAKLAŞTIRMAYIN! SİZE LANET BİR ŞOFÖR BULACAĞIM! TAMAM MI!?",
["pln_watchdogs_new_stage1_04_any_01"] = "TAMAM, SİZİ ALACAK ŞOFÖR HATTA. ŞİMDİ BAĞLIYORUM.",
["pln_watchdogs_new_stage1_04_any_02"] = "TAMAM, SİZE ŞOFÖR BULDUM, BAĞLIYORUM.",
["pln_watchdogs_new_stage1_04_any_03"] = "MİLLET, SİZİ ALACAK ŞOFÖR BURADA, YANIMDA.",
["pln_watchdogs_new_stage1_05_any_01"] = "HERKES ANLADI MI!? GELMESİNE ÜÇ DAKİKA VAR. O ZAMANA KADAR ONLARI KOKAİNDEN UZAK TUTUN!",
["pln_watchdogs_new_stage1_05_any_02"] = "HERKES DUYDU MU? BURAYA GELMESİNE ÜÇ DAKİKA VAR. ONLARI DURDURUN! ",
["pln_watchdogs_new_stage1_05_any_03"] = "UMARIM HERKES DUYDU! SİZİ ALACAK ARABANIN GELMESİNE ÜÇ DAKİKA VAR! SAVUNUN! SAVUNUN! SAVUNUN!",
["pln_watchdogs_new_stage1_06_any_01"] = "İKİ DAKİKA, ARAÇ BURAYA GELENE KADAR İKİ DAKİKA! ONLARI DURDURUN!",
["pln_watchdogs_new_stage1_06_any_02"] = "HEY, SİZİ ALACAK ARABA İKİ DAKİKAYA BURADA OLACAK. BİRAZ DAHA SAVAŞMANIZ YETER!",
