["pln_watchdogs_new_stage1_18_any_02"] = "TAMAM, KAÇIŞ ŞOFÖRÜ FENA ATEŞ ALTINDA GELİYOR! KORUNMAZSA KURŞUNA DİZİLECEK SANIRIM.",
["pln_watchdogs_new_stage1_18_any_03"] = "KAÇIŞ ŞOFÖRÜ ŞİMDİ GELİYOR. KAÇIŞ ŞOFÖRÜ ŞİMDİ GELİYOR!",
["pln_watchdogs_new_stage1_19_any_01"] = "UCUZ ATLATTIK LAN! ŞİMDİ RIHTIMA GİDİN!",
["pln_watchdogs_new_stage1_19_any_02"] = "ZOR DURUMDA KENDİNİZİ İYİ TOPLADINIZ! ŞİMDİ ÇABUK RIHTIMA!",
["pln_watchdogs_new_stage1_20_any_01"] = "ŞOFÖRÜ VURDULAR, LANET OLSUN! ŞOFÖRÜ VURDULAR! BAŞKA BİR SEÇENEK DENEMELİYİM, DAYANIN!",
["pln_watchdogs_new_stage1_20_any_02"] = "SIÇTIK! ŞOFÖRÜ VURDULAR! ŞOFÖRÜ VURDULAR! BAŞKA BİR SEÇENEK LAZIM, DAYANIN!",
["pln_watchdogs_new_stage1_20_any_03"] = "KAÇIŞ ŞOFÖRÜNÜZÜ VURDULAR, ŞOFÖRÜNÜZ ÖLDÜ! B PLANI LAZIM, DAYANIN!",
["pln_watchdogs_new_stage1_21_any_01"] = "MİLLET! PAHALIYA PATLAYACAK AMA KAÇIŞ HELİKOPTERİ AYARLADIM. BİRKAÇ DAKİKA!",
["pln_watchdogs_new_stage1_21_any_02"] = "TAMAM MİLLET, ALTERNATİF KAÇIŞ HELİKOPTERİ YOLLADIM. YAKINDA BURADA!",
["pln_watchdogs_new_stage1_21_any_03"] = "TAMAM MİLLET, SİZE NE AYARLADIM SÖYLEYEYİM: BİR KAÇIŞ HELİKOPTERİ BULDUM, SONRA TEŞEKKÜR EDERSİNİZ. YOLDA!",
["pln_watchdogs_new_stage1_22_any_01"] = "HELİKOPTER PİLOTUNU ŞİMDİ BAĞLAYAYIM!",
["pln_watchdogs_new_stage1_22_any_02"] = "HELİKOPTER PİLOTUNU BAĞLIYORUM!",
["pln_watchdogs_new_stage1_22_any_03"] = "HELİKOPTER PİLOTUNU BAĞLAYAYIM!",
["pln_watchdogs_new_stage1_23_any_01"] = "HEY! HELİKOPTER PİLOTU BURADA! GİDİN GİDİN GİDİN!",
["pln_watchdogs_new_stage1_23_any_02"] = "TAMAM! HELİKOPTER GELDİ! GİDİN!",
["pln_watchdogs_new_stage1_23_any_03"] = "HELİKOPTER PİLOTU GELDİ! İLERLEYİN! İLERLEYİN! İLERLEYİN!",
["pln_watchdogs_new_stage1_24_any_01"] = "TAMAM! HELİKOPTER RIHTIMA GİDİYOR MİLLET; YAĞMURDAN KAÇARKEN...",
["pln_watchdogs_new_stage1_24_any_02"] = "İYİ İŞ! İŞİNİZ HENÜZ BİTMEDİĞİ İÇİN PİLOTA SİZİ RIHTIMA GÖTÜRMESİNİ SÖYLEDİM.",
["pln_watchdogs_new_stage1_24_any_03"] = "TAMAM, ŞİMDİ RIHTIMLARA GİDİYORSUNUZ. BU İŞ BİTMEDİ!",
["pln_watchdogs_new_stage1_brief_01"] = "BU İŞTE BEKÇİLİK YAPIYORUZ. KALIN CEKET GİYİN, DAHA AĞIR SİLAHLAR TAŞIYIN. HECTOR'IN NAKLİYELERİNE SALDIRILDIĞINI BİLİYORUZ. KAMYONUN ARKASINDA GİDECEKSİNİZ. KOKAİNİN BİR YERE GİTMESİNE İZİN VERMEYİN.",
["pln_watchdogs_new_stage1_end_a_01"] = "O BELADAN ÇIKACAĞINIZI BİLİYORDUM. ÜSTELİK HEPSİNİ DE ALDINIZ. HECTOR'IN TEKNESİNE HABER VERDİM. LİMANDA GÖRÜŞÜRÜZ!",
["pln_watchdogs_new_stage1_end_a_02"] = "KOKAİNİN HEPSİ TAMAM, SAPASAĞLAM GÜVENDE. SİZİN İÇİN BİLE MÜTHİŞ BİR ZAFERDİ! MALLARI TEKNEYE GÖTÜRELİM DE PARAMIZI ALALIM!",
["pln_watchdogs_new_stage1_end_b_01"] = "ÇOĞUNU ALDINIZ, ÇOĞU DA HİÇ YOKTAN İYİDİR. HECTOR DURUMU İDARE EDİŞİNİZİ BEĞENECEK. ŞİMDİ TEKNEYE GİTMENİZ GEREK!",
["pln_watchdogs_new_stage1_end_b_02"] = "KOKAİN YETERLİ, HEPSİ DEĞİL AMA YETERLİ! HECTOR'IN ADAMLARI LİMANDA. ONLARLA BULUŞUP MALI TEKNELERİNE YÜKLEMENİZ GEREK. SONRA İŞİ BİTİRİRİZ. TAMAM, PARA GÜNÜ!",
["pln_watchdogs_new_stage1_intro_a_01"] = "FBI PEŞİMİZDE! SİLAHLARI KALDIRIN! O KOKAİNİ KAYBETMEYİN!",
["pln_watchdogs_new_stage1_intro_a_02"] = "KAHRETSİN! KAMYONLARINI KENARA ÇEKİYORLAR. FBI. HECTOR'IN MALINI ALMALARINA İZİN VERMEYİN!",
["pln_watchdogs_new_stage1_intro_a_03"] = "AH, BU FBI OPERASYONU, ÇIKIŞ YOK! ATEŞ EDEREK ÇIKMAZSANIZ SİZİ İNDİRECEKLER!",
["pln_watchdogs_new_stage2_01_any_01"] = "ÇANTALARI BİR AN ÖNCE GÜVENE ALALIM. ONLARI ALMAYA BİR TEKNE GELİYOR.",
["pln_watchdogs_new_stage2_01_any_02"] = "TEKNE SİZİ ALMAYA GELİYOR. O ÇANTALARI HEMEN GÜVENE ALMANIZ GEREK.",
["pln_watchdogs_new_stage2_01_any_03"] = "TAMAM MİLLET, ÇANTALARI ALMAYA BİR TEKNE GELİYOR. ÖNCE GİDİP ONLARI TAŞIMA İÇİN GÜVENE ALIN.",
["pln_watchdogs_new_stage2_01_any_04"] = "HECTOR'IN ÇANTALARINI ALMAYA BİR TEKNE GELİYOR. ÖNCE ONLARI GÜVENCEYE ALMALIYIZ.",
["pln_watchdogs_new_stage2_02_any_01"] = "TAMAM, KAYBEDECEK VAKİT YOK. POLİS HEMEN ARKANIZDA, ÇANTALARI GÜVENE ALIN.",
["pln_watchdogs_new_stage2_02_any_02"] = "BAKIN MİLLET! KENDİNİZE GELİN DE POLİSLERDEN ÖNCE O ÇANTALARI GÜVENE ALIN. SİZİ ALACAK TEKNE YOLDA.",
["pln_watchdogs_new_stage2_02_any_03"] = "HEY, FAZLA VAKTİMİZ YOK! SİZİ ALMAK İÇİN BİR TEKNE YOLLADIM. ŞU POLİSLERDEN ÖNCE DAVRANIP ÇANTALARI GÜVENE ALIN. ",
["pln_watchdogs_new_stage2_02_any_04"] = "VAKİT AZ MİLLET! POLİSLER ALMADAN ÇANTALARI GÜVENE ALIN. TEKNE GELİYOR.",
["pln_watchdogs_new_stage2_03_any_01"] = "TAMAM, GÜZEL! ŞİMDİ SİZİ ALACAK TEKNEYE İŞARET VERMELİSİNİZ. DEPODAKİ PROJEKTÖRLER İÇİN BİR ŞALTER ARAYIN.",
["pln_watchdogs_new_stage2_03_any_02"] = "TEKNECİ NE ZAMAN YANAŞACAĞINI BİLMELİ. DEPODA PROJEKTÖR DÜĞMESİNİ ARAYIN.",
["pln_watchdogs_new_stage2_03_any_03"] = "DEPODAKİ PROJEKTÖRLE TEKNE SÜRÜCÜSÜNE İŞARET VERMENİZ GEREKİYOR. TEK YOL BU.",
["pln_watchdogs_new_stage2_05_any_01"] = "TEKNE, VİNCİN ORADAKİ 7 NUMARALI İSKELEYE GELİYOR.",
["pln_watchdogs_new_stage2_05_any_02"] = "TEKNE 7 NUMARALI RIHTIMA GELİYOR.",
["pln_watchdogs_new_stage2_05_any_03"] = "TEKNE 7 NUMARALI İSKELEYE GELİYOR.",
["pln_watchdogs_new_stage2_06_any_01"] = "DEPONUN ÖNÜNDEKİ 8 NUMARALI RIHTIMA GELİYOR.",
["pln_watchdogs_new_stage2_06_any_02"] = "TEKNE YOLDA, DEPONUN YANINDAKİ 8 NUMARALI RIHTIMA GELECEK.",
["pln_watchdogs_new_stage2_06_any_03"] = "TEKNE HAREKET EDİYOR, DEPONUN YANINDAKİ 8 NUMARALI RIHTIMA GELECEK.",
["pln_watchdogs_new_stage2_07_any_01"] = "DOKUZ NUMARALI İSKELEYE GELİYOR, HAZIR OLUN!",
["pln_watchdogs_new_stage2_07_any_02"] = "DOKUZ NUMARALI İSKELEYE GELECEK.",
["pln_watchdogs_new_stage2_07_any_03"] = "TEKNE YAKINDA 9 NUMARALI İSKELEDE OLACAK, HAZIR OLUN!",
["pln_watchdogs_new_stage2_08_any_01"] = "TAMAM, KAÇIŞ HELİKOPTERİ GELİYOR. DAYANIN!",
["pln_watchdogs_new_stage2_08_any_02"] = "HELİKOPTER HER AN ORADA OLABİLİR.",
["pln_watchdogs_new_stage2_08_any_03"] = "HELİKOPTER YOLDA MİLLET, DAYANIN!",
["pln_watchdogs_new_stage2_09_any_01"] = "KAÇIŞ HELİKOPTERİNİZ GELDİ, DEFOLUP GİTMENİZİ ÖNERİRİM!",
["pln_watchdogs_new_stage2_09_any_02"] = "KAÇIŞ HELİKOPTERİ YERİNDE. BİNAYI BOŞALTMAK İÇİN İYİ BİR ZAMAN.",
["pln_watchdogs_new_stage2_09_any_03"] = "HELİKOPTER GELDİ, ÇIKIN! ÇIKIN!",
["pln_watchdogs_new_stage2_10_any_01"] = "KAÇIŞ HELİKOPTERİNİZ BURADA. KALANINI GÜVENE ALMAYA ÇALIŞIN AMA YAPAMIYORSANIZ DEFOLUP GİTMENİZİ ÖNERİRİM!",
["pln_watchdogs_new_stage2_10_any_02"] = "HEY, KAÇIŞ HELİKOPTERİ GELDİ. ŞANSINIZA GÜVENİYORSANIZ KALAN ÇANTALARI ALIN, YOKSA ÇIKIN!",
["pln_watchdogs_new_stage2_10_any_03"] = "KAÇIŞ HELİKOPTERİ GELDİ MİLLET. AÇGÖZLÜ HİSSEDİYORSANIZ KALAN ÇANTALARI ALABİLİRSİNİZ. YOKSA KOŞMA VAKTİ!",
["pln_watchdogs_new_stage2_11_any_01"] = "HEY MİLLET! ÇANTALARI UNUTMAYIN!",
["pln_watchdogs_new_stage2_11_any_02"] = "O ÇANTALARI ALIN! BİZE LAZIM!",
["pln_watchdogs_new_stage2_12_any_01"] = "PROJEKTÖR ŞALTERİNİ BULDUNUZ MU?",
["pln_watchdogs_new_stage2_12_any_02"] = "ELEKTRİK KAYNAĞINI BULDUNUZ MU?",
["pln_watchdogs_new_stage2_12_any_03"] = "ETRAFTA ŞALTERİ ARAYIN. ORADA OLMALI.",
["pln_watchdogs_new_stage2_13_any_01"] = "MUHTEMELEN DEPONUN YANINDA SİPER ALMAK İSTERSİNİZ.",
["pln_watchdogs_new_stage2_13_any_02"] = "O DEPODA SİPER BULMAK AKILLICA OLUR.",
["pln_watchdogs_new_stage2_13_any_03"] = "SİPER BULUN, DEPO SAVUNMAYA ELVERİŞLİ GÖRÜNÜYOR.",
["pln_watchdogs_new_stage2_brief_01"] = "TAMAM, PLANLADIĞIMIZ GİBİ LİMANA GİDİN. KOKAİNİ KAMYONETTEN İNDİRİN. HECTOR'IN TEKNESİNİN GELMESİ İÇİN DEPODAKİ IŞIKLARLA İŞARET VERMENİZ GEREKECEK. GELİNCE KOKAİNİ YÜKLEYİN, GERİSİNİ KAPTAN HALLEDER.",
["pln_watchdogs_new_stage2_end_a_01"] = "KOKAİN YOLLANDI. AFERİN DENİZCİLER! GİDİP PARANIZI ALIN!",
["pln_watchdogs_new_stage2_end_a_02"] = "HER ŞEYİN KONTROLÜNÜZDE OLDUĞUNU BİLİYORDUM, GEÇEN SEFERKİ GİBİ DEĞİL. HAVALI BİR ŞEKİLDE HALLETTİNİZ! HECTOR BİZE ÇOK BORÇLU!",
["pln_watchdogs_new_stage2_end_b_01"] = "BU İŞTE BİRAZ KOKAİN KAYBETTİK AMA DAHA KÖTÜ OLABİLİRDİ. KURTARABİLDİĞİMİZİ KURTARDIĞIMIZ İÇİN HECTOR YİNE DE MEMNUN KALACAK.",
["pln_watchdogs_new_stage2_end_b_02"] = "EH, KOKAİNİN BİRAZINI KAYBETTİNİZ AMA İŞİ BİTİRDİNİZ. AFERİN! PARAMIZI YİNE ALACAĞIZ. BU ARADA ENSEYE BİRAZ BUZ KOYUN.",
["pln_watchdogs_new_stage2_intro_a_01"] = "ÇIKIN! FBI YİNE YETİŞMEDEN ÇANTALARI ALIN. BİLİYORUM, İNATÇI KÜÇÜK PİÇLER, DEĞİL Mİ?",
["pln_watchdogs_new_stage2_intro_a_02"] = "KOKAİNİ LİMANA GÖTÜRÜN. PROJEKTÖRLERLE TEKNEYE İŞARET VERİN, GELİP ALSIN.",
["pln_watchdogs_new_stage2_intro_a_03"] = "POLİSLERE TEK BİR ŞEY BİLE VERMEYİN. DEPODAKİ PROJEKTÖRLERLE HECTOR'IN ADAMLARINA İŞARET VERİP KOKAİNİ SÜRAT TEKNESİNE YÜKLEYİN. KARMAŞIK BİR ŞEY YOK.",
["pln_watchdogs_new_stage2_intro_b_01"] = "POLİS KAMYONETİN HER TARAFINDA. ALEX'E SİZİ DAHA UZAĞA İNDİRMESİNİ SÖYLEDİM, KOKAİNİ DAHA GÜVENLİ BİR YERDEN ALABİLESİNİZ DİYE. ALINCA TEKNEYE İŞARET VERİP KOKAİNİ ÇABUCAK YÜKLEYİN.",
["pln_watchdogs_new_stage2_intro_b_02"] = "HECTOR ENDİŞELİ. BU HELİKOPTERDE KOKAİNDEN ÇOK UZAĞIZ. YERE İNİNCE KOKAİNİ ALIN, KURYEYE İŞARET VERİN VE TEKNEYE YÜKLEYİN.",
["pln_watchdogs_stage1_01_any_01"] = "TAMAM, EVET, KESİNLİKLE BİR SORUNUMUZ VAR.",
