["pln_watchdogs_stage1_57_any_01"] = "DUYDUNUZ, İKİ DAKİKA. O GELENE KADAR HAYATTA KALIN VE KOKAİNİ KORUYUN!",
["pln_watchdogs_stage1_58_any_01"] = "DUYDUNUZ ONU, BİR DAKİKA. HAYATTA KALIN, KOKAİNİ ORADAN KALDIRMAYA HAZIRLANIN!",
