["pln_watchdogs_stage1_75_any_01"] = "NE YAPABİLECEĞİME BİR BAKAYIM.",
["pln_watchdogs_stage1_76_any_01"] = "BİR DAKİKA VERİN.",
["pln_watchdogs_stage1_76_any_02"] = "BİR HELİKOPTER AYARLAMAYA ÇALIŞACAĞIM.",
["pln_watchdogs_stage1_77_any_01"] = "ARABAYI PARÇALADILAR.",
["pln_watchdogs_stage1_80_any_01"] = "DEPOYA İLERLİYORLAR, TETİKTE OLUN.",
["pln_watchdogs_stage1_81_any_01"] = "MİLLET, SİZİ ALACAK ARAÇ ŞU VİNCİN YAKININDA.",
["pln_watchdogs_stage1_82_any_01"] = "O KAPI İŞİ NASIL GİDİYOR?",
["pln_watchdogs_stage1_83_any_01"] = "TAMAM, KAPIYI İYİ HALLETTİNİZ.",
["pln_watchdogs_stage1_84_any_01"] = "TAMAM ÇOCUKLAR, KAÇIŞ ARABAMIZ BURADA AMA POLİSLER TEPESİNDE.",
["pln_watchdogs_stage1_85_any_01"] = "MİLLET, KAÇIŞ ARABANIZ GELDİ! POLİS ŞOFÖRE ULAŞMADAN ACELE EDİN!",
["pln_watchdogs_stage1_85_any_02"] = "KAÇIŞ ARABANIZ GELDİ, POLİSLER ŞOFÖRÜ ÖLDÜRMEDEN ACELE ETSENİZ İYİ OLUR.",
["pln_watchdogs_stage1_86_any_01"] = "ARABAYI KORUYUN!",
["pln_watchdogs_stage1_86_any_02"] = "ONU KORUYUN!",
["pln_watchdogs_stage1_brief_01"] = "BU İŞTE BEKÇİLİK YAPIYORUZ. SAĞLAM BİR CEKET GİYİN, DAHA DA SAĞLAM SİLAHLAR GETİRİN. HECTOR'IN SEVKİYATLARININ SALDIRIYA UĞRADIĞINI BİLİYORUZ. KAMYONUN ARKASINDA GİDECEKSİNİZ. KOKAİNİN HİÇBİR YERE KAYBOLMASINA İZİN VERMEYİN.",
["pln_watchdogs_stage1_end_a_01"] = "O KARMAŞADAN ÇIKACAĞINIZI BİLİYORDUM. HEPSİNİ DE ALDINIZ! HECTOR'IN TEKNESİNE HABER VEREYİM. LİMANDA GÖRÜŞÜRÜZ.",
["pln_watchdogs_stage1_end_a_02"] = "BÜTÜN KOKAİN GÜZELCE GÜVENE ALINDI. SİZİN İÇİN BİLE MÜTHİŞ BİR ZAFERDİ. MALI TEKNEYE TAŞIYALIM DA PARAMIZI ALALIM.",
["pln_watchdogs_stage1_end_b_01"] = "ÇOĞUNU ALDINIZ. ÇOĞU, HİÇ YOKTAN İYİDİR. HECTOR İŞİNİZİ BEĞENECEK. ŞİMDİ TEKNEYE GİTMELİYİZ.",
["pln_watchdogs_stage1_end_b_02"] = "KOKAİN YETERLİ, HEPSİ DEĞİL AMA YETERLİ. HECTOR'IN ADAMLARI LİMANDA. ONLARLA BULUŞUP MALI TEKNELERİNE KOYMANIZ GEREK. SONRA İŞİ BİTİRİRİZ... TAMAM, PARA GÜNÜ.",
["pln_watchdogs_stage1_intro_a_01"] = "FBI PEŞİMİZDE! SİLAHLARI KALDIRIN! O KOKAİNİ KAYBETMEYİN!",
["pln_watchdogs_stage1_intro_a_02"] = "LANET OLSUN, KAMYONUNUZU KENARA ÇEKİYORLAR! FBI... HECTOR'IN MALINI ALMALARINA İZİN VERMEYİN!",
["pln_watchdogs_stage1_intro_a_03"] = "AH, BU BİR FBI OPERASYONU. ÇIKIŞ YOK; ATEŞ EDEREK YOL AÇMAZSANIZ SİZİ İNDİRECEKLER!",
["pln_watchdogs_stage2_12_any_01"] = "SİZİN İÇİN HELİKOPTER YOLLADIM, YAKINDA ALINACAKSINIZ.",
["pln_watchdogs_stage2_13_any_01"] = "KAÇIŞ HELİKOPTERİNİZ GELDİ. KALANLARI GÜVENE ALMAYA ÇALIŞIN AMA YAPAMIYORSANIZ ORADAN DEFOLMANIZI ÖNERİRİM!",
["pln_watchdogs_stage2_14_any_01"] = "BURASI GÖZETİM ALTINDAYMIŞ! KÖPRÜYE GİDİYORUZ!",
["pln_watchdogs_stage2_15_any_01"] = "HADİ, ÇANTALARI ALIN!",
["pln_watchdogs_stage2_16_any_01"] = "MUHTEMELEN DEPONUN YANINDA SİPER ALMAK İSTERSİNİZ.",
["pln_watchdogs_stage2_17_any_01"] = "ÇANTALARI TEKNEYE YÜKLEYİN.",
["pln_watchdogs_stage2_18_any_01"] = "DAYANIN, TEKNE HER AN ORADA OLABİLİR.",
["pln_watchdogs_stage2_19_any_01"] = "HELİKOPTER SİZİ ALMAYA HAZIR.",
["pln_watchdogs_stage2_20_any_01"] = "BİZİ ALACAK TEKNEYE YERİMİZİ GÖSTERMEMİZ GEREK. DEPOYA GİRİP PROJEKTÖRLERİ KULLANMAYA ÇALIŞIN.",
["pln_watchdogs_stage2_21_any_01"] = "ŞALTERİ BİRKAÇ KEZ AÇIP KAPATIN, DİKKATİNİ ÇEKMEYE YETER.",
["pln_watchdogs_stage2_22_any_01"] = "ŞALTERİ AÇIN, TEKNEYE İŞARET VERMELİYİZ!",
["pln_watchdogs_stage2_22_any_02"] = "O ŞALTERİ İNDİRİN!",
["pln_watchdogs_stage2_23_any_01"] = "TAMAM, TEKNEYİ GÖRÜYORUM, NEREDEYSE GELDİ. ÇANTALARLA HAZIR OLUN.",
["pln_watchdogs_stage2_24_any_01"] = "ÇANTALARI ALIYORLAR!",
["pln_watchdogs_stage2_brief_01"] = "TAMAM, PLANLADIĞIMIZ GİBİ LİMANA GİDİN. KOKAİNİ KAMYONETTEN BOŞALTIN. HECTOR'IN TEKNESİNİN GELMESİ İÇİN DEPODAN İŞARET VERMELİSİNİZ.",
["pln_watchdogs_stage2_brief_01b"] = "ORAYA GELİNCE KOKAİNİ YÜKLEYİN, TEKNECİ KALANINI HALLEDER.",
["pln_watchdogs_stage2_end_a_01"] = "KOKAİN YOLLANDI. AFERİN DENİZCİLER. GİDİP PARANIZI ALIN.",
["pln_watchdogs_stage2_end_a_02"] = "İŞLER KONTROLÜNÜZDEYDİ, BİLİYORDUM. ÖTEKİ SEFERKİ GİBİ DEĞİLDİ. ŞIK HALLETTİNİZ. HECTOR BİZE ÇOK BORÇLU.",
["pln_watchdogs_stage2_end_b_01"] = "BU İŞTE BİRAZ KOKAİN KAYBETTİK AMA DAHA KÖTÜ OLABİLİRDİ. KURTARABİLDİĞİMİZİ KURTARDIĞIMIZ İÇİN HECTOR YİNE MEMNUN OLUR.",
["pln_watchdogs_stage2_end_b_02"] = "KOKAİNİN BİRAZINI KAYBETTİNİZ AMA İŞİ BİTİRDİNİZ, AFERİN. YİNE DE PARAMIZI ALACAĞIZ. O ZAMANA KADAR ARKANIZI DA KOLLAYIN.",
["pln_watchdogs_stage2_intro_a_01"] = "ÇIKIN, FBI TEKRAR YETİŞMEDEN ÇANTALARA GİDİN. BİLİYORUM, İNATÇI KÜÇÜK PİÇLER, DEĞİL Mİ?",
["pln_watchdogs_stage2_intro_a_02"] = "KOKAİNİ LİMANA GÖTÜRÜN... PROJEKTÖRLERLE TEKNEYE İŞARET VERİN, GELİP ALSIN.",
["pln_watchdogs_stage2_intro_a_03"] = "POLİSE HİÇBİR ŞEY BIRAKMAYIN. DEPODAKİ PROJEKTÖRLERLE HECTOR'IN ADAMLARINA İŞARET VERİP KOKAİNİ SÜRAT TEKNESİNE YÜKLEYİN. BURADA ÖYLE SÜSLÜ İŞ YOK.",
["pln_watchdogs_stage2_intro_b_01"] = "POLİSLER ALINACAĞINIZ YERİN HER YANINA DOLUŞMUŞ... KOKAİNİ DAHA GÜVENLİ BİR KONUMDAN ALABİLMENİZ İÇİN ALEX'E SİZİ DAHA UZAĞA BIRAKMASINI SÖYLEDİM. ALINCA TEKNEYE İŞARET VERİP KOKAİNİ ÇABUCAK YÜKLEYİN.",
["pln_watchdogs_stage2_intro_b_02"] = "HECTOR ENDİŞELİ... BU HELİKOPTERDE KOKAİNDEN FAZLA UZAĞIZ. YERE İNİNCE KOKAİNE GİDİN, KURYESİNE İŞARET VERİP MALI ALMAYA GELEN TEKNEYE YÜKLEYİN.",
["pln_wwh_01_01"] = "HEY, NE OLUYOR LAN? LOCKE, NE YAPIYORSUN?",
["pln_wwh_01_02"] = "LOCKE, NE ÇEVİRİYORSUN? EKİBİMLE OYNAMASAN İYİ OLUR.",
["pln_wwh_01_03"] = "LANET OLSUN LOCKE, EKİBİMLE OYNAMASAN İYİ OLUR. SÖZLEŞMEMİZ VARDI!",
["pln_wwh_02_01"] = "BU BİR TUZAK! LANET İT BİZİ SATTI. SWAT GELİYOR. ÇIKMAK İÇİN SAVAŞMANIZ GEREKECEK.",
["pln_wwh_02_02"] = "LANET OLSUN, İHANETE UĞRADIK. GELENLER VAR, SAVAŞMAYA HAZIR OLUN.",
["pln_wwh_02_03"] = "BAŞINIZ BELADA EKİP. LOCKE BİZİ SATTI. SAVAŞARAK ÇIKMANIZ GEREKECEK.",
["pln_wwh_03_01"] = "ŞİMDİLİK LOCKE'U UNUTUN, O PİSLİKLE SONRA İLGİLENİRİZ.",
["pln_wwh_03_02"] = "LOCKE KAÇTI AMA İNTİKAMIMIZI SONRA ALACAĞIZ.",
["pln_wwh_03_03"] = "LOCKE GİTTİ, O KALLEŞ. AMA SONRA BUNUN HESABINI SORACAĞIZ. SÖZÜMÜ UNUTMAYIN.",
["pln_wwh_04_01"] = "RIHTIMDAKİ GEMİ BUTCHER'A AİT. GÖRÜNÜŞE GÖRE ONU DA SATMIŞLAR. YARDIM EDİN, BELKİ BİZİ DE BURADAN GÖTÜRÜRLER.",
["pln_wwh_04_02"] = "RIHTIMDAKİ GEMİ BUTCHER'A AİT! LOCKE ONU DA SATTI. YARDIM EDİN, BELKİ SİZİ GÖTÜRÜRLER.",
