["pln_wwh_brf_01"] = "LOCKE ALASKA'DAKİ BİR SİLAH ALIŞVERİŞİNİ KORUMAK İÇİN YARDIM İSTEDİ. SORUN BEKLEMEDİĞİNİ AMA NE OLUR NE OLMAZ GÜVENİLİR GÜVENLİK İSTEDİĞİNİ SÖYLÜYOR. SOĞUĞA DAYANABİLİRSENİZ KOLAY PARA OLABİLİR.",
["pln_wwh_end_01"] = "PLAN RESMEN CEHENNEME GİTTİ. LOCKE'U DERT ETMEYİN, NEREYE GİTTİĞİNİ BULACAĞIM.",
["pln_wwh_end_02"] = "BUGÜN DAHA İYİ OLABİLİRDİ, MİLLET. AMA LOCKE'LA ENİNDE SONUNDA HESAPLAŞACAĞIZ. SADECE BİZDEN KAÇIYOR OLMAYACAK.",
