["plt_al1_01_01"] = "KUTUNUZ BENDE. BURAYA GELİN! ŞU BOKU YÜKLEYİN.",
["plt_al1_01_02"] = "POLİS HELİKOPTERİMİ HAVADA UZUN SÜRE BEKLETMEZ. KIÇINIZI KALDIRIN DA YÜRÜYÜN!",
