["plt_al1_03_02"] = "ÖNDEN ÇIKIŞ YOK. ÇABUK! KONTEYNERE GİRİN. GANİMETLE BİRLİKTE ÇIKIYORSUNUZ. DÜŞÜŞÜ DÜŞÜNMEYİN, TAMAM MI?",
["plt_al1_03_03"] = "BAŞKA ÇIKIŞ YOK. O KONTEYNERE GİRİN EKİP. BİR DE KABLO DAYANSIN DİYE UMUT EDİN.",
["plt_al1_03_04"] = "SİKTİR. BURANIN ÇEVRİLDİĞİNİ GÖRÜYORUM. SAVAŞARAK ÇIKAMAZSINIZ. KONTEYNERE GİRİN!",
["plt_al1_03_05"] = "KAHRETSİN, ŞEHİRDEKİ BÜTÜN POLİSLER DIŞARI DOLUŞMUŞ GİBİ. ÇIKIŞ YOK. BENİMLE GELİYORSUNUZ. KONTEYNERE GİRİN!",
["plt_al1_03_06"] = "BARİKATLAR, KESKİN NİŞANCILAR GÖRÜYORUM... DOSTUM. ÖN TARAFTAN ÇIKAMAZSINIZ. KONTEYNERE ATLAYIN PALYAÇOLAR. SİZİ UÇARAK ÇIKARACAĞIM.",
["plt_al1_03_07"] = "SIÇTIK, AĞIR TAKVİYE GELİYOR. ÇIKMAK İSTİYORSANIZ GANİMETLE BİRLİKTE ATLASANIZ İYİ OLUR.",
["plt_al1_03_08"] = "VAY BE. VAY BE! UFKA KADAR POLİS GÖRÜYORUM. SAVAŞARAK ÇIKMAYI UNUTUN. KONTEYNERE ATLAYIN, UÇARAK KAÇIYORUZ!",
["plt_as1_01_01"] = "TANRIM, YIKIMA BAK... 3 DAKİKAYA YANINIZDAYIM.",
["plt_as1_01_02"] = "ÜÇ DAKİKA UZAKTAYIM. BİR DE BURADAN GÖRSENİZ.",
["plt_as1_01_03"] = "VAY BE. ŞEHİR BOKA DÖNMÜŞ. YOLDAYIM, ÜÇ DAKİKA.",
["plt_as1_02_01"] = "ACİL SERVİSLER TAHLİYE İÇİN HELİKOPTERİME EL KOYMAYA ÇALIŞIYOR. 2 DAKİKAYA GELİRİM.",
["plt_as1_02_02"] = "HELİKOPTERİ TIBBİ TAHLİYEYE VERMEM İÇİN BASKI YAPIYORLAR. AMA BOK GİBİ PARA ÖDÜYORLAR. 2 DAKİKAYA ORADAYIM.",
["plt_as1_02_03"] = "YETKİLİLER HELİKOPTERİME EL KOYMAYA ÇALIŞIYOR. AMA YARALI SİVİLLER PEK İYİ PARA VERMİYOR. 2 DAKİKAYA YANINIZDAYIM.",
["plt_as1_03_01"] = "TOZ ÇOK YOĞUN. BİR BOK GÖRÜNMÜYOR. BİR DAKİKA UZAKTAYIM.",
["plt_as1_03_02"] = "YIKINTI İNANILMAZ. SİZE BİR DAKİKA UZAKTAYIM.",
["plt_as1_03_03"] = "BURAYI YENİDEN YAPMAK YILLAR SÜRER. SADECE BİR DAKİKA, HAZIR OLUN.",
["plt_as1_04_01"] = "TAMAM. İŞARET FİŞEĞİNİ GÖRÜYORUM. ALÇALMAYA BAŞLIYORUM.",
["plt_as1_04_02"] = "İŞARET FİŞEĞİNİ GÖRÜYORUM! GELİYORUM.",
["plt_as1_04_03"] = "TAMAM, İŞARET FİŞEĞİ ORADA. ALÇALMAYA BAŞLIYORUM.",
["plt_as1_intro_01_01"] = "SİZİ BURADA İNDİRİYORUM. ÇIKMAYA HAZIR OLUN!",
["plt_as1_intro_01_02"] = "BIRAKMA BÖLGESİ BURASI. HAZIR BEKLEYİN!",
["plt_as1_intro_01_03"] = "HAZIR MISINIZ? BURADA İNECEKSİNİZ.",
["plt_chw_01_01"] = "BEYLER, KISA SÜRELİĞİNE GELEBİLECEĞİM BİR AÇIKLIK GÖRÜYORUM. GÜVENE ALACAK GANİMETİNİZ VARSA TAM ZAMANI. TRENİN ARKASINDA OLACAĞIM.",
["plt_chw_01_02"] = "HEY MİLLET, KISA BİR SÜRELİĞİNE GELİYORUM. GÜVENE ALMAK İSTEDİĞİNİZ GANİMETLERİ BANA GETİRİN.",
["plt_chw_01_03"] = "ARKA TARAFA GELİYORUM MASKELİ DOSTLARIM. KISA SÜRE KALACAĞIM. GÜVENE ALMAK İSTEDİĞİNİZ HER ŞEYİ GETİRİN, ÇABUK OLUN.",
["plt_chw_02_01"] = "BURADAYIM. FAZLA KALAMAM, GANİMETİ HEMEN GETİRİN.",
["plt_chw_02_02"] = "HEY, ŞİMDİ ARKA TARAFTAYIM. GÜVENE ALMAK İSTEDİĞİNİZ GANİMETİ ÇABUCAK GETİRİN.",
["plt_chw_02_03"] = "HEY, ŞİMDİ ARKA TARAFTAYIM. GÜVENE ALMAK İSTEDİĞİNİZ GANİMETİ ÇABUCAK GETİRİN.",
["plt_chw_intro_01"] = "TAMAM KOVBOYLAR, SİZİ BURADA BIRAKIYORUM. MALLARI ALMAM İÇİN ÇAĞIRANA KADAR ETRAFTA DÖNECEĞİM.",
["plt_chw_intro_02"] = "KOVBOY FİLMİNDEN ÇIKMIŞ GİBİ. BILE BUNU SEVDİ BEYLER! NEYSE, SİZİ BURADA İNDİRİYORUM. GANİMETİ ALMAYA DÖNMEM İÇİN İŞARET VERENE KADAR HAZIR BEKLEYECEĞİM.",
["plt_chw_intro_03"] = "YİHUUU! GELDİK! ALMAYA GELDİĞİNİZ ŞEYİ BULANA KADAR TUR ATACAĞIM. İŞARET VERİN YETER, GANİMETİ ALMAYA DÖNERİM. İYİ ŞANSLAR!",
["plt_flt_01_01"] = "TAMAM, BÖLGEDEYİM AMA POLİS BİNANIN ÇEVRESİNDEKİ BÜTÜN ÇATILARA KESKİN NİŞANCI YERLEŞTİRMİŞ. C4'Ü BIRAKABİLMEM İÇİN ÖNCE ONLARI İNDİRMELİSİNİZ.",
["plt_flt_01_02"] = "YAKINDAYIM MİLLET AMA POLİSLER ÇEVREDEKİ BİNALARIN ÇATILARINA BİR SÜRÜ KESKİN NİŞANCI GETİRMİŞ. YÜKÜ BIRAKABİLMEM İÇİN ONLARI HALLETMENİZ GEREKECEK.",
["plt_flt_01_03"] = "TAMAM, YAKLAŞTIM AMA BIRAKMA BÖLGESİNE KESKİN NİŞANCILAR YAYILMIŞ. C4'Ü BIRAKMADAN ÖNCE ONLARI HALLETMELİSİNİZ.",
["plt_flt_02_01"] = "HEY! DESTEĞİM NEREDE? YUKARIDA AÇIK HEDEFİM!",
["plt_flt_02_02"] = "MİLLET, BENİ SAVUNUN! O KESKİN NİŞANCILAR YAKLAŞMAMI İMKÂNSIZ KILIYOR. ONLARI İNDİRMELİSİNİZ!",
["plt_flt_02_03"] = "HEY! BENİ BURADA DELİK DEŞİK EDİYORLAR! KESKİN NİŞANCILAR NEFES ALDIĞI SÜRECE YÜKÜ BIRAKACAK KADAR YAKLAŞAMAM!",
["plt_flt_03_01"] = "İYİ ATIŞLAR DOSTLARIM. ANLAŞTIĞIMIZ GİBİ C4'Ü BIRAKIYORUM.",
["plt_flt_03_02"] = "İŞTE ŞİMDİ OLDU HANIMLAR BEYLER. YÜKÜ BIRAKIYORUM.",
["plt_flt_03_03"] = "İYİ İŞ ÇIKARDINIZ, MASKELİ DOSTLARIM. BİRAZ C4'E HAZIR MISINIZ?",
["plt_flt_04_01"] = "HAY AKSİ, BIRAKMA NOKTASINI ISKALADIM... KUSURA BAKMAYIN MİLLET... C4'Ü ARKA SOKAKTA BULACAKSINIZ.",
["plt_flt_04_02"] = "AH LANET... ÇATIYI ISKALADIM... MİLLET, C4 ARKA SOKAĞA DÜŞTÜ...",
["plt_flt_04_03"] = "LANET OLSUN! C4 ARKA SOKAĞA DÜŞTÜ...",
["plt_flt_05_01"] = "BALKON. C4 BALKONDA. ÇATIYI ISKALADIM. KUSURA BAKMAYIN.",
["plt_flt_05_02"] = "EH, ISKALADIM... MİLLET, C4 BALKONA DÜŞTÜ. KUSURA BAKMAYIN.",
["plt_flt_05_03"] = "KUSURA BAKMAYIN BEYLER. C4'Ü YANLIŞLIKLA BALKONA BIRAKTIM... ÖZÜR DİLERİM.",
["plt_flt_06_01"] = "BEYLER, C4 ÇATIDA.",
["plt_flt_06_02"] = "YİHUU! C4 ANLAŞTIĞIMIZ GİBİ ÇATIYA BIRAKILDI.",
["plt_flt_06_03"] = "TAMAMDIR, BİTTİ! C4 ÇATIYA BIRAKILDI.",
["plt_flt_07_01"] = "TAMAM, DÖNDÜM AMA HER YERDE BU KADAR POLİS VARKEN BİR BOK YAPAMAM. ÇATIYI TEMİZLEMENİZ GEREKECEK.",
["plt_flt_07_02"] = "TANRIM, OLAY YERİNDE ÇOK FAZLA POLİS VAR! YETERİNCE YAKLAŞAMIYORUM, BU YÜZDEN SİZİN HALLETMENİZ GEREK.",
["plt_flt_07_03"] = "BURADAYIM MİLLET AMA ÇATI POLİS DOLUYKEN YAKLAŞAMAM.",
["plt_flt_08_01"] = "BEYLER, ÇATIYI TEMİZLEMEDEN YAKLAŞAMAM!",
