["pyr_al1_01_01"] = "BU SON GÖSTERİMİZ, DUYDUNUZ MU? GÜMBÜR GÜMBÜR BİTSİN.",
["pyr_al1_01_02"] = "BU GECE HEPİNİZDEN KUSURSUZ İŞ İSTİYORUM, GÖT HERİFLER! ÖZELLİKLE DE YUKARIDA, KABİNDEKİ SENDEN.",
["pyr_al1_01_04"] = "DÜNYANIN EN BÜYÜK TURNESİNİN SON GÖSTERİSİ BU. ŞİMDİ SIÇMAYIN.",
["pyr_al1_01_05"] = "YUKARIDA KABİNDEKİ EKİBİN İYİ OLDUĞUNU DUYDUM. BENİ YÜZÜSTÜ BIRAKMAYIN, ANLAŞILDI MI?",
["pyr_al1_02_01"] = "HEY! GÖT HERİF! KIÇINI KAŞIMAYI BIRAK DA DAHİLİ TELEFONA GEL!",
["pyr_al1_02_02"] = "HEY! HAYRAN KIZINI BIRAK DA DAHİLİ TELEFONA GEL!",
["pyr_al1_02_03"] = "HEY! HEY BOK KAFA! ÜÇ KELİME. CEVAP. VER. ŞU. LANET. TELEFONA.",
["pyr_al1_02_08"] = "DİYAFONA CEVAP VER. BENİ ORAYA GETİRTME EVLAT.",
["pyr_al1_03_01"] = "(AĞZIYLA RİTİM TUTAR) CEVAP. (AĞZIYLA RİTİM TUTAR) VERİN. (AĞZIYLA RİTİM TUTAR) DİYAFONA.",
["pyr_al1_03_04"] = "BENİ SİZİ DEVLETİN KATIRI GİBİ KIRBAÇLAMAK ZORUNDA BIRAKMAYIN. DİYAFONA CEVAP VERİN.",
["pyr_al1_03_05"] = "EVET! EVET! TAMAM, HEY, KABİNDEKİLER, DİYAFONA CEVAP VERİN.",
["pyr_al1_04_01"] = "TAMAM, KABİN EKİBİ. İŞARET VERDİĞİMDE BASIYORSUNUZ, ANLAŞILDI MI?",
["pyr_al1_04_02"] = "DURUM ŞU. BEN İŞARET VERECEĞİM, SİZİN YAPACAĞINIZ TEK ŞEY DÜĞMEYE BASMAK. ANLAŞILDI MI?",
["pyr_al1_04_03"] = "DİNLEYİN, BU MİLLETİ KENDİNDEN GEÇİRECEĞİZ AMINA KOYAYIM. BEN SÖYLEYİNCE DÜĞMEYE BASIN. TAMAMDIR!",
["pyr_al1_04_04"] = "BUNUNLA ÇILGINCA AŞIRIYA KAÇACAĞIZ. ŞİMDİ, DEDİĞİMDE DÜĞMEYE BASIN. ANLADINIZ MI?",
["pyr_al1_04_05"] = "KUMANDA EKİBİ. DİKKATİNİZ YERİNDE OLSA İYİ OLUR. BEN İŞARETİ VERİRİM, SİZ DÜĞMEYE BASARSINIZ. ANLAŞILDI MI DOSTUM?",
["pyr_al1_05_01"] = "EVET! EVET! AHHH İŞTE BU BE! KALABALIK ÇILDIRIYOR!",
["pyr_al1_05_02"] = "MÜTHİŞTİ! VUHUUUU! MÜTHİŞ.",
["pyr_al1_05_03"] = "İNANILMAZ! MÜKEMMEL! AŞAĞIDA HERKES AKLINI KAÇIRIYOR!",
["pyr_al1_05_04"] = "OOOO HASSSİKTİİİİİR. MUAZZAMDI AMINA KOYAYIM!",
["pyr_al1_05_05"] = "HEY, KABİN EKİBİ İÇİN BİR COŞKULU EVET ALABİLİR MİYİM?",
["pyr_al1_05_06"] = "YUKARIDA HARİKA İŞ ÇIKARDINIZ. TURNE EKİBİNE KATILMAK İSTER MİSİNİZ?",
["pyr_al1_05_08"] = "HASSİKTİR LAN! ACAYİP SALLADI ORTALIĞI! VUHUUUUUUUUU!",
["pyr_al1_06_01"] = "DOSTUM, DAHA İYİSİNİ YAPMALISIN. YANLIŞ MERMİYİ ATIYORSAN ZAMANLAMANIN HİÇBİR BOK ÖNEMİ YOK, ANLADIN MI!",
["pyr_al1_06_03"] = "YUKARIDA NE BOK OLUYOR, BOK KAFALI?!",
["pyr_al1_06_04"] = "YUKARIDA HALKA OLUP BİRBİRİNİZE Mİ ÇEKİYORSUNUZ? ÇÜNKÜ BURADA BENİM SİKİMLE OYNUYORSUNUZ! TOPARLANIN!",
["pyr_al1_06_05"] = "SİKTİĞİMİN BOK KUŞLARI. YUKARIDA ŞU EŞYANIZI SABİTLEYİN.",
["pyr_al1_07_01"] = "DOSTUM, ÇOK GÜZELDİ. ÇOK GÜZEL. SEVGİLİ ANNEM GİBİ. (BURNUNU ÇEKER)",
["pyr_al1_07_02"] = "KARDEŞİM, MUHTEŞEMDİ BE! TAM ON İKİDEN VURUYORSUNUZ AMINA KOYAYIM, VUHUUUU!",
["pyr_al1_07_03"] = "VUHUUUUU! İŞTE BU, DOSTUM. İŞTE BU! VUHUUUUUUU!",
["pyr_al1_07_04"] = "AHH SİKTİR DOSTUM. BU ÇOCUKLAR ÇILDIRIYOR LAN. VUHUUUU!",
["pyr_al1_07_05"] = "EVET, İŞTE BU. AH SİKTİR! MUHTEŞEM!",
["pyr_al1_07_06"] = "EVET! SAĞLAM İŞTİ. ÇOK SAĞLAM!",
["pyr_al1_07_07"] = "SİZE TEK SÖZÜM VAR: VUHUUUUUUUUUUUUUUUUU!",
["pyr_al1_07_08"] = "HARİKA İŞ! DOSTUM, BU ÇOCUKLAR BUNU HAYATLARININ EN GÜZEL GECESİ DİYE HATIRLAYACAK.",
["pyr_al1_08_04"] = "HAY AMINA KOYAYIM. GÖT HERİFLER! BATIRDINIZ. TOPARLANIN, YOKSA SİZİ BEN ÇEKER ÇIKARIRIM. KILINIZDAN TÜYÜNÜZDEN TUTUP.",
["pyr_al1_08_07"] = "DOĞRU YAP, YOKSA AUSTİN'DEN AMARİLLO'YA KADAR SENİ SİKTİRİRİM.",
["pyr_al1_09_01"] = "BAŞLAT!",
["pyr_al1_09_02"] = "TAMAM, VERİN!",
["pyr_al1_09_03"] = "VE... ŞİMDİ!",
["pyr_al1_09_04"] = "ATEŞLEYİN!",
["pyr_al1_09_05"] = "BAŞLATIN!",
["pyr_al1_09_07"] = "BAŞLAT!",
["pyr_al1_09_09"] = "ŞİMDİ!",
["pyr_al1_09_10"] = "YAPIN!",
["pyr_al1_09_13"] = "PATLAMA VAR, DOSTUM!",
["pyr_al1_10_01"] = "SIÇIP BATIRMAYIN. BAŞLAYIN!",
["pyr_al1_10_02"] = "DOĞRU YAP. BAS!",
["pyr_al1_10_03"] = "BU KEZ ODAKLANIN. BASIN!",
["pyr_al1_10_04"] = "GÖZÜN İŞTE OLSUN. ATEŞLE!",
["pyr_al1_10_05"] = "ELLER SİKLERDEN ÇEKİLSİN, DÜĞMEYE GİTSİN. HEMEN!",
["pyr_al1_10_06"] = "KENDİNİZİ AFFETTİRME ŞANSI. YAPIN!",
["pyr_al1_10_07"] = "BU SEFER SIÇMAK YOK. BIRAK!",
["pyr_al1_10_08"] = "YİNE BOK ETMEYİN. HADİ!",
["pyr_al1_10_09"] = "ŞİMDİ BATIRMAYIN. BASMA VAKTİ!",
["pyr_al1_11_01"] = "SIÇTIN EVLAT.",
["pyr_al1_11_02"] = "KUMANDA EKİBİ Mİ? DAHA ÇOK SIÇIP BATIRMA EKİBİ.",
["pyr_al1_11_03"] = "FENA SIÇIP BATIRDIN, GÖT HERİF.",
["pyr_al1_12_01"] = "LANET BİR DÜĞMEYE BASMAYI NASIL BECEREMEZSİNİZ AMINA KOYAYIM?!",
["pyr_al1_12_02"] = "FELAKET YARATIYORSUNUZ! ŞU BOKUNUZU TOPARLAYIN OROSPU ÇOCUKLARI!",
["pyr_al1_12_05"] = "OĞLUM, SİZ YÜRÜYEN FELAKETSİNİZ. NE BOKTAN BİR REZALET BU.",
["pyr_al1_13_01"] = "TAMAM. (TELEFONDAN BAŞKASINA SESLENİR) DWAYNE, YUKARIYA BİRKAÇ ADAM GÖNDER, BİRAZ KIÇ TEKMELESİNLER.",
["pyr_al1_13_06"] = "YETER ARTIK. (TELEFONDAN BAŞKASINA SESLENİR) YUKARIYA GÜVENLİĞİ GÖNDERİN. PARMAKLARI SÖKÜLSÜN İSTİYORUM.",
["pyr_al1_14_04"] = "(ALAYCI) İYİ İŞ, SİK SURAT. GERÇEKTEN HARİKA İŞ.",
["pyr_al1_14_07"] = "BİR SIÇIŞ DAHA. EN AZINDAN İSTİKRARLISINIZ.",
["pyr_al1_14_08"] = "YİNE BİR BOKTAN SIÇIŞTAN AZINI BEKLEMİYORDUM. SİKTİİİİİR.",
["pyr_al1_15_02"] = "MUHTEŞEM BE! DÜNYA ÇAPINDASINIZ. (BURNUNU ÇEKER) DÜNYA ÇAPINDA, DUYDUNUZ MU!",
["pyr_al1_15_03"] = "HAYATIMIN EN MÜTHİŞ GECESİNE HOŞ GELDİNİZ LAN. HERKES HARİKA İŞ ÇIKARDI!",
["pyr_al1_15_07"] = "HARİKA BİR GÖSTERİ İŞTE BÖYLE YAPILIR. MÜKEMMEL İŞ!",
["pyr_al1_15_08"] = "MÜZİK TARİHİNİN EN İYİ EKİBİ! BİR COŞKULU EVET ALABİLİR MİYİM?",
["pyr_al1_16_01"] = "EH, GÖRDÜĞÜM EN BOKTAN PİROTEKNİK GÖSTERİYDİ NEREDEYSE.",
["pyr_al1_16_03"] = "PİROTEKNİK OKULUNA GERİ DÖNMENİZ GEREK. NE BOKTAN İŞ!",
["pyr_al1_16_06"] = "HAY SİKEYİM BÖYLE İŞİ. O HAVAİ FİŞEK GÖSTERİSİ BOK GİBİYDİ.",
["pyr_al1_17_01"] = "AZ ÖNCE BİR ŞEY Mİ GEVŞEDİ? KONTROL EDİP DÜZELTİN!",
["pyr_al1_17_02"] = "VAY, BİR SÜRÜ IŞIK BİRDEN GİTTİ. YUKARIDAKİ DONANIMI DÜZELTİN.",
["pyr_al1_17_03"] = "SIÇTIK. GÖRÜYOR MUSUNUZ? YUKARIDA BİR ŞEY PATLADI. PİROTEKNİK EKİBİ, DÜZELTİN!",
["pyr_al1_17_04"] = "NE OLUYOR LAN! BİR GÖRÜNTÜ HATTI GİTTİ. DÜZELTİN ŞUNU!",
["pyr_al1_17_05"] = "KUMANDA KABİNİNDE DONANIM ARIZASI VAR GİBİ. PİROTEKNİK EKİBİ, HALLEDİN!",
["pyr_al1_17_06"] = "ORADA BİR ŞEYLER SIÇMIŞ. EFEKT EKİBİ, İLGİLENMENİZ GEREKİYOR.",
["pyr_al1_17_07"] = "ŞEY, SADECE... EVET, BİR ŞEY SIÇTI. DÜZELTİN, MİLLET.",
["pyr_al1_17_08"] = "UFAK BİR DONANIM SORUNU VAR. DÜZELTEN KİŞİ ALESSO'YLA TANIŞACAK.",
["pyr_al1_18_01"] = "SIÇTIK! ORADA BİR ŞEY YANIYOR. YANGINI SÖNDÜRÜN, ÇABUK!",
["pyr_al1_18_02"] = "YANGIN UYARISI YANDI. SİKTİİİİR. SÖNDÜRÜN, HEMEN!",
["pyr_al1_18_03"] = "ALEVLERİ VE DUMANI BURADAN GÖRÜYORUM. BİR YANGIN SÖNDÜRÜCÜ ALIP SÖNDÜRÜN!",
["pyr_al1_18_04"] = "BİR ŞEY YANIYOR MİLLET, KOKUSU DA YEDİĞİM HİÇBİR TEKSAS MANGALINA BENZEMİYOR. SÖNDÜRÜN ŞU YANGINI!",
["pyr_al1_18_05"] = "BURASI YANAMAZ, PİROTEKNİK KUMANDA KABİNİ BURASI. SÖNDÜRÜN!",
["pyr_al1_18_06"] = "ATEŞ GÖSTERİSİNİ KONSERE SAKLAYIN MİLLET. YANGINI HEMENCECİK HALLEDİN!",
["pyr_al1_18_07"] = "O EKİPMAN PAHALI. ON YILLIK MAAŞIN KADAR PAHALI. YANGINI HALLET!",
["pyr_al1_18_08"] = "LANET OLSUN, YUKARIDA YANGIN VAR. KABİNDEKİ SEN! HALLET!",
["pyr_al1_18_09"] = "DOMUZ PİRZOLALI SANDVİÇ Mİ YAPIYORSUNUZ? YANGINI SÖNDÜRÜN. (ARKADA SESSİZCE) BEN BİR BİLGİSAYARIM.",
["pyr_al1_19_01"] = "(TELEFONA YAKLAŞIRKEN)...SONRA SİD HEPSİNİ KEİTH'İN SANDVİÇİNE SÜRÜP MAYONEZ OLDUĞUNU SÖYLEDİ! (GÜLER)",
["pyr_al1_19_02"] = "DOSTUM, ŞU MÜZİK ACAYİP GÜZEL. KİLİSEDE ÇALINMALI.",
["pyr_al1_19_03"] = "KEŞKE ÇOCUKKEN BU MÜZİK OLSAYDI. ACAYİP SEVİYORLAR.",
["pyr_al1_19_04"] = "JİMİ'YLE TIJUANA'DAN BİR BALYA OT VE BİR KEÇİ KAÇIRDIĞIMIZ HAFTA SONUNU SİZE HİÇ ANLATTIM MI?",
["pyr_al1_19_05"] = "YAŞLI BİR ADAMDAN ÖĞÜT ALIN MİLLET. UYUŞTURUCU KULLANMAYIN. AMA İÇKİ VE SİGARA ACAYİP GÜZEL.",
["pyr_al1_19_06"] = "BURADA HARRY'S WİNE BOX VARKEN ÇALMIŞTIK. '73'TÜ.",
["pyr_al1_19_07"] = "BU DÖVMEYİ GÖRÜYOR MUSUN? BİZZAT KRAL YAPTI. MÜTHİŞ BE DOSTUM.",
["pyr_al1_19_08"] = "THE COCKROACHES DAĞILIRKEN ORADAYDIM. GELMİŞ GEÇMİŞ EN İYİ GRUPTU AMINA KOYAYIM.",
["pyr_al1_20_01"] = "HEY GÖT HERİF! DAHİLİ TELEFON!",
["pyr_al1_20_02"] = "HEY! DAHİLİ TELEFONA CEVAP VERİN!",
["pyr_al1_20_03"] = "HEY HEY HEY, BOK KAFA! ŞU LANET İNTERKOMA CEVAP VER!",
["pyr_al1_20_04"] = "DİYAFONA CEVAP VER EVLAT!",
["pyr_al1_20_05"] = "İNTERKOMA CEVAP VER!",
["ranc_intro_01_01"] = "         \nPEKİ, ŞU ESTEBAN DENEN ADAM. HAKKINDA NE BİLİYORSUN?",
["ranc_intro_01_02"] = "MANGAL YAPMAKTAN DAHA ÇOK SEVDİĞİ TEK ŞEYİN İZİNSİZ GİRENLERİ VURMAK OLDUĞUNU BİLİYORUM. SİZİ GÖRMESİN. 'SORU SORAN' TİPLERDEN DEĞİL.",
["ranc_intro_01_03"] = "BİZİ GÖRÜRSE ONUN İÇİN DAHA ÇOK ENDİŞELENİRDİM. BİZ \"KAÇIP GİDEN\" TİPLERDEN DEĞİLİZ, ANLARSIN YA.",
["ranc_intro_02_01"] = "UNUTMAYIN: BURASI SIRADAN BİR SIĞIR ÇİFTLİĞİ GİBİ GÖRÜNEBİLİR AMA HİÇ İNEK BULAMAYACAKSINIZ. BİR SÜRÜ KAMERA, BİR SÜRÜ AFİLİ KAPI VE BİR SÜRÜ SİLAH TAŞIYAN BİR SÜRÜ ADAM BULACAKSINIZ.",
["ranc_intro_02_02"] = "BİZİ MERAK ETMEYİN. AKLINIZA GELMEYECEK YERLERDE İŞLER BAŞARDIK. BU... NASIL DENİYORDU? ŞEY... HA! ‘BU BİZİM İLK RODEOMUZ DEĞİL!’ TABİRİ CAİZSE.",
["ranc_intro_02_03"] = "HA HA! VAY SANA BAK, BAY YEREL LEZZET! SENDEN BİR TEXAS'LI ÇIKARACAĞIZ DAHA LOCKE.",
["ranc_intro_03_01"] = "BU ESTEBAN DENEN APTALIN NEDEN SANA TAKTIĞINA DAİR BİR FİKRİN VAR MI?",
["ranc_intro_03_02"] = "NE BİLEYİM BEN. BENCE BİRİ ESTEBAN'I BANA BULAŞSIN DİYE TUTTU AMA BU DA SORUYA BAŞKA BİR LANET SORUYLA CEVAP VERMEK OLUYOR.",
["ranc_intro_03_03"] = "BU KARMAŞANIN ARKASINDA KİM VARSA BİRAZDAN AĞIR BİR DARBE YİYECEK. BİRİNİ SOYMAK İÇİN ADINI BİLMEN GEREKMEZ. BİZ HEP YAPIYORUZ.",
["rb14_drk_cbf_01_01"] = "EMP BOMBASINI ELE GEÇİRMEK İÇİN LANET MURKYWATER'LA UĞRAŞMAMIZ GEREKECEK. TRENLE BİR SÜRÜ MAL TAŞIYORLAR VE GİZLİ BİR TREN SAHASINDA PLANLI MOLA VERECEKLER. BEN TABİİ SİLAHLARI KONUŞTURMAYI TERCİH EDERİM AMA BU FAZLA RİSKLİ, DEĞİL Mİ? O YÜZDEN BUNU GİZLİCE YAPMALIYIZ ÇOCUKLAR.$NL;$NL;» TRENLERİ BUL$NL;» EMP BOMBASI PARÇALARINI BUL$NL;» PARÇALARI ORADAN ÇIKAR VE KAÇ",
["rb14_drk_outro_01_01"] = "İPEK GİBİ PÜRÜZSÜZDÜ KIZLAR VE OĞLANLAR! EMP BOMBASI GÜVENDE; GİZLİ TESİSE GİRMEK İÇİN GEREKEN ARTIK ELİMİZDE. RUSYA ANA, İŞTE GELİYORUZ! ",
["rb14_drk_outro_01_02"] = "HARİKA OLDU BE ÇOCUKLAR! EMP BOMBASI GÜVENDE OLDUĞUNA GÖRE YERALTI TESİSİNE GİREBİLİRİZ. LANET RUSYA'YA GİTME ZAMANI!",
["rb14_drk_outro_02_01"] = "SİKTİR, ALARM ÇALDI AMA BAŞARDIK. İYİYİZ. O LANET MURKY'LER NEYE UĞRADIKLARINI ANLAMAYACAK. AKAN İSE KUDURACAK. BUNU DÜŞÜNMEK HOŞUMA GİDİYOR. ",
["rb14_mad_cbf_01_01"] = "BU PİS RUS ÖRGÜTÜ, RUSYA'DAKİ GİZLİ BİR LABORATUVARDA ÇOK RAHATSIZ EDİCİ DENEYLER YÜRÜTÜYOR. ORADA NE BOKLAR YAPTIKLARINA İNANAMAZSINIZ. AKAN'IN VERİLERE ULAŞMASINI KESİNLİKLE ENGELLEMELİYİZ, TAMAM MI? YA BAŞARIRIZ YA ÖLÜRÜZ KIZLAR VE OĞLANLAR.$NL;$NL;» YERLEŞKEYE GİR$NL;» LABORATUVARA ERİŞ$NL;» VERİLERİ AL$NL;» KAÇ",
["rb14_mad_outro_01_01"] = "BAŞARDIK BE ÇOCUKLAR! O BEYAZ SAÇLI UCUBENİN İSTEDİĞİ VERİLERİ ALMASINI ENGELLEDİK. NE DERSİNİZ? NE DERSİNİZ? YAKALIM MI? YAKIP CEHENNEMİN DİBİNE GÖNDERELİM!",
["rb1_bph_intro_01d"] = "LOCKE, BU AYKİ LANET ÇAMAŞIR FATURASINI SEN ÖDÜYORSUN.",
["rb1_bph_intro_01f"] = "DENTİST YUKARIDAYSA DİŞLERİNİ TEKMEYLE DÖKECEĞİM.",
["rb1_bph_intro_01h"] = "DOĞRU DEDİN HOX.",
["rb1_bph_intro_02d"] = "BİR MURKYWATER İNİNE DE TAM BÖYLE BİR YER YAKIŞIR LAN.",
["rb1_bph_intro_02f"] = "BİRAZ HESAP ÖDEME VAKTİ. ",
["rb1_bph_intro_03a"] = "TANIDIK GELDİ Mİ HOX?",
["rb1_bph_intro_03c"] = "KENTO'YA İLK ULAŞAN İÇKİLERİ ÖDER.",
["rb1_bph_intro_03e"] = "PEKİ YA KOCAMAN ALEVLİ PATLAMALAR?",
["rb1_bph_intro_03g"] = "YANLIŞ FİLM HOX.",
["rb1_bph_intro_04b"] = "EVET, ŞEKER FALAN DEĞİL.",
["rb1_bph_intro_04d"] = "DAYAN BAIN, SENİ ALMAYA GELDİK.",
["rb1_nmh_cbf_01"] = "SELAM. LOCKE'LA KONUŞTUM. BAIN'İN BİRKAÇ GÜNÜ KALDI. O KATARU OROSPU ÇOCUKLARI ADAMIN İÇİNE VİRÜS POMPALAMIŞ. BİRKAÇ YIL ÖNCE MERCY HOSPİTAL'DAN ÇALDIĞIMIZ SİKİK VİRÜSÜN AYNISI. KİMİN İÇİN ALDIYSAK MURKYWATER'A SATMIŞ, ŞİMDİ DE ONU ÖLDÜRÜYOR. BAŞINDAN BERİ O İŞTE HAYIR OLMADIĞINI BİLİYORDUM. BAIN DE BİLİYORDU AMA CAGLİOSTRO EL YAZMASINI İSTİYORDU. O SİKTİĞİMİN KİTABINI. SİKTİR GİT DEMELİYDİM AMA BİR ŞEY İÇİN ONA GERÇEKTEN İHTİYACIMIZ OLDUĞUNU SÖYLEDİ. AÇIKÇASI, O KİTAP OLMASA ŞU AN BULUNDUĞUMUZ YERE GELEMEZDİK. İNSAN EKTİĞİNİ BİÇİYOR GALİBA. O SİKTİĞİMİN KİTABI. ",
["rb22_bph_intro_01a"] = "BURADAN GİRMEK KİMİN FİKRİYDİ?",
["rb22_bph_intro_01e"] = "DENTİST GİBİ BİRİNİN İNSANLARA İŞKENCE ETMEK İÇİN DAHA BAKIMLI BİR HAPİSHANEYE PARASI YETER SANIRDIN...",
["rb22_bph_intro_02a"] = "BAIN, ESKİ DOSTUM, GELİYORUZ! AH, NE MUHTEŞEM ŞİİR.",
["rb22_bph_intro_02c"] = "GÜZEL, SICACIK BİR YUVA, DEĞİL Mİ?",
["rb22_bph_intro_02e"] = "KANALİZASYON. İLLA KANALİZASYON OLMAK ZORUNDA MIYDI?",
["rb22_bph_intro_03d"] = "YEŞİL PARLAYAN ŞEYLERE DİKKAT EDİN.",
["rb22_bph_intro_04aa"] = "İÇİME BİRAZ KÖTÜ BİR HİS DOĞDU. KÖTÜ HİSSETMELİ MİYİM?",
["rb22_bph_intro_04c"] = "SAL YAPMAMIZ GEREKİRSE DİYE YAĞMURLUK GETİRMEYİ UNUTMAYAN OLDU MU?",
["rb22_des_cbf_01"] = "HENRY'S ROCK. GİZLİ BİLİMSEL DENEYLER VE ŞİRKETLERİN OKÜLT DALAVERELERİ HAKKINDA DUYDUĞUNUZ BÜTÜN ÇATLAK KOMPLO TEORİLERİ TEK BİR TESİSTE TOPLANMIŞ. LOCKE, MURKYWATER'IN TEPESİNDEKİ ADAMLARIN ORADA EPEY KARANLIK İŞLER ÇEVİRDİĞİNİ SÖYLÜYOR. ELE GEÇİRDİĞİMİZ GÜVENLİK KAYITLARINDA, ELLERİNDE KOMİSER GARRETT'IN FBI EMANET DEPOSUNDAKİNE BENZEYEN İKİ YALDIZLI SANDIK DAHA GÖRÜNÜYOR. BUNLARDAN BİRİ, VEGAS'TA DENTİST İÇİN ELE GEÇİRDİĞİMİZ SANDIĞIN TA KENDİSİ BİLE OLABİLİR. BAIN'İN ARAYIŞIYLA BAĞLANTILARI HENÜZ BELLİ DEĞİL AMA MURKY'LER İÇİN YETERİNCE DEĞERLİ OLDUKLARI AÇIK. BUNLARI ELLERİNDEN ALSAK İYİ OLUR. HAZIR GİTMİŞKEN ONLARA HAK ETTİKLERİ DERSİ DE VERİRİZ BELKİ.",
["rb22_sah_cbf_01"] = "TAMAM EKİP, ELEPHANT'TAN BİR BİLDİRİ ALDIK. BİZE YARDIM ETMEK İSTEDİĞİNİ İDDİA EDİYOR. GÖRÜNÜŞE GÖRE 1900'LERİN BAŞINDA BİR KATARU ÜYESİ, ONUN 'AİLE YADİGÂRI' DEDİĞİ BİR ŞEYİ ÇALMIŞ. BU KİŞİ SONRA PARA VERİP ANTARKTİKA'YA GİDEN ÜNLÜ SHACKLETHORNE SEFERİNE KATILMIŞ. ELEPHANT'A GÖRE VARLIĞI, YOLCULUĞU BAŞTAN LANETLEMİŞ. ELEPHANT KETUM DAVRANSA DA BUNLARIN TANIDIK GELMESİ TESADÜF DEĞİL. GEMİ VE MÜRETTEBATI KAYBOLMUŞTU. YAKIN ZAMANDA ENKAZ, PLANLANAN ROTADAN UZAKTA BUZLARIN ARASINDA EZİLMİŞ HÂLDE BULUNDU. ENKAZDAN BİRKAÇ MİL ÖTEDE DE KORKUNÇ BİÇİMDE ÖLMÜŞ GÖRÜNEN MUMYALANMIŞ BİR CESET, BİR KIZAK VE ESER KOLEKSİYONU BULDULAR. ÇIKARILAN EŞYALAR BİR GRUP YOZLAŞMIŞ SOSYETEYE GİZLİCE AÇIK ARTIRMAYLA SATILACAK. ELEPHANT BU EŞYALARDAN BİRİNİN MUTFAKTAKİ CİHAZDA BİZE YARDIM EDECEĞİNİ SÖYLÜYOR. BU İŞ BANA TUHAF HİSSETTİRİYOR. FAZLA YAKINDAN TANIDIK GELİYOR.",
["rb22_sah_intro_01a"] = "DAHA ÇOK BİR HP LOVECRAFT ROMANINI SOYUYORUZ GİBİ...",
["rb22_sah_intro_01b"] = "DUVARLARDA FARELER VAR...",
["rb22_sah_intro_02a"] = "TAM ANA KAPININ ARKASINDA OLSA BAYAĞI SIKICI OLURDU, DEĞİL Mİ?",
["rb22_sah_intro_02b"] = "SADECE HAYAL GÜÇLERİ OLDUĞUNU KANITLAMAYA ÇALIŞIYORLAR.",
["rb22_sah_intro_03a"] = "BÖYLE BİR YERDE YAŞADIĞIMI DÜŞÜNEBİLİYORUM. YANİ DAHA AZ ÜRKÜTÜCÜ OLSA.",
["rb22_sah_intro_03b"] = "BELKİ SANA EVCİL HAYVAN DİYE BİRKAÇ TANE GETİRİRİZ LOCKE.",
["rb22_sah_intro_04a"] = "BU İŞLE İLGİLİ TUHAF BİR HİS VAR İÇİMDE. SANKİ... BİR ŞEKİLDE KİŞİSEL.",
["rb22_sah_intro_04b"] = "KONUKLAR BALIK KOKUYORSA BURADAN DEFOLUP GİTMEYİ ÖNERİRİM.",
["rb4_sh11_01_01"] = "BANA BU BOKU YAPTIRDIĞINA İNANAMIYORUM, BAIN...",
["rb4_sh11_01_02"] = "NE KADAR OLDU, İKİ YIL MI? BİR DE BANA BU BOKTAN İŞLERİ Mİ YAPTIRIYORSUN?",
["rb4_sh11_01_03"] = "SAÇMALIK BU BAIN. BU İŞİ YAPMAYI UNUTTUĞUMU MU SANIYORSUN?",
["rb4_sh11_02_01"] = "AA BAK, YAPTIM. ŞİMDİ ÖDÜL ALIYOR MUYUM?",
["rb4_sh11_02_02"] = "TAMAM, GEÇTİM. AMA GERÇEKTEN ZORDU. BUNU YAPTIĞIMIZA SEVİNİYORUM. GERÇEKTEN.",
["rb4_sh11_02_03"] = "TANRIM BAIN. LANET ÇİTİ AŞMAYI UNUTMUŞ OLAMAM YA? NEYSE, ARTIK GEÇTİM.",
["rb4_sh11_03_01"] = "TAMAM, İLERİDE BİR MUHAFIZ GÖRÜYORUM. AÇIKÇASI YANINDAN GİZLİCE GEÇECEK PEK ALAN YOK.",
["rb4_sh11_03_02"] = "İLERİDE MUHAFIZ VAR. GİZLİCE GEÇEBİLECEĞİMİ SANMIYORUM.",
["rb4_sh11_03_03"] = "İLERİDE BİR MUHAFIZ GÖRÜYORUM. KIPIRDAMIYOR, YANINDAN GİZLİCE GEÇEBİLECEĞİMİ SANMIYORUM.",
["rb4_sh11_04_01"] = "CESEDİ TORBALADIM. ŞİMDİ SAKLAYACAK BİR YER LAZIM.",
["rb4_sh11_04_02"] = "ONU SAKLAYABİLECEĞİM BİR YER BULMAM GEREKECEK.",
["rb4_sh11_04_03"] = "CESET TORBALANDI. SORU ŞU, NEREYE SAKLAYACAĞIM?",
["rb4_sh11_05_01"] = "BUGÜN DE PEK ATEŞLİYİZ, HA?",
["rb4_sh11_05_02"] = "TANRIM, KAFAYI YEME BAIN.",
["rb4_sh11_05_03"] = "MUHAFIZI İNDİRİRKEN ONU FARK ETMEDİĞİM İÇİN AFFEDERSİN.",
["rb4_sh11_06_01"] = "İYİ GECELER.",
["rb4_sh11_06_02"] = "UYKU VAKTİ.",
["rb4_sh11_06_03"] = "MIŞIL MIŞIL UYU.",
["rb4_sh11_07_01"] = "SİKTİR!",
["rb4_sh11_07_02"] = "SİKTİR!",
["rb4_sh11_07_03"] = "AH SİKTİR!",
["rb4_sh11_08_01"] = "YÜCE TANRIM... BU BİRAZ FAZLA YAKINDI...",
["rb4_sh11_08_02"] = "HASSİKTİR, KIL PAYIYDI.",
["rb4_sh11_08_03"] = "DOSTUM, BU BENİM İÇİN BİRAZ FAZLA RİSKLİYDİ.",
["rb4_sh11_09_01"] = "NASIL AMA?",
["rb4_sh11_09_02"] = "NE OLDUĞUNU BİLE BİLMİYORUM AMA İŞ GÖRÜR. DEĞİL Mİ?",
["rb4_sh11_09_03"] = "AĞIR GÖRÜNÜYOR AMA BAYAĞI GÖZE ÇARPIYOR.",
["rb4_sh11_10_01"] = "TAMAM, ALDIM. BU BOK BİTTİ Mİ?",
["rb4_sh11_10_02"] = "TAMAM, ALDIM. ŞİMDİ MUTLU MUSUN?",
["rb4_sh11_10_03"] = "ALDIM. LÜTFEN ARTIK BİTTİĞİNİ SÖYLE.",
["rb4_sh11_11_01"] = "KABUL ETMEK ZOR AMA BU BANA İYİ GELMİŞ OLABİLİR. SUÇ HAYATINDAN İKİ YIL UZAK KALMAK UZUN SÜRE.",
["rb4_sh11_11_02"] = "LANET OLSUN SANA BAIN AMA GALİBA HAKLIYDIN. İŞE GERİ DÖNMEK İÇİN \"KOLAY\" BİR ŞEYE İHTİYACIM VARDI.",
["rb4_sh11_11_03"] = "OLGUNLUK GÖSTERİP HAKLI OLDUĞUNU KABUL EDECEĞİM BAIN. DAHA ZOR SOYGUNLARA GİRİŞMEDEN BUNU YAPMAK İYİ OLDU ASLINDA.",
["rb4_sh12_01_01"] = "TAMAM BAIN. BİTİRELİM ŞU BOKTAN İŞİ.",
["rb4_sh12_01_02"] = "BİTİRELİM ŞU İŞİ BAIN.",
["rb4_sh12_01_03"] = "BENİ BURADA İSTEDİN, GELDİM. ŞU İŞİ BİTİRELİM.",
["rb4_sh12_02_01"] = "BU BOKU DÜN GECE HALLETTİM BAIN. BENİ KİM SANIYORSUN LAN?",
["rb4_sh12_02_02"] = "BAK BABA, YAPTIM. ARTIK USLU ÇOCUK OLDUM MU?",
["rb4_sh12_02_03"] = "GEÇTİM. MADALYA FALAN ALACAK MIYIM?",
["rb4_sh12_03_01"] = "KAPIYI GÖRÜYORUM AMA ORADA KAMERA VAR.",
["rb4_sh12_03_02"] = "TAMAM, KAPIYI GÖRÜYORUM AMA KAMERA DA VAR.",
["rb4_sh12_03_03"] = "KAPI BU AMA KAMERA GÖZETLİYOR.",
["rb4_sh12_04_01"] = "SIÇTIK. GENSEC'İN HAKKINI VERMEK GEREK. GÜVENLİ KAPI YAPMAYI GERÇEKTEN BİLİYORLAR.",
["rb4_sh12_04_02"] = "HATIRLADIĞIMDAN DAHA ZORMUŞ.",
["rb4_sh12_04_03"] = "BU KAPI CEHENNEM GİBİ SAĞLAM. GENSEC İŞİNİ BİLİYOR.",
["rb4_sh12_05_01"] = "YAKALADIM SENİ!",
["rb4_sh12_05_02"] = "AL SANA!",
["rb4_sh12_05_03"] = "MIŞIL MIŞIL UYU!",
["rb4_sh12_06_01"] = "HUZUR İÇİNDE YAT.",
["rb4_sh12_06_02"] = "AĞIR OROSPU ÇOCUĞU.",
["rb4_sh12_06_03"] = "LANET OLSUN, AĞIRMIŞ...",
["rb4_sh12_07_01"] = "SİKTİR. BAŞKA BİR KAMERA.",
["rb4_sh12_07_02"] = "LANET OLSUN, BİR KAMERA DAHA.",
["rb4_sh12_07_03"] = "BURADA BAŞKA KAMERA VAR.",
["rb4_sh12_08_01"] = "TAMAM, GÜVENLİK ODASININ DIŞINDAYIM AMA ANAHTAR KARTI LAZIM.",
["rb4_sh12_08_02"] = "BULDUM AMA ANAHTAR KARTI LAZIM.",
["rb4_sh12_08_03"] = "GÜVENLİK ODASININ DIŞINDAYIM AMA ANAHTAR KARTI GEREKİYOR.",
["rb4_sh12_09_01"] = "TAMAM, ANAHTAR KARTINI ALDIM.",
["rb4_sh12_09_02"] = "ANAHTAR KARTI'NI ALDIM.",
["rb4_sh12_09_03"] = "ANAHTAR KARTINI BULDUM.",
["rb4_sh12_10_01"] = "TAMAM, GÜVENLİKÇİYİ HALLETTİM.",
["rb4_sh12_10_02"] = "MUHAFIZ HALLEDİLDİ.",
["rb4_sh12_10_03"] = "GÜVENLİKÇİ ARTIK YOK.",
["rb4_sh12_11_01"] = "TAMAM... LOBİDE DAHA FAZLA MUHAFIZ VAR.",
["rb4_sh12_11_02"] = "TAMAM... DAHA FAZLA GÜVENLİKÇİ GÖRÜYORUM.",
["rb4_sh12_11_03"] = "TAMAM... BİNADA DEVRİYE GEZEN BAŞKA MUHAFIZLARI VAR. BARİZ ZATEN.",
["rb4_sh12_12_01"] = "HEY! SANIRIM GÖRÜYORUM. EVET, ARADIĞIMIZ BİLGİSAYAR O OLMALI. HEM DE YAKINLARDA SANIRIM.",
["rb4_sh12_12_02"] = "BAKALIM BURADA NE VARMIŞ? BİLGİSAYAR O OLMALI. SANIRIM YAKINLARDA.",
["rb4_sh12_12_03"] = "VAY, MERHABA GÜZELİM... BAIN, DİZÜSTÜ BİLGİSAYARI BULDUM. YAKINLARDA OLMALI.",
["rb4_sh12_13_01"] = "SİKTİR, BURADA BİR MUHAFIZ DAHA VAR",
["rb4_sh12_13_02"] = "SİKTİR, BURADA BİR MUHAFIZ VAR.",
["rb4_sh12_13_03"] = "BURADA BİR MUHAFIZ DAHA VAR.",
["rb4_sh12_14_01"] = "BİLGİSAYAR GÖRÜŞ ALANINDA. ODA DA BOŞ GİBİ.",
["rb4_sh12_14_02"] = "BİLGİSAYARI GÖRÜYORUM, MUHAFIZ YOK. ŞANSLI GÜNÜM.",
["rb4_sh12_14_03"] = "İŞTE ORADA, ÜSTELİK KİMSE GÖZLEMİYOR GİBİ. APTAL OROSPU ÇOCUKLARI.",
["rb4_sh12_15_01"] = "TAMAM. ERİŞİM ŞİFRELERİ İŞE YARAMIŞ GALİBA.",
["rb4_sh12_15_02"] = "VAY ODİN'İN SAKALI, GÖRÜNÜŞE GÖRE KODLAR İŞE YARADI.",
["rb4_sh12_15_03"] = "ŞÜKÜRLER OLSUN AMINA KOYAYIM. ERİŞİM ŞİFRELERİ İŞE YARADI.",
["rb4_sh12_16_01"] = "TAMAMDIR, BAIN. BÜTÜN KAYITLAR SİLİNDİ.",
["rb4_sh12_16_02"] = "İŞE YARADI BAIN. CRIME.NET'İN BÜTÜN KAYITLARI SİLİNDİ.",
["rb4_sh12_16_03"] = "İŞE YARADI. BÜTÜN KAYITLAR SİLİNDİ.",
["rb4_sh12_17_01"] = "TAMAM. DIŞARIDAYIM. GİTMEYE HAZIRIZ, DEĞİL Mİ?",
["rb4_sh12_17_02"] = "TAMAM, SAĞ SALİM DIŞARI ÇIKTIM.",
["rb4_sh12_17_03"] = "BAIN, ARTIK DIŞARIDAYIM.",
["rb4_sh12_18_01"] = "BU BOKTAN İŞLERİ YAPTIRIYORSUN, BİR DE FAZLADAN BİRKAÇ CESET TORBASI İÇİN TEŞEKKÜR MÜ BEKLİYORSUN? SİKTİR GİT BAIN.",
["rb4_sh12_18_02"] = "EVET, EVET.",
["rb4_sh12_18_03"] = "ÇOK NAZİKSİN BAIN. GERÇEKTEN.",
["rb4_sh21_01_01"] = "BU DAHA ÇOK BENİM TARZIM.",
["rb4_sh21_01_02"] = "BU PİSLİKLERİ İNDİRME VAKTİ.",
["rb4_sh21_01_03"] = "ROCK'N ROLL, BEBEĞİM.",
["rb4_sh21_02_01"] = "AH, EVET. BUNU ALIYORUM.",
["rb4_sh21_02_02"] = "İŞTE BU AMINA KOYAYIM. BU BENİM.",
["rb4_sh21_02_03"] = "SÜPER, BUNU KENDİME ALIYORUM.",
["rb4_sh21_03_01"] = "HASSİKTİR BAIN. HÂLÂ SÜREKLİ SIKIŞAN BU BOKTAN MATKAPLARI MI KULLANIYORUZ?",
["rb4_sh21_03_02"] = "LANET OLSUN BAIN. SIKIŞMAYAN BİR MATKABA PARAMIZ YETMİYOR MU?",
["rb4_sh21_03_03"] = "SİKTİR. MATKAP SIKIŞTI. RESMEN DEJAVU.",
["rb4_sh21_04_01"] = "HEPSİ İŞİN BİR PARÇASI, DEĞİL Mİ?",
["rb4_sh21_04_02"] = "BENİMLE UĞRAŞMAK İSTİYORLARSA BEN DE ONLARLA UĞRAŞIRIM!",
["rb4_sh21_04_03"] = "TAMAM, O ZAMAN YAPALIM!",
["rb4_sh21_05_01"] = "SİKTİR, DAHA FAZLA POLİS!",
["rb4_sh21_05_02"] = "SİKTİR! HER YERDE DOMUZ VAR. ATEŞ EDE EDE ÇIKMAM GEREKECEK.",
["rb4_sh21_05_03"] = "SİKTİR, HER YER POLİS. ATEŞ EDEREK ÇIKACAĞIM GALİBA.",
["rb4_sh21_06_01"] = "GERÇEKTEN BAŞARISIZ OLACAĞIMI MI SANDIN?",
["rb4_sh21_06_02"] = "HADİ AMA, BU BOKU HALLEDEMEYECEĞİMİ GERÇEKTEN DÜŞÜNDÜNÜZ MÜ?",
["rb4_sh21_06_03"] = "ÇOCUK OYUNCAĞI. BU OYUNU HÂLÂ OYNAYABİLDİĞİMİ GÖRMÜŞSÜNDÜR ARTIK, DEĞİL Mİ BAIN?",
["rb4_sh22_01_01"] = "SİKTİR, BİRİMİZ YAKALANIP GÖZALTINA ALINDI! BAIN, YENİ ARAÇ LAZIM! HEMEN!",
["rb4_sh22_01_02"] = "SİKTİR, BİRİMİZ YAKALANIP GÖZALTINA ALINDI! YENİ KAÇIŞ PLANI GEREK!",
["rb4_sh22_01_03"] = "LANET OLSUN, BİRİMİZ YAKALANIP GÖZALTINA ALINDI! BAIN, YENİ KAÇIŞ ARACI LAZIM!",
["rb4_sh22_02_01"] = "İŞTE GELİYORLAR! AĞIZLARINA SIÇIN!",
["rb4_sh22_02_02"] = "DOMUZLAR OLAY YERİNDE! ONLARI EMEKLİ EDİN!",
["rb4_sh22_02_03"] = "BU DOMUZCUKLARI PASTIRMAYA ÇEVİRİN!",
["rb4_sh22_03_01"] = "BUNU HALLETSEN İYİ OLUR BAIN. BU ACEMİ İŞİ GÖREV YÜZÜNDEN ADAMLARIMDAN BİRİNİ KAYBETMEYECEĞİM.",
["rb4_sh22_03_02"] = "ANLAŞMAYI HALLETSEN İYİ OLUR BAIN. BU KÜÇÜK SINAMAN YÜZÜNDEN ARKADAŞLARIMDAN BİRİNİ KAYBETMEYECEĞİM AMINA KOYAYIM.",
["rb4_sh22_03_03"] = "NASIL GİDİYOR? YEMİN EDERİM BAIN, ŞU ANLAŞMAYI YAPSAN İYİ OLUR. SIRF BENDE HÂLÂ İŞ VAR MI DİYE MERAK ETTİN DİYE ARKADAŞLARIMDAN BİRİNİN HAPSE GİRMESİNE GÖZ YUMMAM.",
["rb4_sh22_04_01"] = "O KALKANIN GÖTÜNÜ KURTARACAĞINI MI SANIYORSUN?",
["rb4_sh22_04_02"] = "KALKAN KULLANAN KORKAK POLİS!",
["rb4_sh22_04_03"] = "HADİ O ZAMAN ÖDLEK!",
["rb4_sh22_05_01"] = "TABİİ HÂLÂ FORMDAYIM. BİR DAHAKİNE DAHA ÇOK PARA GETİREN BİR İŞ VERSEN İYİ OLUR.",
["rb4_sh22_05_02"] = "BİZDEN ŞÜPHELENDİĞİN İÇİN HIYARSIN AMA BİZE BOL PARALI BİR SOYGUN BUL, BUNU UNUTALIM.",
["rb4_sh22_05_03"] = "EVET EVET, BİZİ ZENGİN EDECEK İYİ BİR SOYGUN HAZIRLA YETER.",
["rb5_bph_intro_01c"] = "LANET LOCKE, HEP EĞLENCEYİ BOZACAK.",
["rb5_bph_intro_01g"] = "TAMAM OTUZBİRCİLER. BUNU PATRON İÇİN YAPIYORUZ.",
["rb5_bph_intro_02b"] = "UMARIM O BOKTAN HAİN KENTO YUKARIDADIR. GERÇEKTEN UMARIM.",
["rb5_bph_intro_03b"] = "BÜTÜN BUNLAR DAHA ÖNCE DE OLDU. VAY AMINA KOYAYIM.",
["rb5_bph_intro_03f"] = "SİKTİĞİMİN OTUZBİRCİLERİNİN AKINCILARI.",
["rb5_bph_intro_04a"] = "HAY SİKEYİM. BURANIN HAVASI...",
["rb5_hb1_01_01"] = "HASSİKTİR. KULAKLARIM SİKİLDİ. O C4 MÜYDÜ, YIKIM PATLAYICISI MI?",
["rb5_hb1_01_02"] = "VAY AMINA KOYAYIM, GİRİŞ DEDİĞİN BÖYLE OLUR.",
["rb5_hb1_01_03"] = "CHURCHİLL'DEN ALINTI YAPAYIM: 'HASSİKTİR, NE GÜRÜLTÜYDÜ.'",
["rb5_hb1_01_04"] = "SİKTİR, NE PATLAMAYDI!",
["rb5_hb1_01_05"] = "YAN YAN SİKSİNLER BENİ, BU SİKTİĞİMİN PAYDAY GANG'İ!",
["rb5_hb1_01_06"] = "İKİNİZİ TANIYORUM DA BENİM ESKİ LANET MASKEM NEREDE!?",
["rb5_hb1_01_07"] = "SİZİ LANET OTUZBİRCİLER, HİÇ ACELE ETMEDİNİZ, DEĞİL Mİ!",
["rb5_hb1_01_08"] = "EVET! EVET! ARTIK KASKLARIN UÇUŞUNU GÖRME VAKTİ!",
["rb5_hb1_02_01"] = "BAIN NE DÜŞÜNÜYORDU BİLMİYORUM AMA YOLU UZATIYORUZ. AKLIMDA BİR ŞEY VAR.",
["rb5_hb1_02_02"] = "GÜVENLİ EVİ SİKTİR EDİN. BAŞKA YERE GİDİYORUZ. BANA GÜVENİN.",
["rb5_hb1_02_03"] = "SİKTİĞİMİN GÜVENLİ EVİNİ BOŞ VERİN. BİR PLANIM VAR. SİZ DE BANA YARDIM ETMEK İSTİYORSUNUZ, DEĞİL Mİ ÇOCUKLAR?",
["rb5_hb1_02_04"] = "HAPİSTE UZUN SÜRE KALDIM OTUZBİRCİLER, HALLETMEM GEREKEN İŞLER VAR.",
["rb5_hb1_02_05"] = "SİZİ AMCIKLAR, BEN TATİLDEYKEN AKLINIZI MI YİTİRDİNİZ? NE YAPTIĞIMI BİLİYORUM.",
["rb5_hb1_03_01"] = "BANA TUZAK KURULDU ÇOCUKLAR. BİLİYORUM. BİRİ ÖTTÜ. ",
["rb5_hb1_03_02"] = "BENİ FEDERALLERE BİR AMCIK SATTI, BEYLER. EMİNİM.",
["rb5_hb1_03_03"] = "BİRİNİN BANA İHANET ETTİĞİNDEN EMİNİM. BİR MUHBİR OLMALI. AMA KİM?",
["rb5_hb1_03_04"] = "BİR HAİN VAR. EKİBE YAKIN. YA DA İÇİMİZDE. VAR, BİLİYORUM.",
["rb5_hb1_03_05"] = "BİR BOK TORBASI BENİ İSPİYONLADI. KİM BİLMİYORUM AMA EMİNİM.",
["rb5_hb1_03_06"] = "JUDAS KILIKLI BİR SİKİK BENİ SATTI. BİLİYORUM. AMA KİM?",
["rb5_hb1_03_07"] = "İHANETE UĞRADIĞIMI BİLİYORUM. BUNU YAPANI BULACAĞIM.",
["rb5_hb1_03_08"] = "BİRİ BENİ İSPİYONLADI! MATT OLMADIĞINI BİLİYORUM. ARTIK ONUN BÜTÜN SIRLARINI ÖĞRENDİM.",
["rb5_hb1_03_09"] = "OROSPUNUN BİRİ İSPİYONLAMIŞ! KİM OLDUĞUNU BULMALIYIM.",
["rb5_hb1_04_01"] = "O BOK ÇUKURUNDAN ÇIKTIĞIMA SEVİNDİM. LANET HAZELTON. DÜZGÜN BİR İNGİLİZ BEYEFENDİSİNE GÖRE YER DEĞİL, ANLIYOR MUSUN? ",
["rb5_hb1_04_02"] = "BEN YOKKEN NELER KAÇIRDIM BAKALIM? ",
["rb5_hb1_04_03"] = "İLK HAPİSLİĞİMİ STRANGEWAYS'TE GEÇİRDİM. SONUNCUYU DA AZ ÖNCE BİTİRDİM. GERİ DÖNMEYECEĞİM ÇOCUKLAR.",
["rb5_hb1_04_04"] = "WEDNESDAY NASIL GİDİYOR? İÇERİDE DUYDUĞUMUZ TEK ŞEY HOKEY HABERLERİYDİ. KIZ OYUNU.",
["rb5_hb1_04_05"] = "İKİNCİ OLARAK ADAM GİBİ BANYO İSTİYORUM. ÜÇÜNCÜ, BİRA. DÖRDÜNCÜ, GENELEV. AMA ÖNCE... SÜRMEYE DEVAM.",
["rb5_hb1_04_06"] = "HAY AMINA KOYAYIM, ÇOCUKLAR. DÜRÜST BİR HAYATA DÖNMEYİ DÜŞÜNÜN. PERŞEMBELERİ HAZELTON'DA OLMAK İSTEMEZSİNİZ. İKİ KELİME: SAPIK GECESİ.",
["rb5_hb1_04_07"] = "ORADA DOĞRU DÜZGÜN ÇAY BULAMADIM. HEP YEŞİL ÇAY VE EARL GREY ZIRVALARI. ALTIN NEREDE!",
["rb5_hb1_04_08"] = "GERİDE BIRAKTIĞIM KAHPELERİ ÖZLEYECEĞİM. MİCKEY THE SQUİB. DİRTY ALAN. FİSH FİNGERS. İYİ ÇOCUKLARDI.",
["rb5_hb1_04_09"] = "BİRİ BANA HAZELTON'DAKİ KAHPELERE BİRKAÇ PAKET SİGARA GÖNDERMEYİ HATIRLATSIN. MUHAFIZLARA DA BOKTAN BİR PASTA. OTUZBİRCİLER.",
["rb5_hb1_04_10"] = "O GÖT ROSCOE'YA SAĞLAM BİR DAYAK ATMAYI ÖZLEYECEĞİM. BELKİ ONU DA KAÇIRIRIZ?",
["rb5_hb1_04_11"] = "DIŞARIDA OLMAK GÜZEL. TEMİZ HAVA, KUŞLAR... MERMİLER, PATLAMALAR VE BÜTÜN O BOKLAR.",
["rb5_hb1_04_12"] = "EN AZINDAN HAPİSTEYKEN BAIN MUHTAÇ KÜÇÜK KÖPEK GİBİ KULAĞIMDA HAVLAMIYORDU. MATKABI ALMIŞ, KIÇIMA AL.",
["rb5_hb1_04_13"] = "İTİRAF EDİN. SİZİ OTUZBİRCİLER, O GÜZEL İNGİLİZ AKSANIMI ÖZLEDİNİZ. DEĞİL Mİ? ÖZLEDİNİZ Mİ? OTUZBİRCİLER.",
["rb5_hb1_04_14"] = "HAPİSHANE YEMEKLERİNİ ÖZLEMEYECEĞİM, ONU SÖYLEYEYİM. SANKİ KİREMİDİN ÜSTÜNDE BOK YEDİK.",
["rb5_hb1_04_15"] = "DALLAS, HANGİ CEHENNEMDEYDİN? LANET KULEDE PRENSES GİBİ BEKLİYORDUM.",
["rb5_hb1_04_16"] = "DALLAS, DOSTUZ SANIYORDUM. İNSAN EN YAKIN ARKADAŞINI HAPİSTE BIRAKIR MI? OTUZBİRCİ.",
["rb5_hb1_04_17"] = "CHAINS, SANA GÜVENEBİLİRİM SANMIŞTIM! OTUZBİRCİ.",
["rb5_hb1_04_18"] = "KAÇ KERE KIÇINI KURTARDIM BİLMİYORUM CHAINS, KARŞILIĞINI BÖYLE Mİ VERİYORSUN? EN AZINDAN LİMUZİN BULABİLİRDİN.",
["rb5_hb1_04_19"] = "WOLF, YILLARDIR YANLIŞ AĞACA HAVLIYORSUN! SONUNDA BENİ BULDUN!",
["rb5_hb1_04_20"] = "WOLF, ARKADA O BULLDOZER'A YAPTIĞIN BİRAZ... BENCE YARDIM LAZIM DOSTUM.",
["rb5_hb1_04_21"] = "VAY VAY VAY, DÖRDÜNCÜ SİLAHŞOR KİMMİŞ? BU OTUZBİRCİ SENİN KÜÇÜK KARDEŞİN Mİ DALLAS?",
["rb5_hb1_04_22"] = "KENDİNE HOXTON DİYORSUN, HA? DAHA ÇOK HOUSTON, ÇÜNKÜ ARTIK BÜYÜK BİR SORUNUN VAR.",
["rb5_hb1_04_23"] = "DALLAS, KÜÇÜK KARDEŞİN ADIMI GERİ VERSİN DE KENDİNE HOUSTON DESİN.",
["rb5_hb1_04_24"] = "VAY ANASINI, JOHN WICK. YÜZÜNÜ BİR DAHA GÖRECEĞİMİ SANMIYORDUM.",
["rb5_hb1_04_25"] = "BENİ YANLAMASINA SİKSİNLER, JOHN WICK GELMİŞ. SEN BIRAKMAMIŞ MIYDIN? AİLE NASIL? NE OLDU, KÖTÜ BİR ŞEY Mİ SÖYLEDİM?",
["rb5_hb1_05_01"] = "ÖDEME GÜNÜ GELDİ DEDİM OROSPU ÇOCUKLARI!",
["rb5_hb2_01_01"] = "İLERLEYİN! SON GİREN SÜBYANCI!",
["rb5_hb2_01_02"] = "İÇERİ GİRİN ÇOCUKLAR! YAPACAK İŞ VAR.",
["rb5_hb2_01_03"] = "HIZLANIN ÇOCUKLAR. ÇABUK OLUN AMINA KOYAYIM!",
["rb5_hb2_02_01"] = "OPERASYON ODASI'NI BULMALIYIZ. GEREKEN BİLGİYİ ORADA BULACAĞIZ.",
["rb5_hb2_02_02"] = "İLK DURAK OPERASYON ODASI. FEDERALLERİN SİNİR MERKEZİ. GEREKENİ ORADA BULABİLİRİZ.",
["rb5_hb2_02_03"] = "İLK DURAĞIMIZ OPERASYON ODASI. GEREKENİ ORADAN BULABİLMELİYİZ.",
["rb5_hb2_03_01"] = "BURADA! O SUNUCUYA GEÇİYORUM. GÖRDÜĞÜNÜZ SON PİÇE KADAR HERKESİ ÖLDÜRÜN!",
["rb5_hb2_03_02"] = "İŞTE BURASI. TAMAM, O SUNUCULARA ERİŞMEM LAZIM. ODAYI TEMİZLEYİN!",
["rb5_hb2_03_03"] = "GELDİK! SUNUCUYA ULAŞMAM GEREK. ŞU FEDERALLERİ İNDİRİN.",
["rb5_hb2_04_01"] = "TAMAM, İÇERİDEYİM. BU SUNUCULAR ÜZERİNDE ÇALIŞACAĞIM. BENİ KORUYUN!",
["rb5_hb2_04_02"] = "İÇERİDEYİM. ÇALIŞIRKEN O PİÇLERİ BENDEN UZAK TUTUN.",
["rb5_hb2_04_03"] = "ÇALIŞIRKEN BENİ KORUYUN!",
["rb5_hb2_05_01"] = "SIÇTIK! UFAK BİR SORUN VAR, SUNUCU AĞIR ŞİFRELİ. ŞİFRELEME ANAHTARLARI GÜVENLİK OFİSİNDE TUTULUYOR. ALIP BURAYA GETİRMENİZ GEREK!",
["rb5_hb2_05_02"] = "AH SİKTİR. SUNUCUNUN HER YANI ŞİFRELİ. ŞİFRE ANAHTARLARI GÜVENLİK OFİSİNDE OLMALI. ORAYA GİDİN, ALIN VE BURAYA GETİRİN.",
["rb5_hb2_05_03"] = "UFAK BİR SORUNUMUZ VAR ÇOCUKLAR. SUNUCU ŞİFRELEMEYLE İYİCE SİKİLMİŞ. KIRMASI ÇOK UZUN SÜRER, ŞİFRELEME ANAHTARLARI LAZIM. GÜVENLİK OFİSİNDE BİRKAÇ TANE OLMALI.",
["rb5_hb2_06_01"] = "SİKTİR, GÖRÜŞME DOSYALARINA ERİŞEMİYORUM. BİZZAT FBI DİREKTÖRÜNDEN ONAY GEREKİYOR. OFİSİNİ BULUN. YERİNE GEÇEBİLİYOR MUSUNUZ BAKIN.",
["rb5_hb2_06_02"] = "AH, SIÇTIK. BU İFADE DOSYALARI KİLİTLİ. YALNIZCA MÜDÜRÜN KENDİSİNİN ONAYIYLA AÇILABİLİR. HAY SİKEYİM, BU EN TEPEYE KADAR GİDİYOR. BİR GÜNLÜĞÜNE KRAL OLMAK İSTEYEN VAR MI?",
["rb5_hb2_06_03"] = "AH, LANET OLSUN. BAZI SORGU DOSYALARI KİLİTLİ. ONAY GEREKİYORMUŞ... HASSİKTİR, BİZZAT MÜDÜRDEN. BU KÖSTEBEK HER KİMSE SAĞLAM BAĞLANTILARI VAR. MÜDÜRÜN OFİSİNE GİDİN!",
["rb5_hb2_07_01"] = "TAMAM, GİRDİNİZ! GÜVENLİK YETKİSİ TALEBİ YOLLADIM. ONAYLAMANIZ GEREKİYOR.",
["rb5_hb2_07_02"] = "GİRDİNİZ. HAH! ŞİFRESİ İHEARTRAİNBOWS44'MÜŞ. TALEPLER YOLDA. ONAYLAYIN!",
["rb5_hb2_07_03"] = "TAMAM, GİRDİNİZ. LANET FBI'IN SİKTİĞİMİN MÜDÜRÜNÜN BİLGİSAYARINA ERİŞİMİNİZ VAR! İSTEĞİ ONAYLAYIN.",
["rb5_hb2_08_01"] = "SAKİN OL YETER. İMZALAMAN GEREKEN BÜTÜN DOSYALARI BULAYIM.",
["rb5_hb2_08_02"] = "SAKİN OLUN ÇOCUKLAR. ONAYLAMANIZ İÇİN BÜTÜN DOSYALARI BULMAM LAZIM.",
["rb5_hb2_08_03"] = "BEKLEYİN BEYLER. DOSYALARI BULUYORUM.",
["rb5_hb2_09_01"] = "TAMAM, ONAYLAMANIZ GEREKEN BİR İSTEK DAHA!",
["rb5_hb2_09_02"] = "PEKÂLÂ, İSTEĞİ ONAYLAYIN YETER. HAY SİKEYİM, İŞİ NE KOLAYMIŞ.",
["rb5_hb2_09_03"] = "ONAYLAMAN İÇİN BİR İSTEK DAHA.",
["rb5_hb2_10_01"] = "HARİKA, İHTİYACIM OLAN BÜTÜN GİZLİ DOSYALARA ERİŞİMİM VAR! BURAYA DÖNÜN DE GÖSTERİ DEVAM ETSİN!",
["rb5_hb2_10_02"] = "SINIRSIZ ERİŞİM. İŞTE BU AMINA KOYAYIM! ŞİMDİ BURAYA DÖNÜN. DEVAM EDELİM.",
["rb5_hb2_10_03"] = "ARTIK BİR TON YERE ERİŞİMİMİZ VAR. BURAYA DÖNÜN. DAHA İŞİMİZ VAR.",
["rb5_hb2_11_01"] = "TAMAM, BİRKAÇ DOSYA EKSİK. TANIK İFADELERİ, ARŞİVDE TUTULUYOR. O DOSYALARI GETİRİN!",
["rb5_hb2_11_02"] = "SİKTİR. SUNUCULARDA OLMAYAN BİRKAÇ DOSYA LAZIM. ARŞİVLERDE TUTULAN TANIK İFADELERİ. ORAYA GİDİN.",
["rb5_hb2_11_03"] = "TAMAM, BİRKAÇ TANIK İFADESİ EKSİK GALİBA. KÂĞIT KOPYALARINA BAKMAMIZ GEREK. ARŞİVE GİDİP ALIN.",
["rb5_hb2_12_01"] = "UFAK BİR AKSAKLIK, BURADA BİR SUNUCU EKSİK. KAYDA GÖRE BAKIM İÇİN BİLİŞİM BÖLÜMÜNE GÖTÜRÜLMÜŞ. O SUNUCU LAZIM, GERİ GETİRMENİZ GEREKECEK.",
["rb5_hb2_12_02"] = "TAŞAK MI GEÇİYORSUNUZ LAN? BİR SUNUCU EKSİK. KAYITLARDA BAKIM İÇİN BİLİŞİM BÖLÜMÜNE GÖTÜRÜLDÜĞÜ YAZIYOR. O SUNUCU BİZE LAZIM.",
["rb5_hb2_12_03"] = "AH, YAPMAYIN! BİR SUNUCU EKSİK. KAYITLARA GÖRE BİLİŞİME GÖTÜRÜLMÜŞ. ORAYA GİDİP ALIN.",
["rb5_hb2_13_01"] = "BURADAKİ DOSYALARDA, HAİNLE BAĞLANTILI ADLİ DELİL OLDUĞU YAZIYOR. LABORATUVARLARA GİDİP YAKINDAN BAKIN.",
["rb5_hb2_13_02"] = "İLGİNÇ. BU SUNUCUDAKİ DOSYALAR ADLİ TIPTA TUTULAN BİR DELİLİ İŞARET EDİYOR. BİR BAKALIM.",
["rb5_hb2_13_03"] = "VAY AMINA KOYAYIM, BURADAKİ DOSYALAR AŞAĞIDAKİ LABORATUVARLARDA BULUNAN FİZİKSEL KANITLARA BAĞLANIYOR. İNİN, BİR BAKIN!",
["rb5_hb2_14_01"] = "TAMAM, BULDUĞUM BÜTÜN BİLGİYİ BU SUNUCUYA KOPYALADIM. SUNUCUYU ALIN DA ÇIKALIM BURADAN.",
["rb5_hb2_14_02"] = "PEKÂLÂ. SİKERLER. GEREKEN BÜTÜN İSTİHBARATI SUNUCULARDAN BİRİNE TOPLADIM. BİRİ ALSIN DA TÜYELİM.",
["rb5_hb2_14_03"] = "BURADA YAPABİLECEĞİMİZ BU KADAR. BÜTÜN İSTİHBARATI BU SUNUCUYA KAYDETTİM. ALIN, ÇIKALIM DA ŞU İŞİ ÇÖZMEYE BAKALIM. ",
["rb5_hb2_15_01"] = "HADİ OTUZBİRCİLER. ELEKTRİĞİ YENİDEN AÇIN.",
["rb5_hb2_15_02"] = "HAY SİKEYİM! ÇOCUKLAR! ELEKTRİK!",
["rb5_hb2_15_03"] = "MİLLET, ELEKTRİK OLMADAN GEREKEN İŞİ YAPAMAM. DÜZELTİN AMINA KOYAYIM!",
["rb5_hb2_16_01"] = "ELEKTRİK GELDİ AMA BURADAKİLERİ YENİDEN BAŞLATMAM GEREK. SAKİN OLUN.",
["rb5_hb2_16_02"] = "ELEKTRİK GELDİ BEYLER. YENİDEN BAŞLATMAK İÇİN BİRAZ ZAMAN LAZIM.",
["rb5_hb2_16_03"] = "TAMAM, YİNE ÇALIŞIYORUZ. DAYANIN YETER.",
["rb5_hb2_17_01"] = "TAMAM, YENİDEN ÇALIŞIYORUM AMA ŞU LANET ELEKTRİĞİ AÇIK TUTUN.",
["rb5_hb2_17_02"] = "İŞE DÖNÜYORUZ. BUNDAN SONRA ONLARI UZAK TUTUN.",
["rb5_hb2_17_03"] = "GÜZEL. AMA ŞU OTUZBİRCİLERİ ELEKTRİKTEN UZAK TUTMAYA ÇALIŞIN, OLUR MU?",
["rb5_hb2_18_01"] = "TAMAM, DAVA DOSYAMI BULDUM, İNCELİYORUM.",
["rb5_hb2_18_02"] = "DOSYAMI ALDIM. BAKALIM HAKKIMDA NELER BİLİYORLAR.",
["rb5_hb2_18_03"] = "DOSYAMA GİRDİM. BAKALIM BU AMCIKLAR NE TOPLAMIŞ.",
["rb5_hb2_19_01"] = "HAY SİKEYİM, BURADA \"GİZLİ MUHBİR\" DİYE BİR KAYIT VAR. BİLİYORDUM. KAZMAYA DEVAM EDECEĞİM.",
["rb5_hb2_19_02"] = "BU NE? BURADA \"GİZLİ MUHBİR\"DEN SÖZ EDİLİYOR. BİLİYORDUM LAN!",
["rb5_hb2_19_03"] = "BAKALIM. İŞTE! \"GİZLİ MUHBİR\"! BURNUMA SIÇAN KOKUSU GELDİĞİNİ BİLİYORDUM.",
["rb5_hb2_20_01"] = "SIRADAN BİR DOSYA DEĞİL BU. BİR SÜRÜ BİLGİ KISITLI. BU KADAR ÖNEMLİ DEĞİLİM, DEĞİL Mİ?",
["rb5_hb2_20_02"] = "BU DAVA ÖZEL. BEN NEDEN ÖZELİM? BUNLARI KİM SIZDIRIYOR?",
["rb5_hb2_20_03"] = "SİKTİR, ÇOK AYRINTILIYMIŞ. BİZİ KİM İSPİYONLUYORSA... YAKINIMIZDAN BİRİ.",
["rb5_hb2_21_01"] = "DOSTUM, BU DOSYA BENDEN ÇOK DAHA FAZLASINI KAPSIYOR. HEPİNİZLE İLGİLİ BİLGİLER VAR. AMA İSİM YOK. SANIRIM MUHBİR ONLARI KENDİNE SAKLIYOR.",
["rb5_hb2_21_02"] = "HER ŞEY ELLERİNDE. HER SOYGUN, HER İŞ. SİZDEN DE BAHSEDİYORLAR. AMA İSİM YOK. HAİN ONLARI KENDİNE SAKLIYOR HERHÂLDE.",
["rb5_hb2_21_03"] = "NE OLUYOR LAN. BU DOSYA DEVASA. HAKKIMDA HER ŞEYİ BİLİYORLAR. SİZDEN DE BAHSEDİLİYOR! İSİM YOK, BELKİ MUHBİR DAHA İYİ FİYAT BEKLİYOR, SİKEYİM.",
["rb5_hb2_22_01"] = "BURADA İŞİM BİTMEK ÜZERE. GÜVENLİ EVE DÖNÜNCE İNCELEYECEK BİR SÜRÜ BİLGİ OLACAK AMA O SİKİK MUHBİRİ BULACAĞIZ. HEPİNİZİ ELE VERMEDEN O AMCIĞI ÇİVİLEYECEĞİZ.",
["rb5_hb2_22_02"] = "TAMAM, BURADA TOPARLIYORUM, NEREDEYSE BİTTİ. AYIKLANACAK ÇOK BİLGİ OLACAK. AMA O GÖTÜ BULACAĞIZ. ÖTMEDEN SUSTURACAĞIZ.",
["rb5_hb2_22_03"] = "BURADA DAHA FAZLA BİR ŞEY YAPAMAM, NEREDEYSE BÜTÜN İSTİHBARATI İNCELEDİM. GÜVENLİ EVE DÖNÜNCE TÜM PARÇALARI BİRLEŞTİRMEMİZ GEREKECEK. O HAİNİ YAKALADIĞIMIZDA PİÇ ÖLECEK.",
["rb5_hb2_23_01"] = "SİZ DÖNENE KADAR BURADA SESSİZ KALACAĞIM.",
["rb5_hb2_23_02"] = "BURADA GÖZE BATMAMAYA ÇALIŞACAĞIM.",
["rb5_hb2_23_03"] = "SİZ DÖNENE KADAR KİLİSE FARESİ GİBİ SESSİZ OLACAĞIM.",
["rb5_hb2_24_01"] = "İŞE DÖNELİM, BENİ KORUYUN.",
["rb5_hb2_24_02"] = "İŞE KOYULACAĞIM. BENİ KORUYUN!",
["rb5_hb2_brf_01_01"] = "PEKÂLÂ ÇOCUKLAR, BENİ ÇIKARDIĞINIZ İÇİN SAĞ OLUN. AMA EN BAŞTA ORAYA GİRMEMELİYDİM. BİRİ BANA TUZAK KURDU. EMİNİM. FEDERALLER HAKKIMDA ÇOK ŞEY BİLİYORDU. O CİMRİ OTUZBİRCİLERİN EŞELEYİP ÇIKARABİLECEĞİNDEN ÇOK DAHA FAZLASINI. BİRİ ÖTTÜ. BİRİ BENİ SİKTİ. KİM OLDUĞUNU DA BULACAĞIM.$NL;$NL;KOLAY OLMAYACAK. KENARDAN DOLANIP BOŞ İŞLERLE UĞRAŞMAK YOK, TAMAM MI? GİZLİ ANLAŞMALAR, BAĞLANTILAR, O SAÇMALIKLAR YOK. DOĞRUDAN KAYNAĞA GİDİYORUZ. FBI'IN EN BÜYÜK YUVASINA. BENİ KİMİN KAZIKLADIĞINI BULACAĞIZ.",
["rb5_hb2_end_01_01"] = "AFERİN. İNCELEMEMİZ GEREKEN BİR TON BİLGİ VAR. O SIRTIMIZDAN BIÇAKLAYAN OTUZBİRCİYİ BULMAYA YETER.$NL;$NL;VAY AMINA KOYAYIM, BİRİNİN BENİ SATTIĞINA İNANAMIYORUM. SİZİ DE BU İŞE ÇEKMEYE HAZIRLAR. O SIÇANI HALLEDECEĞİZ. HABERLEŞİRİZ.",
["rb5_hb2_end_01_02"] = "SAĞ OLUN MİLLET, DÖNDÜĞÜME SEVİNDİM. İNCELEMEM GEREKEN BİR BOK YIĞINI İSTİHBARAT VAR. UMARIM BENİ İSPİYONLAYAN, SIRTIMDAN BIÇAKLAYAN O AMCIĞI BULMAMIZA YETER.$NL;$NL;HIRSIZLARIN KURALI FALAN YOK MU? PAYLAŞMAYA DEĞER BİR ŞEY BULUNCA SİZE SÖYLERİM. O OTUZBİRCİYİ BULACAĞIZ. BULUNCA PAYDAY GANG'E BULAŞTIĞINA PİŞMAN OLACAK.",
["rb5_hb2_end_01_03"] = "BU BİLGİLERİN HEPSİNİ, UĞRUNDA ÖLSEM DE İNCELEYECEĞİM. BANA, BİZE TUZAK KURANI BULACAĞIM. O SİKİKLE GEREKTİĞİ GİBİ İLGİLENECEĞİZ. BUNLARI İNCELEMEM İÇİN BİRAZ ZAMAN VERİN, SİZE PİÇİN ADIYLA DÖNERİM.",
["rb5_hb2_intro_01_01"] = "GİRİŞ ORADA. NAZLANMAYIN, O ÖN KAPIYI YIKIN!",
["rb5_hb2_intro_01_01b"] = "ÇOK İYİYMİŞ AMINA KOYAYIM.",
["rb6_spa_cbf_01"] = "TAMAM... CHARON'I ÇIKARALIM. BU BENİM İÇİN KİŞİSEL, O YÜZDEN UYANIK OLALIM.",
["recoil_multiplier"] = "BU YÜKSELTME, ATEŞ EDERKEN OLUŞAN GERİ TEPMEYİ AZALTIR.$NL;BÖYLECE ART ARDA NİŞANLI ATIŞLAR YAPMAK KOLAYLAŞIR.",
["reload_speed_multiplier"] = "BU YÜKSELTME, SİLAHIN DOLDURMA SÜRESİNİ KISALTIR.$NL;YOĞUN ÇATIŞMA ANLARINDA İŞE YARAR.",
