["rt1_hm2_01_02"] = "BÜYÜK PATRON ÇOK KIZGIN.",
["rt1_hm2_01_03"] = "RUSLAN O KOKAİNİ NEHRE DÖKTÜĞÜNDEN BERİ PATRONU BU KADAR SİNİRLİ GÖRMEMİŞTİM.",
["rt1_hm2_02_01"] = "BOŞ VER ONU. BU SANDIKLARI AÇACAK MIYIZ? ",
