["rt1_hm2_04_03"] = "KİM OLDUKLARI ÖNEMLİ DEĞİL. PATRON KELLELERİNE BÜYÜK PARA VERİYOR. BEN ALMAYI DÜŞÜNÜYORUM.",
["rt1_hm2_05_01"] = "SİKTİR ET ONU! ONLARI DA SİKTİR ET! BIRAK GELSİNLER DİYORUM. BENİM İÇİN KOLAY PARADAN İBARETLER.",
["rt1_hm2_05_02"] = "ANNEN BİR MURMANSK FAHİŞESİNDEN DAHA AZ ŞEY BİLİYOR. DUYSUNLAR. GELSİNLER!",
["rt1_hm2_05_03"] = "ANNEN BACAKLARININ ARASINDAKİNİ KULLANDIĞI KADAR KULAKLARININ ARASINDAKİNİ DE KULLANSAYDI DİNLEYEBİLİRDİM.",
["rt1_hm2_06_01"] = "KIZIMIN OKULUNDAN TELEFON GELDİ. DERSLERİ EKİYORMUŞ.",
