["sm_10_desc"] = "BİR MAFYA ADAMININ ELİNDE NÜKLEER SAVAŞ BAŞLIKLARI MI? SORMA. VLAD BİR ÜST SEVİYEYE ÇIKMANA YARDIM ETMEYE HAZIR. KARTELLERLE BAĞLANTI KURMANI SAĞLAYABİLECEĞİNİ SÖYLÜYOR AMA FEDERALLER KAYIP SAVAŞ BAŞLIKLARI İÇİN SOKAKLARI DİDİK DİDİK EDİYOR. BIRAK SENİ BULMAK İÇİN DC’Yİ SÖKSÜNLER. VLAD’IN BAŞKA BİR İŞİ VAR VE BU ACİL. LA’E GİT; HIZLI.",
