["sm_12_desc"] = "VLAD O TOZU VERMEDEN ÖNCE BİRAZ GÜVENCE İSTİYOR. PAYDAY GANG ADI YENİ BİR ANLAM TAŞIYOR. ONUN ADINA BİRAZ GÜÇ GÖSTERMEMİZ, RAKİPLERİNE NE KADAR İLERLEDİĞİNİ KANITLAR. BAŞ BELASI, BİLİYORUM AMA BUNDAN SONRA SİZİ KARTELİYLE TANIŞTIRMAYA HAZIR OLACAK. BUNA DEĞER.",
["sm_12_name"] = "KİRAYI ÖDEMEK",
["sm_12_obj"] = "NİGHTCLUB VE STEALING XMAS İŞLERİNİ ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_13_desc"] = "VLAD BİZİ KARTELDEN BİR BAĞLANTIYLA TANIŞTIRDI: HECTOR MORALES. KENDİMİZİ KANITLAYANA KADAR BİZİ İŞLERİNE KATMAYA TAM HAZIR DEĞİL. KÖTÜ ŞÖHRETİMİZİ BÜYÜTMELİYİZ. BİRKAÇ İŞİ DAHA TAMAMLAMANIN ZAMANI. DC’DEKİ HER POLİSİN VE SİYASETÇİNİN DİLİNE ADINIZI DÜŞÜRMEYE YETECEK KADAR. BU İŞ GÖRÜR.",
["sm_13_name"] = "DÜRÜST İŞ",
["sm_13_obj"] = "50. İTİBAR SEVİYESİNE ULAŞ.",
["sm_14_desc"] = "HECTOR BİZİMLE ÇALIŞMAYA HAZIR. LİMANA BÜYÜK BİR KOKAİN SEVKİYATI TAŞIMAK İSTİYOR. ÇOK BÜYÜK BİR SEVKİYAT. MALLA BİRLİKTE KAMYONDA GİTMEMİZİ İSTİYOR. BU KADAR KOKAİNİN HECTOR’I KARTELDE YÜKSELTECEĞİNİ TAHMİN EDİYORUM. ONUNLA YÜKSELMEMİZ İÇİN İYİ FIRSAT.",
["sm_14_name"] = "TERFİ",
["sm_14_obj"] = "WATCHDOGS İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_15_desc"] = "FEDERALLER BİZİ BEKLİYORDU! EKİBİN İÇİNDEN VEYA DIŞINDAN, AMA BİZE YAKIN BİRİ MUHBİR. KİM OLDUĞUNU BULACAĞIZ AMA O ZAMANA KADAR PROFESYONEL KALIYORUZ. HECTOR BAŞKA BİR İŞTE, RAKİPLERİ MENDOZA KARTELİNE DARBE VURMAMIZI İSTİYOR. YAPALIM. BELKİ HAİNİ ORTAYA ÇIKARIR.",
["sm_15_name"] = "ÖDEDİĞİN BEDEL",
["sm_15_obj"] = "FİRESTARTER İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_16_desc"] = "HECTOR’IN, ÜLKEDEN ÇIKARILMAK ÜZERE OLDUKLARINI DÜŞÜNDÜĞÜMÜZ MENDOZA AİLESİNİN İŞİNİ BİTİRMEK İÇİN BİR PLANI VAR. PLANIN BİR PARÇASI COBRA ÇETESİNDEN BİLGİ ALMAK AMA ONLAR PARA DEĞİL, METAMFETAMİN İSTİYOR. HECTOR BUNUN İÇİN KENDİ ADAMLARINI KULLANMAYACAK. O YÜZDEN ANLAŞMAYI BİZ GERÇEKLEŞTİRECEĞİZ. BU İŞ HECTOR’I ZİRVEYE TAŞIYABİLİR; VAKTİMİZE DEĞER.",
["sm_16_name"] = "ÖDEME VAKTİ",
["sm_16_obj"] = "RATS İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_17_desc"] = "PEKÂLÂ, YENİ BİR BAĞLANTIMIZ VAR. KENDİNE THE ELEPHANT DİYEN BİR SİYASETÇİ. İŞ BİRAZ ENDÜSTRİYEL SABOTAJ. ÇOK PARLAK BİR BİLİM İNSANI SOĞUK FÜZYONU ÇÖZMÜŞ. PETROL ŞİRKETLERİNİ DİSKOYLA AYNI MEZARA SOKACAK TÜRDEN TEKNOLOJİ. İKTİDAR SAHİPLERİNİN DE O ŞİRKETLERDE ÇOK PARASI VAR. BU YÜZDEN THE ELEPHANT VE DOSTLARI TEKNOLOJİNİN GÖMÜLDÜĞÜNDEN EMİN OLMAK İSTİYOR. BANA UYAR.",
["sm_17_name"] = "GÜÇ OYUNU",
["sm_17_obj"] = "BIG OIL İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_18_desc"] = "FÜZYON MOTORUNU ORADAN ÇIKARMAK THE ELEPHANT’I MUTLU EDECEK. MUTLU BİR ELEPHANT İSE ÖDEME YAPAN BİR ELEPHANT’TIR. O KADAR MUTLU Kİ BİZE BAŞKA BİR İŞİ VAR. THE ELEPHANT’IN SIRADAKİ HAMLESİ, RAKİPLERİNDEN BİRİNİ DEVRE DIŞI BIRAKMAMIZ. BİZ DE BUNU YAPACAĞIZ.",
["sm_18_name"] = "TAŞLAR TAHTADAN ÇIKIYOR",
["sm_18_obj"] = "FRAMING FRAME İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_19_desc"] = "THE ELEPHANT DAHA ÇOK PERDE ARKASINDA GÜÇ KULLANAN BİRİ. YERLEŞTİRDİĞİ PİYONLAR ÜZERİNDEN ÇALIŞIR; ŞİMDİ BİZDEN İSTEDİĞİ DE BU. DC BELEDİYE BAŞKANLIĞI YARIŞINDA BOB MCKENDRİCK ADLI BİR ADAMI VAR. THE ELEPHANT, KENDİ ADAMININ YARIŞI KAZANACAĞINDAN EMİN OLMAK İSTİYOR.",
["sm_19_name"] = "SUÇLULAR VE YOZLAŞMIŞLAR",
["sm_19_obj"] = "ELECTION DAY İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_1_desc"] = "BU ÇOK ZOR OLMAMALI. MERAK ETME, ARKANI KOLLAYACAĞIM VE HER ADIMI ANLATACAĞIM. HEM BU HAYATA HÂLÂ HAZIR OLDUĞUNDAN EMİN OLMAMA FIRSAT VERİR.",
["sm_1_desc_old"] = "BAŞLAMADAN ÖNCE GEÇMİŞİNİ TEMİZLEMELİYİZ. YANİ FEDERALLERİN SENİN HAKKINDA TOPLADIĞI PİSLİKLERİ SİLMELİYİZ. ŞU ANDA ONLAR İÇİN ÖNEMSİZSİN; PEK ZOR OLMAMALI. MERAK ETME, ARKANI KOLLAYACAĞIM VE HER ADIMI ANLATACAĞIM. HEM BU HAYATA HÂLÂ HAZIR OLDUĞUNDAN EMİN OLMAMA FIRSAT VERİR.",
["sm_1_name"] = "TEMEL BİLGİLER",
["sm_1_obj"] = "THE TUTORİAL HEİST - LOUD SOYGUNUNU TAMAMLA VEYA 10. İTİBAR SEVİYESİNE ULAŞ.",
["sm_1_obj_old"] = "THE TUTORIAL HEISTS SOYGUNLARINI GİZLİ VE ÇATIŞMALI TAMAMLA VEYA 10. İTİBAR SEVİYESİNE ULAŞ.",
["sm_20_desc"] = "İNSANLARIN ELİMİZİ ZORLAMASINI SEVMİYORUM AMA THE DENTIST ADLI BU ADAM, ORTAĞIMIZI GERİ GETİRECEK İMKÂNLARA SAHİP. HOXTON’I HAPİSTEN KAÇIRMAK İSTİYORSAK THE DENTIST’IN KÜÇÜK PLANLARINA UYMALIYIZ. GERÇİ BURADA \"KÜÇÜK\" HİÇ DOĞRU KELİME DEĞİL. BİZDEN \"NEZAKETLE\" İSTEDİĞİ İLK İŞ, ŞİMDİYE KADARKİ EN BÜYÜK İŞİMİZ OLABİLİR. KUSURSUZ BANKA SOYGUNUYLA KENDİMİZİ KANITLAMAMIZI İSTİYOR: BENEVOLENT BANK. HİÇ BAŞARIYLA SOYULMADI. BUNU YAPARSAK HOXTON’I GERİ ALMA FIRSATI İÇİN YARDIM EDECEĞİNİ SÖYLÜYOR. AMA BEDAVAYA DEĞİL. SANIRIM İŞTEN SONRA ONDAN DAHA FAZLASINI DUYACAĞIZ.",
["sm_20_name"] = "BÜYÜK SAHNE",
["sm_20_obj"] = "BİG BANK İŞİNİ ÇOK ZOR VEYA ÜZERİ ZORLUKTA TAMAMLA.$NL;BU GÖREV İÇİN LOBİDEN SOYGUNUN SONUNA KADAR OYNAMALISIN.",
["sm_21_desc"] = "THE DENTIST’IN BİZE BÜYÜK BİR İŞİ VAR AMA ÖNCE HOXTON’I GERİ ALMALIYIZ; EN YÜKSEK GÜVENLİKLİ HAPİSTE. ONA ULAŞMAK, BÖLGE SAVCISINA ULAŞMAK DEMEK. SORUN ŞU Kİ KENDİNE THE COMMİSSAR DİYEN BİR RUS PİSLİĞİ ONU KORUYOR. ÇÖZÜM? THE COMMİSSAR’I ORTADAN KALDIRMAK. SUİKAST GENELLİKLE TARZIMIZ DEĞİLDİR AMA... İSTİSNALAR YAPILABİLİR.",
}
